import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, symlink, rm, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { JSDOM } from 'jsdom';
import { build } from 'esbuild';

const project = resolve(new URL('../', import.meta.url).pathname);
const dom = new JSDOM('<!doctype html><html><body></body></html>', { url: 'http://127.0.0.1/', pretendToBeVisual: true });
for (const key of ['window', 'document', 'HTMLElement', 'HTMLInputElement', 'HTMLSelectElement', 'Event', 'MouseEvent', 'KeyboardEvent', 'Node', 'Element', 'getComputedStyle', 'localStorage', 'sessionStorage']) Object.defineProperty(globalThis, key, { value: (dom.window as any)[key], configurable: true, writable: true });
Object.defineProperty(globalThis, 'navigator', { value: dom.window.navigator, configurable: true });
Object.defineProperty(globalThis, 'requestAnimationFrame', { value: dom.window.requestAnimationFrame.bind(dom.window), configurable: true });
Object.defineProperty(globalThis, 'cancelAnimationFrame', { value: dom.window.cancelAnimationFrame.bind(dom.window), configurable: true });
dom.window.matchMedia = ((query: string) => ({ media: query, matches: query.includes('reduced-motion'), addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {}, dispatchEvent() { return true; }, onchange: null })) as any;
(globalThis as any).IntersectionObserver = class { observe() {} unobserve() {} disconnect() {} };
(globalThis as any).ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
const { createElement, act } = await import('react');
const { createRoot } = await import('react-dom/client');
const { default: chartHandler } = await import('../api/compute-chart.ts');
const { default: dailyHandler } = await import('../api/daily-sky.ts');
process.env.LOCATIONS_DATA_DIR = join(project, 'tests/fixtures/locations');
const { default: locationsHandler } = await import('../api/locations.ts');

// Bundle the actual App and its local modules, defining the same development env used by Vite.
// External package imports resolve through existing installed dependencies; no server or port is used.
const runtime = await mkdtemp(join(tmpdir(), 'astrolove-app-journey-'));
await symlink(join(project, 'node_modules'), join(runtime, 'node_modules'), 'dir');
const output = await build({ absWorkingDir: project, entryPoints: ['src/OfflineApp.tsx'], bundle: true, write: false, platform: 'node', format: 'esm', packages: 'external', loader: { '.css': 'empty' }, define: { 'import.meta.env': JSON.stringify({ DEV: true, MODE: 'development' }) }, jsx: 'automatic', logLevel: 'silent' });
await writeFile(join(runtime, 'app.mjs'), output.outputFiles[0].text);
const { default: App } = await import(pathToFileURL(join(runtime, 'app.mjs')).href);

interface RequestRecord { path: string; body: any; payload?: any; signal?: AbortSignal; released: boolean; release: () => Promise<void> }
const requests: RequestRecord[] = [];
let holdDaily = false;
(globalThis as any).fetch = (path: string, init: RequestInit = {}) => new Promise(resolveFetch => {
  if (path === '/fomalhaut/data/stars.json') {
    void readFile(join(project, 'public/fomalhaut/data/stars.json'), 'utf8').then(raw => resolveFetch({ok:true,json:async()=>JSON.parse(raw)}));
    return;
  }
  const record: RequestRecord = { path: String(path), body: init.body ? JSON.parse(String(init.body)) : undefined, signal: init.signal || undefined, released: false, release: async () => {
    assert.equal(record.released, false); record.released = true;
    const response = { code: 0, payload: undefined as any, setHeader() {}, status(code: number) { this.code = code; return this; }, json(value: any) { this.payload = value; return this; } };
    const handler = record.path === '/api/compute-chart' ? chartHandler : record.path === '/api/daily-sky' ? dailyHandler : record.path === '/api/locations' ? locationsHandler : null;
    assert.ok(handler, `unexpected network request ${record.path}`);
    await handler({ method: init.method || 'GET', body: record.body } as any, response as any);
    record.payload = response.payload;
    resolveFetch({ ok: response.code === 200, status: response.code, json: async () => response.payload });
  } };
  requests.push(record);
  if (record.path !== '/api/daily-sky' || !holdDaily) void record.release();
});
const container = document.body.appendChild(document.createElement('div'));
const root = createRoot(container);
const text = () => container.textContent || '';
const query = (selector: string) => container.querySelector(selector);
const button = (label: RegExp) => { const found = [...container.querySelectorAll('button')].find(b => label.test((b.getAttribute('aria-label') || b.textContent || '').trim())); assert.ok(found, `button ${label}`); return found!; };
function click(node: Element) { act(() => { node.dispatchEvent(new dom.window.MouseEvent('click', { bubbles: true })); }); }
function setValue(node: HTMLInputElement | HTMLSelectElement, value: string) {
  assert.ok(node, 'input exists');
  const proto = node.tagName === 'SELECT' ? dom.window.HTMLSelectElement.prototype : dom.window.HTMLInputElement.prototype;
  act(() => { Object.getOwnPropertyDescriptor(proto, 'value')!.set!.call(node, value); node.dispatchEvent(new dom.window.Event(node.tagName === 'SELECT' ? 'change' : 'input', { bubbles: true })); });
}
async function settle(ms = 20) { await act(async () => { await new Promise(r => setTimeout(r, ms)); }); }
async function waitFor(predicate: () => unknown, message: string, timeout = 3000) {
  const start = Date.now();
  while (!predicate() && Date.now() - start < timeout) await settle(20);
  assert.ok(predicate(), `${message}\nScreen: ${text().slice(-1500)}`);
}
async function launch() { await act(async () => { root.render(createElement(App)); }); await settle(); }
const labelled = (prefix: RegExp) => [...container.querySelectorAll('.birth-form label')].find(l => prefix.test(l.textContent || ''))?.querySelector('input') as HTMLInputElement;
const nav = (label: RegExp) => { const found = [...container.querySelectorAll('nav[aria-label="Navegação principal"] button, nav[aria-label="Primary navigation"] button')].find(b => label.test(b.textContent || '')); assert.ok(found, `navigation ${label}`); return found!; };
async function fillUnknownProfile(name: string, date: string, cityName: string, zone: string) {
  setValue(labelled(/^(Nome|Name)/), name);
  setValue(labelled(/^(Data de nascimento|Birth date)/), date);
  const checkbox = query('.birth-form input[type="checkbox"]') as HTMLInputElement;
  if (!checkbox.checked) click(checkbox);
  const city = query('.birth-form [role="combobox"]') as HTMLInputElement;
  act(() => city.focus()); setValue(city, cityName);
  await waitFor(() => [...container.querySelectorAll('[role="option"]')].some(o => o.textContent?.includes(zone)), `actual city search returns ${zone}`);
  click([...container.querySelectorAll('[role="option"]')].find(o => o.textContent?.includes(zone))!);
  click(button(/^(Calcular mapa|Calculate chart)$/));
  await waitFor(() => requests.some(r => r.path === '/api/compute-chart' && (r.body.user?.name === name || r.body.partner?.name === name) && (r.payload?.metadata || r.payload?.user && r.payload?.partner)), `${name} real chart is calculated`);
  await settle();
}

test.beforeEach(async () => { await act(async () => { root.render(null); }); localStorage.clear(); requests.length = 0; holdDaily = false; });
test.after(async () => { await act(async () => { root.unmount(); }); dom.window.close(); await rm(runtime, { recursive: true, force: true }); });

test('actual App accepts sourced birth data through the city picker, personalizes Today, and restores the same chart after reload', async () => {
  await launch();
  click(nav(/^(Meu céu|Chart)$/));
  setValue(labelled(/^(Nome|Name)/), 'Fictional Honolulu profile');
  setValue(labelled(/^(Data de nascimento|Birth date)/), '1992-06-10');
  const unknown = query('.birth-form input[type="checkbox"]') as HTMLInputElement;
  assert.equal(unknown.checked, true);
  click(unknown);
  setValue(labelled(/^(Horário local|Birth time|Local time)/), '19:24');
  const city = query('.birth-form [role="combobox"]') as HTMLInputElement;
  act(() => city.focus()); setValue(city, 'Honolulu');
  await waitFor(() => query('[role="option"]'), 'city picker returns real GeoNames Honolulu');
  click(button(/Honolulu.*United States|Honolulu.*Estados Unidos|Honolulu/));
  assert.match(text(), /Pacific\/Honolulu/);
  click(button(/^(Calcular mapa|Calculate chart)$/));
  await waitFor(() => requests.some(r => r.path === '/api/compute-chart' && r.payload?.metadata), 'real Swiss chart is returned after form submission');
  await settle();
  const computation = requests.find(r => r.path === '/api/compute-chart');
  assert.equal(computation?.body.user.timezone, 'Pacific/Honolulu');
  assert.equal(computation?.body.user.time, '19:24');
  assert.equal(computation?.payload.metadata.utc, '1992-06-11T05:24:00.000Z', 'documented Honolulu civil time resolves to the next UTC day');
  click(nav(/^(Hoje|Today)$/));
  await waitFor(() => requests.some(r => r.path === '/api/daily-sky' && r.body.birth?.name === 'Fictional Honolulu profile'), 'Today request includes the saved birth profile');
  await waitFor(() => query('[data-testid="daily-overview"]') && text().includes('Top transits'), 'personalized daily sky loads');
  assert.match(text(), /Saved profile: Fictional Honolulu profile/);
  for (const destination of ['Calendar', 'Space', 'Chart', 'You']) {
    click(nav(new RegExp(`^${destination}$`)));
    await settle(50);
    assert.doesNotMatch(text(), /\b(?:Seu mapa|Sua leitura|Hora desconhecida|Posições|Conjunção|Quadratura|Trígono|Retrógrado|Não foi possível|Nenhum aspecto|Salvar|Cancelar|Escolher perfis|Fuso do calendário)\b/i, `${destination} uses English copy`);
  }
  click(nav(/^Today$/));
  const saved = JSON.parse(localStorage.getItem('astrolove_last_chart') || 'null');
  assert.equal(saved.user.name, 'Fictional Honolulu profile');
  await act(async () => { root.render(null); });
  await launch();
  await waitFor(() => query('[data-testid="chart-workspace"]'), 'workspace returns after actual App reload');
  await waitFor(() => requests.filter(r => r.path === '/api/compute-chart').length >= 2, 'reload recalculates the actual saved chart');
  await waitFor(() => requests.filter(r => r.path === '/api/daily-sky' && r.body.birth?.name === 'Fictional Honolulu profile').length >= 2, 'reload personalizes Today with restored data');
});

test('two actual unknown-time form journeys preserve distinct non-US profiles and reject a late daily response after switching people', async () => {
  await launch();
  click(nav(/^(Meu céu|Chart)$/));
  await fillUnknownProfile('Fictional Tokyo profile', '1998-06-03', 'Tokyo', 'Asia/Tokyo');
  click(nav(/^(Hoje|Today)$/));
  await waitFor(() => requests.some(r => r.path === '/api/daily-sky' && r.body.birth?.name === 'Fictional Tokyo profile'), 'first profile personalizes actual App Today');
  const select = query('.sky-context select') as HTMLSelectElement;
  setValue(select, 'partner');
  click(nav(/^(Meu céu|Chart)$/));
  holdDaily = true;
  await fillUnknownProfile('Fictional Paris profile', '1996-11-17', 'Paris', 'Europe/Paris');
  const stored = JSON.parse(localStorage.getItem('astrolove_last_chart') || 'null');
  assert.equal(stored.mode, 'compatibility');
  assert.equal(stored.user.timezone, 'Asia/Tokyo');
  assert.equal(stored.partner.timezone, 'Europe/Paris');
  assert.equal(stored.user.time, ''); assert.equal(stored.partner.time, '');
  const pair = requests.filter(r => r.path === '/api/compute-chart' && r.payload?.user && r.payload?.partner).at(-1)!.payload;
  assert.equal(pair.user.metadata.utc, '1998-06-03T03:00:00.000Z', 'unknown Tokyo birth uses noon at UTC+09, not noon UTC');
  assert.equal(pair.partner.metadata.utc, '1996-11-17T11:00:00.000Z', 'unknown Paris birth uses noon at UTC+01, not noon UTC');
  assert.equal(pair.user.metadata.timeKnown, false); assert.equal(pair.partner.metadata.timeKnown, false);
  assert.equal(pair.user.ascendant, null); assert.equal(pair.partner.ascendant, null);
  assert.equal(pair.user.houses, null); assert.equal(pair.partner.houses, null);
  click(nav(/^(Hoje|Today)$/));
  await waitFor(() => requests.some(r => !r.released && r.path === '/api/daily-sky' && r.body.birth?.name === 'Fictional Paris profile'), 'partner daily request is held');
  const stale = requests.filter(r => !r.released && r.path === '/api/daily-sky').at(-1)!;
  assert.equal(stale.body.birth.name, 'Fictional Paris profile');
  setValue(query('.sky-context select') as HTMLSelectElement, 'user');
  const current = requests.findLast(r => r.path === '/api/daily-sky' && r.body.birth?.name === 'Fictional Tokyo profile')!;
  assert.ok(current, 'Tokyo was calculated for this profile');
  if (!current.released) await act(async () => { await current.release(); });
  await waitFor(() => query('[data-testid="daily-overview"]') && text().includes('Top transits'), 'current person daily sky appears');
  const before = query('[data-testid="daily-overview"]')?.textContent;
  await act(async () => { await stale.release(); });
  assert.equal(query('[data-testid="daily-overview"]')?.textContent, before, 'late old-person response cannot replace the current real sky');
  assert.equal((query('.sky-context select') as HTMLSelectElement).value, 'user');
  assert.equal(query('.daily-sky [role="alert"]'), null);
  holdDaily = false;
});

