const privateProfile = await readFile(join(project, '.local/regression-fixture.json'), 'utf8').then(JSON.parse).catch(() => null);
test('optional private standing profile completes the actual birth form journey with time-specific chart limits', { skip: !privateProfile }, async () => {
  const birth = privateProfile.birth || privateProfile;
  assert.ok(birth.date && birth.timezone && birth.location, 'private fixture requires an actual birth date, city and timezone');
  await launch();
  click(nav(/^(Meu céu|Chart)$/));
  if (!birth.time) await fillUnknownProfile(birth.name || 'Standing private profile', birth.date, privateProfile.cityQuery || birth.location.split(',')[0], birth.timezone);
  else {
    setValue(labelled(/^(Nome|Name)/), birth.name || 'Standing private profile');
    setValue(labelled(/^(Data de nascimento|Birth date)/), birth.date);
    const checkbox = query('.birth-form input[type="checkbox"]') as HTMLInputElement;
    if (checkbox.checked) click(checkbox);
    setValue(labelled(/^(Horário local|Birth time|Local time)/), birth.time);
    const city = query('.birth-form [role="combobox"]') as HTMLInputElement;
    act(() => city.focus()); setValue(city, privateProfile.cityQuery || birth.location.split(',')[0]);
    await waitFor(() => [...container.querySelectorAll('[role="option"]')].some(o => o.textContent?.includes(birth.timezone)), `actual city search returns ${birth.timezone}`);
    click([...container.querySelectorAll('[role="option"]')].find(o => o.textContent?.includes(birth.timezone))!);
    click(button(/^(Calcular mapa|Calculate chart)$/));
    await waitFor(() => requests.some(r => r.path === '/api/compute-chart' && (r.payload?.metadata || r.payload?.user)), 'private timed chart is calculated');
    await settle();
  }
  const calculation = requests.filter(r => r.path === '/api/compute-chart').at(-1)!;
  const chart = calculation.payload.metadata ? calculation.payload : calculation.payload.user;
  assert.equal(chart.metadata.timeKnown, Boolean(birth.time));
  if (!birth.time) { assert.equal(chart.ascendant, null); assert.equal(chart.houses, null); }
  const localParts = new Intl.DateTimeFormat('en-CA', { timeZone: birth.timezone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(calculation.payload.metadata.utc));
  const part = (type: string) => localParts.find(p => p.type === type)?.value;
  assert.equal(`${part('year')}-${part('month')}-${part('day')}`, birth.date);
  const expectedLocal = birth.time || '12:00';
  assert.equal(`${part('hour')}:${part('minute')}`, expectedLocal, 'birth clock time resolves in its actual IANA birth zone');
  click(nav(/^(Hoje|Today)$/));
  await waitFor(() => requests.some(r => r.path === '/api/daily-sky' && r.body.birth?.date === birth.date), 'private unknown-time profile personalizes Today');
  await waitFor(() => query('[data-testid="daily-overview"]') && text().includes('Top transits'), 'private daily sky completes with real calculations');
});

