import test from 'node:test';
import assert from 'node:assert/strict';
import { buildDailySky } from '../api/_lib/daily-sky.ts';
import { fetchDailySky } from '../src/lib/daily-sky.ts';

const request = { date: '2024-04-08', timeZone: 'UTC' };
const actual = await buildDailySky(request);
const originalFetch = globalThis.fetch;
let response = actual;
globalThis.fetch = async () => ({ ok: true, json: async () => response });
test.after(() => { globalThis.fetch = originalFetch; });

test('daily client accepts an actual Swiss response without changing its positions or lunar data', async () => {
  response = actual;
  assert.deepEqual(await fetchDailySky(request), actual);
});

test('daily client rejects malformed success payloads before rendering positions, dates, or lunar SVGs', async () => {
  for (const tamper of [
    () => null,
    () => ({}),
    p => ({ ...p, at: 'not an instant' }),
    p => ({ ...p, date: '2024-04-09' }),
    p => ({ ...p, timeZone: 'Pacific/Apia' }),
    p => ({ ...p, moon: { ...p.moon, illumination: 1.1 } }),
    p => ({ ...p, planets: [null, ...p.planets.slice(1)] }),
    p => ({ ...p, planets: [p.planets[0], ...p.planets.slice(0, 9)] }),
    p => ({ ...p, month: [] }),
    p => ({ ...p, month: [null] }),
  ]) {
    response = tamper(structuredClone(actual));
    await assert.rejects(fetchDailySky(request), /incomplete data/);
  }
});

test('daily client rejects impossible and duplicate month dates instead of silently disabling or shifting calendar cells', async () => {
  for (const month of [
    [...actual.month, { ...actual.month[0] }],
    [{ ...actual.month[0], date: '2024-04-31' }, ...actual.month.slice(1)],
    [{ ...actual.month[0], date: '2024-04-99' }, ...actual.month.slice(1)],
  ]) {
    response = { ...structuredClone(actual), month };
    await assert.rejects(fetchDailySky(request), /incomplete data/);
  }
});

