import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, cp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { verifySwissBundle } from '../scripts/verify-swiss-bundle.mjs';

test('bundled modern and historical ephemerides have their recorded release checksums', async () => {
  assert.deepEqual(await verifySwissBundle(), { files: 4, bytes: 3578507, coverage: '1200–2399' });
});

test('damaged ephemerides fail visibly instead of accepting an engine fallback', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'swiss-bundle-check-'));
  try {
    await cp(new URL('../ephe/', import.meta.url), directory, { recursive: true });
    await writeFile(join(directory, 'sepl_18.se1'), 'damaged');
    await assert.rejects(verifySwissBundle(directory), /damaged: sepl_18/);
  } finally { await rm(directory, { recursive: true, force: true }); }
});

