import test from 'node:test';
import assert from 'node:assert/strict';
import { parseSavedChart, createWorkspaceSavedChart, restoreSavedProfiles } from '../src/lib/saved-chart.ts';
const person = { name: 'Reference', date: '1961-08-04', time: '19:24', location: 'Honolulu', lat: 21.3, lon: -157.8667, timezone: 'Pacific/Honolulu' };
const valid = { id: 'last', mode: 'chart', user: person, isPaid: false };
test('saved inputs preserve the birth data needed for real recalculation and support legacy unknown-time markers', () => {
  assert.deepEqual(parseSavedChart(JSON.stringify(valid)), valid);
  assert.equal(parseSavedChart({ ...valid, user: { ...person, time: 'SUNRISE' } }).user.time, 'SUNRISE');
  assert.deepEqual(parseSavedChart({ ...valid, mode: 'compatibility', partner: { ...person, time: '' } }).partner, { ...person, time: '' });
});
test('corrupt storage cannot restore undefined profiles, impossible dates, invalid times or fabricated coordinates', () => {
  for (const value of ['invalid', '{}', '[]', null, false, { ...valid, user: undefined }, { ...valid, mode: 'compatibility' },
    ...[{ date: '2023-02-29' }, { date: '2024-13-10' }, { date: '1100-01-01' }, { time: '25:00' }, { lat: NaN }, { lon: 181 }, { name: null }, { timezone: 1 }].map(change => ({ ...valid, user: { ...person, ...change } })),
  ]) assert.equal(parseSavedChart(value), null);
});

test('partner-first standalone persistence restores the original partner slot and recalculation input', () => {
  const blank = { name: '', date: '', time: '', location: '' };
  const chart = { planets: [], metadata: { settings: { houseSystem: 'placidus', orbs: { 0: 6 } } } };
  const saved = createWorkspaceSavedChart(blank, person, chart, 'partner', false);
  const parsed = parseSavedChart(JSON.stringify(saved));
  assert.ok(parsed);
  assert.equal(parsed.mode, 'chart');
  assert.deepEqual(parsed.user, person, 'canonical input must remain valid for standalone recalculation');
  assert.equal(parsed.standaloneSlot, 'partner');
  assert.deepEqual(parsed.settings, chart.metadata.settings);
  const restored = restoreSavedProfiles(parsed);
  assert.equal(restored.initialSlot, 'partner');
  assert.deepEqual(restored.partner, person);
  assert.deepEqual(restored.user, blank, 'partner must never be relabeled as user');
});

test('legacy user charts and two-person saves retain owners and ignore obsolete standalone metadata on pairs', () => {
  assert.equal(restoreSavedProfiles(valid).initialSlot, 'user');
  assert.deepEqual(restoreSavedProfiles(valid).user, person);
  const partner = { ...person, name: 'Second owner', date: '2000-01-01' };
  const saved = createWorkspaceSavedChart(person, partner, { user: { metadata: { settings: {} } }, partner: {} }, 'partner', true);
  assert.equal(saved.mode, 'compatibility');
  assert.equal(saved.standaloneSlot, undefined);
  const restored = restoreSavedProfiles({ ...saved, standaloneSlot: 'partner' });
  assert.equal(restored.initialSlot, 'user');
  assert.deepEqual(restored.user, person);
  assert.deepEqual(restored.partner, partner);
  for (const standaloneSlot of ['friend', '', 1, null]) assert.equal(parseSavedChart({ ...valid, standaloneSlot }), null);
});

