import test from 'node:test';
import assert from 'node:assert/strict';
import { phaseFromElongation, lunationPhase, localPhaseDay } from '../src/lib/phase-cycle.ts';
import { bodyIds, traditionalRulers, featuredPlanetForChart } from '../src/lib/featured-planet.ts';
import { topTransitContacts, transitContacts } from '../src/lib/transit-aspects.ts';
import { defaultChartSettings } from '../src/lib/chart-settings.ts';

test('Rudhyar sectors start at multiples of45; all boundaries and wrap follow the authoritative formula', () => {
  for (let index = 0; index < 8; index++) {
    const at = phaseFromElongation(index * 45), before = phaseFromElongation(index * 45 - 0.00001);
    assert.equal(at.phaseNumber, index + 1);
    assert.equal(before.phaseNumber, index === 0 ? 8 : index);
    assert.equal(phaseFromElongation(index * 45 + 44.99999).phaseNumber, index + 1);
  }
  assert.equal(phaseFromElongation(360).phaseNumber, 1);
  assert.equal(phaseFromElongation(-1).phaseNumber, 8);
  assert.equal(phaseFromElongation(22.5).phaseNumber, 1, 'no centred45degree sector convention');
  assert.equal(lunationPhase(350, 35).phaseNumber, 2);
  assert.equal(lunationPhase(10, 280).phaseNameEn, 'Last Quarter');
  assert.equal(phaseFromElongation(315).phaseNameEn, 'Balsamic');
  for (const [angle, expected] of [[0, 0], [90, 50], [180, 100], [270, 50]]) assert.ok(Math.abs(phaseFromElongation(angle).illuminationPercent - expected) < 1e-10);
  assert.throws(() => phaseFromElongation(NaN));
});

test('phase day counts local civil dates rather than elapsed24hour periods across DST', () => {
  assert.equal(localPhaseDay('2024-03-10T04:30:00Z', '2024-03-10', 'America/New_York'), 2, 'phase started March9 locally');
  assert.equal(localPhaseDay('2024-03-10T05:30:00Z', '2024-03-11', 'America/New_York'), 2, 'only23.5hours elapsed at following midnight');
  assert.equal(localPhaseDay('2024-11-03T04:30:00Z', '2024-11-04', 'America/New_York'), 2);
});

test('featured planet derives all12 traditional Sun-sign rulers, permits ten overrides and flags unknown-time cusps', () => {
  const expected = ['mars', 'venus', 'mercury', 'moon', 'sun', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'saturn', 'jupiter'];
  assert.deepEqual([...traditionalRulers], expected);
  const chart = (longitude, known = true) => ({ planets: [{ id: 'sun', lon: longitude }], metadata: { timeKnown: known } });
  for (let index = 0; index < 12; index++) assert.equal(featuredPlanetForChart(chart(index * 30 + 15)).bodyId, expected[index]);
  for (const bodyId of bodyIds) assert.equal(featuredPlanetForChart(chart(75), bodyId).bodyId, bodyId);
  assert.equal(featuredPlanetForChart(chart(60.5, false)).uncertainSunSign, true);
  assert.equal(featuredPlanetForChart(chart(89.5, false)).uncertainSunSign, true);
  assert.equal(featuredPlanetForChart(chart(75, false)).uncertainSunSign, false);
  assert.deepEqual(featuredPlanetForChart(chart(60.5, false), undefined, 1), { bodyId: 'venus', sunSignIndex: 1, uncertainSunSign: false });
  assert.throws(() => featuredPlanetForChart(chart(75), 'earth'));
  assert.throws(() => featuredPlanetForChart(chart(75), undefined, 12));
});

test('applying/separating uses actual supplied next-hour positions; top3 reserves featured first and slower ties first', () => {
  const settings = { ...defaultChartSettings, orbs: { '0': 2, '60': 2, '90': 2, '120': 2, '180': 2 } };
  const contacts = transitContacts([{ id: 'mercury', lon: 89 }, { id: 'moon', lon: 91 }, { id: 'pluto', lon: 359 }], [{ id: 'mercury', lon: 89.5 }, { id: 'moon', lon: 91.5 }, { id: 'pluto', lon: 359.2 }], [{ id: 'sun', lon: 0 }], settings);
  assert.equal(contacts.find(c => c.transitPlanet === 'mercury').motion, 'applying');
  assert.equal(contacts.find(c => c.transitPlanet === 'moon').motion, 'separating');
  assert.equal(contacts.find(c => c.transitPlanet === 'pluto').motion, 'applying');
  const make = (transitPlanet, orb) => ({ transitPlanet, natalPlanet: 'sun', type: 'Conjunction', angle: 0, orb, applying: true, motion: 'applying' });
  const ranked = topTransitContacts([make('moon', 0.1), make('pluto', 0.1), make('venus', 0.2), make('mercury', 5)], { moon: 13, pluto: -0.001, venus: 1, mercury: -0.2 }, 'mercury');
  assert.equal(ranked.length, 3);
  assert.deepEqual(ranked.map(c => c.transitPlanet), ['mercury', 'pluto', 'moon']);
  assert.deepEqual(topTransitContacts([], {}, 'mercury'), []);
});

