import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const bundledRoot = fileURLToPath(new URL('../ephe/', import.meta.url));
const expected = ['sepl_12.se1', 'semo_12.se1', 'sepl_18.se1', 'semo_18.se1'];

export async function verifySwissBundle(directory = bundledRoot) {
  const manifest = JSON.parse(await readFile(join(directory, 'manifest.json'), 'utf8'));
  if (!Array.isArray(manifest.files) || manifest.files.length !== expected.length ||
      new Set(manifest.files.map(file => file.name)).size !== expected.length ||
      manifest.files.some(file => !expected.includes(file.name))) throw new Error('Invalid bundled Swiss manifest.');
  let bytes = 0;
  for (const file of manifest.files) {
    const data = await readFile(join(directory, file.name));
    if (data.length !== file.bytes || !/^[a-f0-9]{64}$/.test(file.sha256) ||
        createHash('sha256').update(data).digest('hex') !== file.sha256 ||
        !data.subarray(0, 100).toString().includes('SWISSEPH')) {
      throw new Error(`Bundled Swiss file damaged: ${file.name}. Restore it from the clean package.`);
    }
    bytes += data.length;
  }
  return { files: expected.length, bytes, coverage: '1200–2399' };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = await verifySwissBundle();
  console.log(`Bundled Swiss data verified: ${result.files} files, ${result.coverage}; no download needed.`);
}

