import express from 'express';
import { createServer } from 'node:http';
import { access } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { createServer as createViteServer } from 'vite';
import dotenv from 'dotenv';
import { checkoutId, localAppPort, openBrowser } from './lib/open-browser.mjs';

// One local process for the actual frontend and existing Node API handlers.
const root = fileURLToPath(new URL('../', import.meta.url));
process.chdir(root);
dotenv.config({ path: ['.env.local', '.env'], quiet: true });
const production = process.argv.includes('--production');
process.env.NODE_ENV = production ? 'production' : 'development';
const shouldOpen = process.argv.includes('--open');
// Keep the browser origin stable so profiles and local journals survive a relaunch.
const port = localAppPort(process.env.PORT, shouldOpen);
const app = express();
const server = createServer(app);
const offlineRoutes = ['daily-sky', 'astro-events', 'compute-chart', 'locations', 'transits-today'];
const routes = new Map(offlineRoutes.map(name => ['/' + name, new URL('../api/' + name + '.ts', import.meta.url).href]));
app.get('/api/app-info', (_req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  res.json({ app: 'Hermit', checkout: checkoutId(root) });
});
app.use('/api', express.json({ limit: '64kb' }), async (req, res) => {
  const route = routes.get(req.path);
  if (!route) return res.status(404).json({ error: 'not_found' });
  try {
    const { default: handler } = await import(route);
    await handler(req, res);
  } catch (error) {
    console.error('[local-api]', req.path, error.message);
    if (!res.headersSent) res.status(500).json({ error: 'api_unavailable' });
    else res.end();
  }
});
let vite = null;
if (production) {
  await access(new URL('../dist/index.html', import.meta.url));
  const dist = fileURLToPath(new URL('../dist/', import.meta.url));
  app.use('/assets', express.static(fileURLToPath(new URL('../dist/assets/', import.meta.url)), { immutable: true, maxAge: '1y', fallthrough: false }));
  app.use(express.static(dist));
  app.get('*', (req, res) => res.sendFile(fileURLToPath(new URL('../dist/index.html', import.meta.url))));
} else {
  vite = await createViteServer({ root, server: { middlewareMode: true, hmr: { server } }, appType: 'spa' });
  app.use(vite.middlewares);
}
try {
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, production ? process.env.HOST || '127.0.0.1' : '127.0.0.1', resolve);
  });
  const address = server.address();
  const actualPort = typeof address === 'object' && address ? address.port : port;
  const url = `http://127.0.0.1:${actualPort}`;
  console.log(`Hermit + APIs: ${url}`);
  if (shouldOpen) {
    // Open only after Express, API routing, Vite, and the listening socket are ready.
    await openBrowser(url).catch(() => console.warn(`Could not open the browser automatically. Open ${url}`));
  }
} catch (error) {
  console.error(`[local-server] ${error.message}`);
  await vite?.close();
  process.exitCode = 1;
}
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, async () => {
  await vite?.close();
  server.close();
});

