import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';

export function checkoutId(root) { return createHash('sha256').update(resolve(root)).digest('hex').slice(0, 16); }
export function localAppPort(value = process.env.PORT, shouldOpen = true) {
  const port = value === undefined ? (shouldOpen ? 3186 : 3000) : Number(value);
  if (!Number.isInteger(port) || port < 0 || port > 65535 || value === '') throw new Error('Invalid PORT');
  return port;
}
/** A failed/mismatched probe is never permission to open a browser at that port. */
export async function hasMatchingApp(root, port, fetchImpl = globalThis.fetch) {
  if (port === 0) return false;
  try {
    const response = await fetchImpl(`http://127.0.0.1:${port}/api/app-info`, { signal: AbortSignal.timeout(500), redirect: 'error', cache: 'no-store' });
    if (!response.ok) return false;
    const value = await response.json();
    return value?.app === 'Hermit' && value.checkout === checkoutId(root);
  } catch { return false; }
}
/** No shell: the URL is passed as a single platform opener argument. */
export function openBrowser(url, { platform = process.platform, spawnImpl = spawn } = {}) {
  const command = platform === 'darwin' ? 'open' : platform === 'win32' ? 'rundll32' : 'xdg-open';
  const args = platform === 'win32' ? ['url.dll,FileProtocolHandler', url] : [url];
  return new Promise((resolve, reject) => {
    let child;
    try { child = spawnImpl(command, args, { stdio: 'ignore', shell: false }); } catch (error) { reject(error); return; }
    child.once('error', reject);
    child.once('exit', (code, signal) => { if (code === 0 && !signal) resolve(); else reject(new Error(`Browser opener exited with ${signal || code}`)); });
  });
}

