import { spawn } from 'node:child_process';
import { access, readFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { verifySwissBundle } from './verify-swiss-bundle.mjs';
import { hasMatchingApp, localAppPort, openBrowser } from './lib/open-browser.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const require = createRequire(new URL('../package.json', import.meta.url));
let child;
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => {
  stopping = true;
  child?.kill(signal);
});

async function dependenciesAvailable() {
  const manifest = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
  const dependencies = Object.keys({ ...manifest.dependencies, ...manifest.devDependencies });
  try {
    // Checking package directories also handles type-only packages without a runtime entry point.
    await Promise.all(dependencies.map(name => access(join(root, 'node_modules', ...name.split('/'), 'package.json'))));
    require('sweph'); // Also check that the platform's native Swiss binding can actually load.
    return true;
  } catch { return false; }
}

function run(command, args) {
  return new Promise((resolve, reject) => {
    child = spawn(command, args, { cwd: root, stdio: 'inherit', env: process.env, shell: false });
    child.once('error', reject);
    child.once('exit', (code, signal) => { child = undefined; resolve({ code, signal }); });
  });
}

function finish({ code, signal }) {
  if (signal) {
    // Restore default signal behavior so the caller sees the server's termination signal.
    process.removeAllListeners('SIGINT');
    process.removeAllListeners('SIGTERM');
    process.kill(process.pid, signal);
  } else process.exitCode = code ?? 1;
}

async function npmCommand() {
  // npm run provides its real JS entry point. Standard Node Windows installations also bundle it here.
  const candidates = [process.env.npm_execpath, join(dirname(process.execPath), 'node_modules/npm/bin/npm-cli.js')].filter(Boolean);
  for (const candidate of candidates) {
    if (!/npm-cli\.(?:c?js|mjs)$/.test(candidate)) continue;
    try { await access(candidate); return { command: process.execPath, args: [candidate] }; } catch {}
  }
  if (process.platform === 'win32') throw new Error('npm was not found. Open this folder in a Node terminal and run npm run open.');
  return { command: 'npm', args: [] }; // Unix executable/shebang; no shell interpolation.
}

try {
  const [major, minor] = process.versions.node.split('.').map(Number);
  if (major < 22 || major === 22 && minor < 18 || major === 23) throw new Error('Use Node 22.18+ or Node 24+ to start the TypeScript server.');
  // Match the server's optional .env PORT before probing. Missing dependencies are installed below.
  try { require('dotenv').config({ path: [join(root, '.env.local'), join(root, '.env')], quiet: true }); }
  catch (error) { if (error.code !== 'MODULE_NOT_FOUND') throw error; }
  const port = localAppPort(process.env.PORT, true);
  if (await hasMatchingApp(root, port)) {
    const url = `http://127.0.0.1:${port}`;
    console.log(`Hermit: reusing this project at ${url}`);
    await openBrowser(url).catch(() => console.warn(`Could not open the browser automatically. Open ${url}`));
