import type { VercelRequest, VercelResponse } from '@vercel/node';
import { searchCityCatalog } from './_lib/locations.ts';

export default async function handler(req: VercelRequest, res: VercelResponse) {
  res.setHeader('Cache-Control', 'private, no-store');
  if (req.method !== 'POST') return res.status(405).json({ message: 'Method not allowed.' });
  const body = req.body;
  if (!body || typeof body !== 'object' || Array.isArray(body) || Object.keys(body).some(k => k !== 'query') || typeof body.query !== 'string' || body.query.trim().length < 2 || body.query.length > 120) return res.status(400).json({ message: 'Enter a city, state, or country using 2 to 120 characters.' });
  try { return res.status(200).json({ cities: await searchCityCatalog(body.query), source: 'GeoNames', license: 'CC-BY-4.0' }); }
  catch { return res.status(503).json({ message: 'City search is unavailable. Enter coordinates and timezone manually.' }); }
}

