import { readFile } from 'node:fs/promises';
import { gunzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { join } from 'node:path';

type City = { id: string; name: string; display: string; lat: number; lon: number; country: string; timezone?: string; population: number; key: string; nameKey: string };
const normalize = (s: string) => s.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('en-US').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
let index: Promise<City[]> | undefined;
const checksum = (b: Buffer) => createHash('sha256').update(b).digest('hex');
/** Installed dataset by default. Outside production, LOCATIONS_DATA_DIR may point at another directory in the same format (same files plus its own LOCATION-DATA.json manifest), which is how offline tests use a subset fixture. */
export function locationDataPaths(env = process.env) {
  const root = process.cwd(), override = env.NODE_ENV !== 'production' ? env.LOCATIONS_DATA_DIR : undefined;
  return override ? { cities: join(override, 'cities500.tsv.gz'), admins: join(override, 'admin1.txt'), manifest: join(override, 'LOCATION-DATA.json'), source: 'override' as const } : { cities: join(root, 'data/locations/cities500.tsv.gz'), admins: join(root, 'data/locations/admin1.txt'), manifest: join(root, 'docs/LOCATION-DATA.json'), source: 'installed' as const };
}
async function loadCities() {
  if (index) return index;
  index = (async () => {
    const paths = locationDataPaths();
    const [data, admins, manifestText] = await Promise.all([readFile(paths.cities), readFile(paths.admins), readFile(paths.manifest, 'utf8')]);
    const manifest = JSON.parse(manifestText);
    if (checksum(data) !== manifest.cityFileSha256 || checksum(admins) !== manifest.adminFileSha256) throw new Error('Location dataset checksum mismatch.');
    const regions = new Map(admins.toString('utf8').trim().split('\n').map(line => { const [id, name] = line.split('\t'); return [id, name]; }));
    const pt = new Intl.DisplayNames(['en-US'], { type: 'region' }), en = new Intl.DisplayNames(['en'], { type: 'region' });
    const countryCache = new Map<string, { display: string; key: string }>(), zones = new Map<string, boolean>();
    const rows = gunzipSync(data).toString('utf8').trim().split('\n');
    if (rows.length !== manifest.sourceRecords) throw new Error('Location dataset count mismatch.');
    return rows.map(line => {
      const f = line.split('\t');
      const lat = Number(f[4]), lon = Number(f[5]);
      if (f.length !== 19 || !/^\d+$/.test(f[0]) || !f[1] || !/^-?\d+(?:\.\d+)?$/.test(f[4]) || !/^-?\d+(?:\.\d+)?$/.test(f[5]) || !Number.isFinite(lat) || Math.abs(lat) > 90 || !Number.isFinite(lon) || Math.abs(lon) > 180 || !/^[A-Z]{2}$/.test(f[8])) throw new Error('Invalid city source record.');
      if (!countryCache.has(f[8])) countryCache.set(f[8], { display: pt.of(f[8]) || f[8], key: `${pt.of(f[8])} ${en.of(f[8])} ${f[8]}` });
      const country = countryCache.get(f[8])!;
      if (!zones.has(f[17])) { try { new Intl.DateTimeFormat('en', { timeZone: f[17] }); zones.set(f[17], true); } catch { zones.set(f[17], false); } }
      const region = regions.get(`${f[8]}.${f[10]}`) || '';
      return { id: f[0], name: f[1], display: [f[1], region, country.display].filter(Boolean).join(', '), lat, lon, country: country.display, timezone: zones.get(f[17]) ? f[17] : undefined, population: Number(f[14]) || 0, nameKey: normalize(f[1]), key: normalize(`${f[1]} ${f[2]} ${f[3]} ${region} ${country.key}`) };
    });
  })().catch(error => { index = undefined; throw error; });
  return index;
}

export async function searchCityCatalog(query: string) {
  const key = normalize(query).replace(/\bbrasil\b/g, 'brazil'), tokens = key.split(' ');
  if (key.length < 2) return [];
  const cities = await loadCities();
  return cities.filter(city => tokens.every(token => city.key.includes(token))).sort((a, b) => {
    const score = (city: City) => city.nameKey === key ? 0 : city.nameKey.startsWith(key) ? 1 : 2;
    return score(a) - score(b) || b.population - a.population || a.id.localeCompare(b.id);
  }).slice(0, 8).map(({ key, nameKey, population, ...city }) => ({ ...city, source: `https://www.geonames.org/${city.id}/`, license: 'CC-BY-4.0' }));
}

