export interface BirthInput {
  name?: string;
  date: string;
  time?: string;
  lat?: number;
  lon?: number;
  timezone?: string;
  location?: string;
}
export class BirthInputError extends Error {}

export function parseBirth(input: BirthInput): { date: Date; timeKnown: boolean; warnings: string[] } {
  if (!input || typeof input.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(input.date)) throw new BirthInputError('Invalid date; use YYYY-MM-DD.');
  const day = new Date(`${input.date}T00:00:00Z`);
  if (!Number.isFinite(day.getTime()) || day.toISOString().slice(0, 10) !== input.date) throw new BirthInputError('This date does not exist.');
  for (const [key, max] of [['lat', 90], ['lon', 180]] as const) {
    if (input[key] !== undefined && (typeof input[key] !== 'number' || !Number.isFinite(input[key]) || Math.abs(input[key]!) > max)) throw new BirthInputError('Invalid coordinates.');
  }
  if (input.time !== undefined && typeof input.time !== 'string') throw new BirthInputError('Invalid time.');
  const timeKnown = !!input.time && input.time !== 'SUNRISE';
  if (timeKnown && !/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(input.time!)) throw new BirthInputError('Invalid time; use HH:MM or HH:MM:SS.');
  const warnings: string[] = [];
  if (!timeKnown) warnings.push(`Birth time unknown: approximate positions at noon ${input.timezone ? 'in the birth timezone' : 'UTC'}; no Ascendant or houses. Lunar contacts remain uncertain.`);
  if (!input.timezone && timeKnown) throw new BirthInputError('Select a city with a confirmed timezone.');
  if (!input.timezone) warnings.push('Unknown timezone: noon UTC reference, without time precision.');
  const civilTime = timeKnown ? input.time!.length === 5 ? `${input.time}:00` : input.time! : '12:00:00';
  const target = Date.parse(`${input.date}T${civilTime}Z`);
  const tz = input.timezone || 'UTC';
  const fixed = /^UTC([+-])(\d{1,2}):(\d{2})(?::(\d{2}))?$/.exec(tz);
  if (fixed) {
    const hours = +fixed[2], minutes = +fixed[3], seconds = +(fixed[4] || 0);
    if (hours > 14 || minutes > 59 || seconds > 59 || (hours === 14 && (minutes || seconds))) throw new BirthInputError('Invalid offset.');
    const offset = (hours * 3600 + minutes * 60 + seconds) * (fixed[1] === '-' ? -1 : 1);
    return { date: new Date(target - offset * 1000), timeKnown, warnings };
  }
  let format: Intl.DateTimeFormat;
  try {
    format = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
  } catch { throw new BirthInputError('Invalid timezone.'); }
  if (timeKnown && input.date < '1970-01-01') warnings.push('Pre-1970 IANA timezone: historical rules may differ from the local standard in the birth record. The calculation uses the supplied zone; confirm the documented UTC offset for precise historical work.');
  // Unknown birth time uses the specified local-noon reference; it never makes angles known.
  const localMillis = (instant: number) => {
    const p = Object.fromEntries(format.formatToParts(new Date(instant)).map(p => [p.type, p.value]));
    return Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}Z`);
  };
  // Try offsets on both sides of a DST transition. Reject folds and gaps.
  const offsets = new Set([-36, 0, 36].map(h => {
    const instant = target + h * 3600000;
    return localMillis(instant) - instant;
  }));
  const candidates = [...offsets].map(offset => target - offset).filter(instant => localMillis(instant) === target);
  if (candidates.length !== 1) throw new BirthInputError('Ambiguous or nonexistent time due to a timezone change; enter the confirmed UTC offset.');
  return { date: new Date(candidates[0]), timeKnown, warnings };
}

