import { parseBirth, BirthInputError } from './birth.ts';
import { swiss } from './swiss.ts';
import { parseChartSettings } from './chart-settings.ts';
import { buildChart } from '../compute-chart.ts';
import { exactPosition, DAY_MS } from './astro-events.ts';
import { findLunationEvents, findPlanetEvents, findTransitPasses, lunationContext, planetCycle } from './planet-cycles.ts';
import { bodyIds, featuredPlanetForChart, type BodyId } from '../../src/lib/featured-planet.ts';
import { lunationPhase, localPhaseDay } from '../../src/lib/phase-cycle.ts';
import { topTransitContacts, transitContacts } from '../../src/lib/transit-aspects.ts';
import type { DailySkyRequest, DailySkyResponse, DailyMoon, DailyPlanet, DailyCalendarDay, PlanetCycleEvent } from '../../src/lib/daily-sky.ts';

const names = ['Sun', 'Moon', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune', 'Pluto'];
const signs = ['Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo', 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces'];
const MIN = Date.parse('1200-01-01T00:00:00Z'), MAX = Date.parse('2399-12-31T23:59:59.999Z');
const calendarCache = new Map<string, { phases: PlanetCycleEvent[]; events: PlanetCycleEvent[] }>();
const formatCache = new Map<string, Intl.DateTimeFormat>();

export function dateInZone(at: Date, timeZone: string): string {
  let format = formatCache.get(timeZone);
  if (!format) {
    format = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' });
    if (formatCache.size >= 32) formatCache.delete(formatCache.keys().next().value!);
    formatCache.set(timeZone, format);
  }
  const parts = Object.fromEntries(format.formatToParts(at).map(part => [part.type, part.value]));
  return `${parts.year}-${parts.month}-${parts.day}`;
}

/** A local day may have 23/25 hours or start after a skipped midnight. */
export function civilDayBounds(date: string, timeZone: string): { start: Date; end: Date } {
  const noon = localNoon(date, timeZone).getTime();
  const boundary = (end: boolean) => {
    let lo = noon + (end ? 0 : -72 * 3600000), hi = noon + (end ? 72 * 3600000 : 0);
    while (hi - lo > 1) {
      const middle = Math.floor((lo + hi) / 2), day = dateInZone(new Date(middle), timeZone);
      if (end ? day <= date : day < date) lo = middle; else hi = middle;
    }
    return new Date(hi);
  };
  return { start: boundary(false), end: boundary(true) };
}

function validateDate(date: unknown): asserts date is string {
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new BirthInputError('Invalid date; use YYYY-MM-DD.');
  const instant = new Date(`${date}T00:00:00Z`);
  if (!Number.isFinite(instant.getTime()) || instant.toISOString().slice(0, 10) !== date || date < '1200-01-01' || date > '2399-12-31') throw new BirthInputError('This date does not exist or is outside 1200–2399 coverage.');
}

/** Resolve a real local noon using the existing strict gap/fold-aware civil-time parser. */
export function localNoon(date: string, timeZone: string): Date {
  validateDate(date);
  if (typeof timeZone !== 'string' || !timeZone.trim() || timeZone.length > 100) throw new BirthInputError('Select a valid IANA timezone.');
  // The calendar contract takes IANA identifiers (or UTC), not implicit offsets or host defaults.
  try { new Intl.DateTimeFormat('en', { timeZone }).format(); }
  catch { throw new BirthInputError('Select a valid IANA timezone.'); }
  const result = parseBirth({ date, time: '12:00:00', timezone: timeZone });
  if (result.date.getUTCFullYear() < 1200 || result.date.getUTCFullYear() > 2399) throw new BirthInputError('Meio-dia local fora da cobertura 1200–2399.');
  return result.date;
}

/** PDF 8.5 uses elongation illumination; the distinct physical Swiss result remains disclosed. */
export function moonAt(at: Date, sunLon?: number, moonLon?: number, timeZone = 'UTC', events?: PlanetCycleEvent[]): DailyMoon {
  const sun = sunLon ?? exactPosition('sun', at.getTime()).lon;
  const moon = moonLon ?? exactPosition('moon', at.getTime()).lon;
  const phase = lunationPhase(sun, moon);
  const s = swiss();
  const physical = s.pheno_ut(at.getTime() / 86400000 + 2440587.5, s.constants.SE_MOON, s.constants.SEFLG_SWIEPH);
  const physicalIllumination = physical.data?.[1];
  if (physical.flag < 0 || !Number.isFinite(physicalIllumination) || physicalIllumination < 0 || physicalIllumination > 1) throw new Error('Swiss Ephemeris is unavailable for lunar illumination.');
