  return { ...phase, physicalIllumination, ...context, dayOfPhase: context.phaseStart ? localPhaseDay(context.phaseStart, dateInZone(at, timeZone), timeZone) : null };
}

export async function buildDailySky(value: unknown): Promise<DailySkyResponse> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new BirthInputError('Invalid daily sky request.');
  if (Object.keys(value).some(key => !['date', 'timeZone', 'birth', 'settings', 'featuredPlanet'].includes(key))) throw new BirthInputError('Unknown daily sky field.');
  const body = value as DailySkyRequest;
  const at = localNoon(body.date, body.timeZone);
  const settings = parseChartSettings(body.settings);
  if (body.featuredPlanet !== undefined && !bodyIds.includes(body.featuredPlanet)) throw new BirthInputError('Invalid featured planet.');
  const warnings = [
    'Daily view sampled at local noon; positions and contacts do not represent every hour of the day.',
    'Rudhyar phase: floor((Moon−Sun mod 360)/45)+1. Displayed illumination: (1−cos E)/2; physicalIllumination is the separate physical Swiss pheno_ut result. Neither is an energy percentage.',
    'Lunar events/conjunctions have a declared numerical precision of 1 second; ingresses use the timeline search and stations have a 60-second tolerance. This precision does not remove birth-data uncertainty.',
    'Geocentric positions; no local daily-sky houses or angles. The birth location was not replaced.',
  ];
