    if (!body.birth || typeof body.birth !== 'object' || Array.isArray(body.birth)) throw new BirthInputError('Invalid birth profile.');
    const birth = body.birth;
    const parsed = parseBirth(birth);
    if (parsed.date.getUTCFullYear() < 1200 || parsed.date.getUTCFullYear() > 2399) throw new BirthInputError('Nascimento fora da cobertura 1200–2399.');
