    natal = await buildChart({ date: birth.date, time: birth.time, timezone: birth.timezone, lat: birth.lat, lon: birth.lon }, settings);
    if (natal.metadata.engine !== 'swiss-ephemeris') throw new Error('The daily sky requires a natal chart calculated by Swiss Ephemeris.');
