  if (natal) {
    const featured = featuredPlanetForChart(natal, body.featuredPlanet);
    featuredPlanetId = featured.bodyId;
    if (featured.uncertainSunSign) warnings.push('Unknown birth time and Sun within 1° of a boundary: Sun sign and ruler may differ. Confirm the sign or choose a featured planet.');
  }
