  const laterAt = at.getTime() + 3600000;
  if (laterAt > MAX) throw new BirthInputError('The reading one hour later is outside coverage.');
  const oneHourLater = bodyIds.map(id => ({ id, lon: exactPosition(id, laterAt).lon }));
  const contacts = transitContacts(planets, oneHourLater, natalPoints, settings);
  const speeds = Object.fromEntries(planets.map(planet => [planet.id, planet.speed]));
  contacts.sort((a, b) => a.orb - b.orb || Math.abs(speeds[a.transitPlanet]) - Math.abs(speeds[b.transitPlanet]));
  const topContacts = topTransitContacts(contacts, speeds, featuredPlanetId);
  const month: DailyCalendarDay[] = [];
  const fourteenDayStrip: DailyCalendarDay[] = [];
  const prefix = body.date.slice(0, 7), year = Number(body.date.slice(0, 4)), monthNumber = Number(body.date.slice(5, 7));
  const dayCount = new Date(Date.UTC(year, monthNumber, 0)).getUTCDate();
  const monthDates = Array.from({ length: dayCount }, (_, index) => `${prefix}-${String(index + 1).padStart(2, '0')}`);
  const stripDates = Array.from({ length: 14 }, (_, index) => new Date(Date.parse(`${body.date}T12:00:00Z`) + index * DAY_MS).toISOString().slice(0, 10)).filter(date => date <= '2399-12-31');
  const allDates = [...new Set([...monthDates, ...stripDates])].sort();
  const noonDates = new Map<string, Date>();
  for (const date of allDates) {
    let instant: Date;
    try { instant = localNoon(date, body.timeZone); }
    catch (error) {
      if (!(error instanceof BirthInputError)) throw error;
      warnings.push(`No sample for ${date}: local noon is nonexistent/ambiguous in the selected zone or outside coverage.`);
      continue;
    }
    noonDates.set(date, instant);
  }
  const validDates = [...noonDates.keys()];
