import { exactPosition, sweepCrossings, angleDistance, norm, DAY_MS } from './astro-events.ts';
import { BirthInputError } from './birth.ts';
import { bodyIds, type BodyId } from '../../src/lib/featured-planet.ts';
import { phaseFromElongation, type PhaseNumber } from '../../src/lib/phase-cycle.ts';
import type { PlanetCycle, PlanetCycleEvent } from '../../src/lib/daily-sky.ts';
import type { ChartSettings } from '../../src/lib/chart-settings.ts';

const MIN = Date.parse('1200-01-01T00:00:00Z');
const MAX = Date.parse('2399-12-31T23:59:59.999Z');
const signs = ['Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo', 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces'];
const iso = (at: number) => new Date(at).toISOString();
const signed = (longitude: number) => norm(longitude + 180) - 180;
const eventId = (kind: string, bodyId: string, at: number, suffix = '') => `${kind}:${bodyId}:${iso(Math.round(at / 60000) * 60000)}${suffix ? `:${suffix}` : ''}`;
const cache = new Map<string, PlanetCycleEvent[]>();

function validateWindow(from: Date, to: Date) {
  if (!Number.isFinite(from.getTime()) || !Number.isFinite(to.getTime()) || from.getTime() < MIN || to.getTime() > MAX || to.getTime() <= from.getTime() || to.getTime() - from.getTime() > 370 * DAY_MS) throw new BirthInputError('Invalid event window: up to 370 days within 1200–2399.');
}

/** Moving-body minus moving-Sun crossings; the existing static-target solver cannot solve these. */
function relativeCrossings(bodyId: 'moon' | 'mercury', from: Date, to: Date, targets: number[]) {
  validateWindow(from, to);
  const values = new Map<number, number>();
  const sample = (at: number) => {
    let longitude = values.get(at);
    if (longitude === undefined) { longitude = norm(exactPosition(bodyId, at).lon - exactPosition('sun', at).lon); values.set(at, longitude); }
    return longitude;
  };
  const results: Array<{ at: number; target: number; residualDegrees: number }> = [];
  const add = (at: number, target: number) => {
    if (at >= to.getTime() || results.some(event => event.target === target && Math.abs(event.at - at) < 1000)) return;
    results.push({ at, target, residualDegrees: angleDistance(sample(at), target) });
  };
  for (let start = from.getTime(); start < to.getTime(); start += 6 * 3600000) {
    const end = Math.min(start + 6 * 3600000, to.getTime());
    for (const target of targets) {
      let lo = start, hi = end, left = signed(sample(lo) - target), right = signed(sample(hi) - target);
      if (Math.abs(left) < 1e-10) add(lo, target);
      if (left * right >= 0 || Math.abs(right - left) >= 180) continue;
      while (hi - lo > 1) {
        const middle = Math.floor((lo + hi) / 2), value = signed(sample(middle) - target);
        if (left * value <= 0) { hi = middle; right = value; } else { lo = middle; left = value; }
      }
      add(Math.abs(left) < Math.abs(right) ? lo : hi, target);
    }
  }
  return results.sort((a, b) => a.at - b.at);
}

export function findLunationEvents(from: Date, to: Date): PlanetCycleEvent[] {
  return relativeCrossings('moon', from, to, [0, 45, 90, 135, 180, 225, 270, 315]).map(event => {
    const phase = phaseFromElongation(event.target);
    return { id: eventId('lunation', 'moon', event.at, String(phase.phaseNumber)), bodyId: 'moon', kind: 'lunation', at: iso(event.at), longitude: exactPosition('moon', event.at).lon, phaseNumber: phase.phaseNumber, phaseName: phase.phaseName, residualDegrees: event.residualDegrees, precisionSeconds: 1 };
  });
}

export function findMercuryConjunctions(from: Date, to: Date): PlanetCycleEvent[] {
  return relativeCrossings('mercury', from, to, [0]).map(event => {
    const mercury = exactPosition('mercury', event.at), conjunctionType = mercury.speed < 0 ? 'inferior' : 'superior';
    return { id: eventId('conjunction', 'mercury', event.at, conjunctionType), bodyId: 'mercury', kind: 'conjunction', at: iso(event.at), longitude: mercury.lon, conjunctionType, direction: mercury.speed < 0 ? 'retrograde' : 'direct', residualDegrees: event.residualDegrees, precisionSeconds: 1 };
  });
}

/** Reuse the timeline's station-aware Swiss sweep for sign crossings and motion reversals. */
export function findPlanetEvents(bodyId: BodyId, from: Date, to: Date): PlanetCycleEvent[] {
  if (!bodyIds.includes(bodyId)) throw new BirthInputError('Invalid body for this cycle.');
  validateWindow(from, to);
  const key = `${bodyId}:${from.toISOString()}:${to.toISOString()}`;
  const cached = cache.get(key);
  if (cached) return cached.map(event => ({ ...event }));
  const sweep = sweepCrossings(bodyId, from, to, Array.from({ length: 12 }, (_, index) => ({ key: String(index), longitude: index * 30 })), 512);
  const events: PlanetCycleEvent[] = sweep.stations.map(station => ({ id: eventId('station', bodyId, station.at, station.turning), bodyId, kind: 'station', at: iso(station.at), longitude: station.longitude, direction: station.turning, precisionSeconds: 60 }));
  for (const crossing of sweep.crossings) {
    const signIndex = (Number(crossing.key) + (crossing.speed < 0 ? 11 : 0)) % 12;
    events.push({ id: eventId('ingress', bodyId, crossing.at, String(signIndex)), bodyId, kind: 'ingress', at: iso(crossing.at), longitude: crossing.longitude, direction: crossing.speed < 0 ? 'retrograde' : 'direct', signIndex, sign: signs[signIndex], residualDegrees: crossing.residualDegrees, precisionSeconds: Math.max(1, crossing.bracketMs / 1000) });
  }
  if (bodyId === 'mercury') events.push(...findMercuryConjunctions(from, to));
  events.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  if (cache.size >= 128) cache.delete(cache.keys().next().value!);
  cache.set(key, events);
  return events.map(event => ({ ...event }));
}

/** Search progressively; slow planets generally reach a station before their next sign ingress. */
export function planetCycle(bodyId: BodyId, at: Date, availableEvents: PlanetCycleEvent[] = []): PlanetCycle {
  if (!bodyIds.includes(bodyId) || !Number.isFinite(at.getTime()) || at.getTime() < MIN || at.getTime() > MAX) throw new BirthInputError('Invalid date or body for this cycle.');
  const position = exactPosition(bodyId, at.getTime());
  let nextEvent = availableEvents.filter(event => event.bodyId === bodyId && ['station', 'ingress', 'conjunction'].includes(event.kind) && Date.parse(event.at) > at.getTime()).sort((a, b) => Date.parse(a.at) - Date.parse(b.at))[0] ?? null;
  // Stop after one tropical year or at the installed coverage boundary; null is an explicit absence.
  if (!nextEvent) {
    const limit = Math.min(at.getTime() + 366 * DAY_MS, MAX);
    for (let start = at.getTime(); start < limit; start += 14 * DAY_MS) {
      const end = Math.min(start + 14 * DAY_MS, limit);
      nextEvent = findPlanetEvents(bodyId, new Date(start), new Date(end)).find(event => Date.parse(event.at) > at.getTime()) ?? null;
      if (nextEvent) break;
    }
  }
  return { bodyId, status: position.speed < 0 ? 'Retrograde' : 'Direct', nextEvent };
}

/** Every exact transit-to-natal pass in this bounded window, without changing the existing timeline. */
export function findTransitPasses(from: Date, to: Date, natal: { id: string; lon: number }[], settings: ChartSettings): PlanetCycleEvent[] {
  validateWindow(from, to);
  if (!natal.length) return [];
  const targets = natal.flatMap(point => Object.keys(settings.orbs).flatMap(angleText => {
    const angle = Number(angleText), offsets = angle === 0 || angle === 180 ? [angle] : [angle, -angle];
    return offsets.map(offset => ({ key: `${point.id}:${angle}:${offset}`, longitude: norm(point.lon + offset) }));
  }));
  const events: PlanetCycleEvent[] = [];
  for (const bodyId of bodyIds) {
    const sweep = sweepCrossings(bodyId, from, to, targets, 4096);
    const passes = new Map<string, number>();
    for (const crossing of sweep.crossings) {
      const [natalPlanet, angleText] = crossing.key.split(':'), angle = Number(angleText), pair = `${natalPlanet}:${angle}`;
      const pass = (passes.get(pair) ?? 0) + 1; passes.set(pair, pass);
      events.push({ id: eventId('exact-aspect', bodyId, crossing.at, pair), bodyId, kind: 'exact-aspect', at: iso(crossing.at), longitude: crossing.longitude, natalPlanet, angle, pass, residualDegrees: crossing.residualDegrees, precisionSeconds: Math.max(1, crossing.bracketMs / 1000) });
    }
  }
  return events.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
}

export function lunationContext(at: Date, events?: PlanetCycleEvent[]): { phaseStart: string | null; phaseEnd: string | null; nextPrincipalEvent: PlanetCycleEvent | null } {
  const candidates = events ?? findLunationEvents(new Date(Math.max(MIN, at.getTime() - 6 * DAY_MS)), new Date(Math.min(MAX, at.getTime() + 10 * DAY_MS)));
  const previous = candidates.filter(event => Date.parse(event.at) <= at.getTime()).at(-1);
  const next = candidates.find(event => Date.parse(event.at) > at.getTime());
  const principal = candidates.find(event => Date.parse(event.at) > at.getTime() && [1, 3, 5, 7].includes(event.phaseNumber as PhaseNumber));
  return { phaseStart: previous?.at ?? null, phaseEnd: next?.at ?? null, nextPrincipalEvent: principal ?? null };
}

