import { createRequire } from 'node:module';
import path from 'node:path';

// Loaded only on the server. Native binaries and ephemeris files are deployment assets.
let engine: any;
export function swiss() {
  if (engine) return engine;
  const req = createRequire(path.join(process.cwd(), 'package.json'));
  try { engine = req('sweph'); }
  catch { throw new Error('Swiss Ephemeris unavailable. Install sweph and configure SWISSEPH_EPHE_PATH; no simulated chart will be returned.'); }
  engine.set_ephe_path(process.env.SWISSEPH_EPHE_PATH || path.join(process.cwd(), 'ephe'));
  return engine;
}
export function swissPosition(bodyName: string, date: Date) {
  const s = swiss();
  const flags = s.constants.SEFLG_SWIEPH | s.constants.SEFLG_SPEED;
  const jd = date.getTime() / 86400000 + 2440587.5;
  const result = s.calc_ut(jd, s.constants[`SE_${bodyName.toUpperCase()}`], flags);
  if (result.flag < 0 || !(result.flag & s.constants.SEFLG_SWIEPH) || !Number.isFinite(result.data[0])) {
    throw new Error(`Swiss Ephemeris: missing files or invalid calculation (${bodyName}). ${result.error || ''}`);
  }
  return { lon: result.data[0] as number, retrograde: result.data[3] < 0 };
}
export function swissAngles(lat: number, lon: number, date: Date, houseSystem: 'equal' | 'whole-sign' | 'placidus' = 'equal') {
  const s = swiss();
  const code = { equal: 'E', 'whole-sign': 'W', placidus: 'P' }[houseSystem];
  const result = s.houses(date.getTime() / 86400000 + 2440587.5, lat, lon, code);
  // Refuse the internal Porphyry fallback for polar Placidus calculations.
  if (result.flag < 0 || !result.data.points.slice(0, 2).every(Number.isFinite) || !result.data.houses.every(Number.isFinite)) throw new Error('Swiss Ephemeris: house system unavailable at these coordinates. Choose equal or whole-sign houses.');
  return { ascendant: result.data.points[0] as number, midheaven: result.data.points[1] as number, cusps: result.data.houses as number[] };
}

