import { BirthInputError } from './birth.ts';
import { defaultChartSettings, type ChartSettings } from '../../src/lib/chart-settings.ts';
export function parseChartSettings(value: unknown = {}): ChartSettings {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new BirthInputError('Invalid calculation settings.');
  const settings = value as Partial<ChartSettings>;
  if (Object.keys(settings).some(k => !['houseSystem', 'orbs'].includes(k))) throw new BirthInputError('Unknown calculation setting.');
  const houseSystem = settings.houseSystem ?? 'equal';
  if (!['equal', 'whole-sign', 'placidus'].includes(houseSystem)) throw new BirthInputError('Invalid house system.');
  if (settings.orbs !== undefined && (!settings.orbs || typeof settings.orbs !== 'object' || Array.isArray(settings.orbs))) throw new BirthInputError('Invalid orbs.');
  const orbs = { ...defaultChartSettings.orbs, ...settings.orbs };
  if (Object.entries(orbs).some(([angle, orb]) => !Object.hasOwn(defaultChartSettings.orbs, angle) || typeof orb !== 'number' || !Number.isFinite(orb) || orb < 0 || orb > 12)) throw new BirthInputError('Orbs must be between 0° and 12° for the five major aspects.');
  return { houseSystem, orbs };
}

