import type { VercelRequest, VercelResponse } from '@vercel/node';
import { DAY_MS, TROPICAL_YEAR_DAYS, bodyIds, parseEventInstant, parseAdvancedBirth, parseBirth, parseChartSettings, BirthInputError, exactPosition, findExactEvents, buildTransitTimeline, maxTimelineOrb, eventPrecision, eventLocation, chartAtInstant } from './_lib/astro-events.ts';
import { swissAngles } from './_lib/swiss.ts';

export default async function handler(req: VercelRequest, res: VercelResponse) {
  res.setHeader('Cache-Control', 'private, no-store');
  if (req.method !== 'POST') return res.status(405).json({ message: 'Method not allowed.' });
  try {
    const body = req.body;
    if (!body || typeof body !== 'object' || Array.isArray(body)) throw new BirthInputError('Invalid event request.');
    const allowed: Record<string, string[]> = { transits: ['mode', 'birth', 'settings', 'movingPlanet', 'natalPoint', 'angle', 'from', 'to'], timeline: ['mode', 'birth', 'settings', 'movingPlanet', 'natalPoint', 'angle', 'orb', 'from', 'to'], return: ['mode', 'birth', 'settings', 'kind', 'year', 'location'], progression: ['mode', 'birth', 'settings', 'at', 'location'], snapshot: ['mode', 'birth', 'settings', 'at', 'location'] };
    if (!Object.hasOwn(allowed, body.mode) || Object.keys(body).some(k => !allowed[body.mode].includes(k))) throw new BirthInputError('Invalid event mode or field.');
    const birth = parseAdvancedBirth(body.birth), parsed = parseBirth(birth), settings = parseChartSettings(body.settings), location = eventLocation(body.location, birth);
    const engine = 'swiss-ephemeris';
    if (body.mode === 'snapshot') { const at = parseEventInstant(body.at); return res.status(200).json({ mode: body.mode, at: at.toISOString(), chart: chartAtInstant(at, settings, location), location, engine, warnings: ['Sky calculated at the selected UTC instant. Houses use the specified location; this chart alone is not a return or progression.'] }); }
    if (body.mode === 'transits' || body.mode === 'timeline') {
      if (!bodyIds.includes(body.movingPlanet) || ![...bodyIds, 'ascendant', 'midheaven'].includes(body.natalPoint) || ![0, 60, 90, 120, 180].includes(body.angle)) throw new BirthInputError('Select a valid planet, natal point, and aspect.');
      if (!parsed.timeKnown && ['moon', 'ascendant', 'midheaven'].includes(body.natalPoint)) throw new BirthInputError('This natal point requires a confirmed birth time and timezone.');
      let target: number;
      if (bodyIds.includes(body.natalPoint)) target = exactPosition(body.natalPoint, parsed.date.getTime()).lon;
      else { if (typeof birth.lat !== 'number' || typeof birth.lon !== 'number') throw new BirthInputError('Ascendant and Midheaven require a confirmed location.'); target = swissAngles(birth.lat, birth.lon, parsed.date, settings.houseSystem)[body.natalPoint as 'ascendant' | 'midheaven']; }
      const from = parseEventInstant(body.from), to = parseEventInstant(body.to);
      const warnings = parsed.timeKnown ? [] : ['Approximate natal reference: events are exact only for this reference position, not for an unknown birth time.'];
      if (body.mode === 'transits') return res.status(200).json({ mode: body.mode, events: findExactEvents(body.movingPlanet, target, body.angle, from, to, body.natalPoint), engine, precision: eventPrecision, warnings });
      if (typeof body.orb !== 'number' || !Number.isFinite(body.orb) || body.orb < 0.1 || body.orb > maxTimelineOrb) throw new BirthInputError(`Enter an orb between 0.1° and ${maxTimelineOrb}°.`);
      const timeline = buildTransitTimeline(body.movingPlanet, target, body.angle, body.orb, from, to, body.natalPoint);
      return res.status(200).json({ mode: body.mode, ...timeline, engine, precision: eventPrecision, warnings: [...warnings, `Timeline with ${body.orb}° orb: entry, exact passes, stations and exit describe transit geometry, not the duration of a life event.`, ...(timeline.periods.some(p => p.openAtStart || p.openAtEnd) ? ['At least one contact extends beyond the search window; expand it to see the complete entry or exit.'] : [])] });
    }
    if (!parsed.timeKnown) throw new BirthInputError('Returns and progressions require a confirmed birth time and timezone.');
    if (body.mode === 'return') {
      if (!['solar', 'lunar'].includes(body.kind) || !Number.isInteger(body.year) || body.year < 1201 || body.year > 2398) throw new BirthInputError('Select a solar/lunar return and a year between 1201 and 2398.');
      const selected = body.kind === 'solar' ? 'sun' : 'moon', target = exactPosition(selected, parsed.date.getTime()).lon;
      const anniversary = Date.UTC(body.year, parsed.date.getUTCMonth(), parsed.date.getUTCDate(), parsed.date.getUTCHours(), parsed.date.getUTCMinutes());
      const from = body.kind === 'solar' ? new Date(anniversary - 7 * DAY_MS) : new Date(`${body.year}-01-01T00:00:00.000Z`);
      const to = body.kind === 'solar' ? new Date(anniversary + 7 * DAY_MS) : new Date(`${body.year + 1}-01-01T00:00:00.000Z`);
      let found = findExactEvents(selected, target, 0, from, to, selected).filter(e => Date.parse(e.at) < to.getTime());
      if (body.kind === 'solar') found = found.sort((a, b) => Math.abs(Date.parse(a.at) - anniversary) - Math.abs(Date.parse(b.at) - anniversary)).slice(0, 1);
      if (!found.length) throw new Error('No convergent return was found for the requested interval.');
      const events = found.map(e => ({ ...e, chart: chartAtInstant(new Date(e.at), settings, location) }));
      return res.status(200).json({ mode: body.mode, kind: body.kind, events, year: body.year, location, engine, precision: eventPrecision, warnings: ['Return to the same natal tropical geocentric longitude. Houses use the birth location or an explicitly supplied alternative.', body.kind === 'solar' ? 'Solar year: return nearest the UTC birthday in the selected year, searched within seven days on either side. The event can fall in the preceding or following civil year.' : 'Lunar returns: all events in the selected UTC calendar year.'] });
    }
    const at = parseEventInstant(body.at), elapsedYears = (at.getTime() - parsed.date.getTime()) / (TROPICAL_YEAR_DAYS * DAY_MS);
    if (elapsedYears < 0 || elapsedYears > 150) throw new BirthInputError('Progression must be between birth and 150 years later.');
    const progressedAt = new Date(Math.round(parsed.date.getTime() + elapsedYears * DAY_MS));
    const warnings = ['Symbolic secondary progression: one mean tropical year of 365.2421897 days corresponds to one ephemeris day after birth. This is not the actual sky on the selected date.', 'Planet positions and aspects only: progressed houses and angles are omitted because they require an additional convention.'];
    return res.status(200).json({ mode: body.mode, chart: chartAtInstant(progressedAt, settings, { source: 'none' }, warnings), at: at.toISOString(), progressedAt: progressedAt.toISOString(), elapsedYears, convention: `one-ephemeris-day-per-${TROPICAL_YEAR_DAYS}-elapsed-days`, location: { source: 'none' }, engine, warnings });
  } catch (error) { return res.status(error instanceof BirthInputError ? 400 : 503).json({ message: error instanceof Error ? error.message : 'Advanced calculation unavailable.' }); }
}

