 return <section ref={ref} tabIndex={-1} role="dialog" aria-modal="false" aria-label="Explain sheet" className={`explain-sheet ${expanded?'expanded':''}`} onTouchStart={e=>{touchY.current=e.touches[0]?.clientY??null;}} onTouchEnd={e=>{if(touchY.current!==null){const dy=(e.changedTouches[0]?.clientY||0)-touchY.current;if(dy>70)p.onClose();else if(dy< -45)setExpanded(true);}}}><div className="sheet-heading"><button type="button" aria-expanded={expanded} onClick={()=>setExpanded(v=>!v)}><strong>{title}</strong><small>{expanded?'Collapse explanation':'Tap to expand explanation'}</small></button><button type="button" className="workspace-secondary" aria-label="Close explanation" onClick={p.onClose}>Close</button></div>
 {!expanded?<p className="workspace-muted">{content}</p>:<><section><h3>Calculated</h3><p>{event?`${eventName(event)} · ${localTime(event.at,p.timeZone)}`:contact?`Transiting ${bodyNames[contact.transitPlanet]} to natal ${bodyNames[contact.natalPlanet]}; ${contact.angle}° aspect, orb ${contact.orb.toFixed(3)}°, ${contact.applying?'Applying':'Separating'}.`:natalAspect?`Natal aspect: ${natalAspect.angle}°, orb ${natalAspect.orb.toFixed(3)}°.`:planet?`Transiting ${bodyNames[planet.id]}: ${planet.lon.toFixed(4)}° longitude; ${planet.degree.toFixed(2)}° in ${planet.sign}; ${planet.retrograde?'R · Retrograde':'Direct'}.`:p.sky?`Phase ${p.sky.moon.phaseNumber}; elongation ${p.sky.moon.phaseAngle.toFixed(3)}°; reference ${localTime(p.sky.at,p.timeZone)}.`:'A calculated sky is not available for this date.'}</p><small>Natal positions stay fixed. Transiting positions follow the selected date.</small></section><section><h3>Astrological meaning</h3><p>{content}</p><small>Source: {meaning?.source||'Traditional Western planetary symbolism; original Hermit wording.'} · Original app text · Owner review pending.</small></section><section><h3>Your log</h3><p>{logError||`n = ${entries.length}. ${entries.length?entries.map(e=>`Mood ${e.mood}/5; energy ${e.energy}/5. ${e.note}`).join(' '):'No entry recorded for this person and date.'}`}</p></section><div className="sheet-links" aria-label="Show in"><strong>Show in:</strong>{(['calendar','timing','space','chart','aspects'] as const).map((v,i)=><button type="button" className="workspace-secondary" key={v} onClick={()=>p.onNavigate(v)}>{['Calendar','Timeline','Space','Mandala','Aspects'][i]}</button>)}</div></>}
 </section>;
}

