import { lazy, Suspense, useEffect, useId, useMemo, useState } from 'react';
import type { ComputedChart } from '../lib/astro';
import { NatalChartWheel } from './NatalChartWheel';
import { ChartProvenance } from './ChartProvenance';
import { aspectLearning, houseTopics } from '../lib/chart-learning';
import { houseSystemNames } from '../lib/chart-settings';
import { ChartJournal } from './ChartJournal';
import { AstroGlyph } from './AstroGlyph';
import { ChartElementExplanation, describeAspectPair, type ChartElementSelection } from './ChartElementExplanation';
import { PlanetInterpretation } from './PlanetInterpretation';
import { zodiacNames, type PlacementFilter } from '../lib/catalog';
import { Clock } from 'lucide-react';
import { journalProfile } from '../lib/journal';

const ChartReport = lazy(() => import('./ChartReport').then(module => ({ default: module.ChartReport })));

export const planetNames: Record<string, string> = { sun: 'Sun', moon: 'Moon', mercury: 'Mercury', venus: 'Venus', mars: "Mars", jupiter: 'Jupiter', saturn: "Saturn", uranus: "Uranus", neptune: "Neptune", pluto: 'Pluto', ascendant: "Ascendant", midheaven: 'Midheaven' };
const glyphs: Record<string, string> = { sun: '☉', moon: '☽', mercury: '☿', venus: '♀', mars: '♂', jupiter: '♃', saturn: '♄', uranus: '♅', neptune: '♆', pluto: '♇', ascendant: 'AC', midheaven: 'MC' };
const colors: Record<string, string> = { sun: '#e8c878', moon: '#c6d8de', mercury: '#d4b4a1', venus: '#ecb8c0', mars: '#e99a84', jupiter: '#d0c6ae', saturn: '#e5cc88', uranus: '#9ed7ce', neptune: '#98bfdc', pluto: '#c4aedb', ascendant: '#c4aedb', midheaven: '#c4aedb' };
export function PlanetBadge({ id, owner }: { id: string; owner?: string }) {
  return <span className="planet-badge" style={{ background: colors[id] || '#ccd0dc' }} aria-label={`${planetNames[id] || id}${owner ? ` · ${owner}` : ''}`}><AstroGlyph symbol={glyphs[id] || id} size={19} color="#171820" />{owner && <small title={owner}>{owner.slice(0, 1).toUpperCase()}</small>}</span>;
}

export function ViewTabs<T extends string>({ options, value, onChange, label }: { options: { id: T; label: string }[]; value: T; onChange: (id: T) => void; label: string }) {
  return <nav className="chart-view-tabs" aria-label={label}>{options.map(o => <button type="button" key={o.id} aria-current={value === o.id ? 'page' : undefined} onClick={() => onChange(o.id)}>{o.label}</button>)}</nav>;
}

export function AspectsList({ aspects, firstName, secondName, uncertain = false, comparisonKind = 'synastry' }: { aspects: ComputedChart['aspects']; firstName?: string; secondName?: string; uncertain?: boolean; comparisonKind?: 'synastry' | 'transit' }) {
  const [filter, setFilter] = useState('');
  const [sort, setSort] = useState('orb');
  const rows = useMemo(() => aspects.filter(a => (!uncertain || (a.a !== 'moon' && a.b !== 'moon')) && (!filter || a.type === filter)).sort((a, b) => sort === 'orb' ? a.orb - b.orb : b.weight - a.weight), [aspects, uncertain, filter, sort]);
  return <div className="space-y-4">
    <div className="flex flex-wrap justify-between items-center gap-3"><p className="workspace-muted text-sm">{rows.length}  aspects {secondName && `· ${firstName} → ${secondName}`}</p><div className="flex gap-2 flex-wrap"><select aria-label={"Filter aspects"} value={filter} onChange={e => setFilter(e.target.value)}><option value="">All aspects</option>{[...new Set(aspects.map(a => a.type))].map(t => <option key={t}>{t}</option>)}</select><select aria-label={"Sort aspects"} value={sort} onChange={e => setSort(e.target.value)}><option value="orb">Smallest orb</option><option value="weight">Highest weight</option></select></div></div>
    {uncertain && <p className="workspace-note">Moon contacts are omitted because birth time is unknown. Ascendant and Midheaven appear only when calculable.</p>}
    <ul className="aspect-list">{rows.map(a => { const pair = describeAspectPair(a.a, a.b, a.angle, { a: comparisonKind === 'transit' ? `${planetNames[a.a] || a.a} in transit` : `${planetNames[a.a] || a.a}${secondName && firstName ? ` for ${firstName}` : ''}`, b: `${planetNames[a.b] || a.b}${secondName ? `${comparisonKind === 'transit' ? ' natal' : ''} for ${secondName}` : ''}`, comparisonKind }); return <li key={`${a.a}-${a.b}`}><details><summary className="aspect-row"><div className="aspect-icons"><PlanetBadge id={a.a} owner={secondName ? firstName : undefined} /><span className="aspect-symbol" aria-hidden="true"><AstroGlyph symbol={({ 0: '☌', 60: '⚹', 90: '□', 120: '△', 180: '☍' } as Record<number, string>)[a.angle]} size={18} /></span><PlanetBadge id={a.b} owner={secondName} /></div><div className="aspect-names"><strong>{planetNames[a.a] || a.a} · {planetNames[a.b] || a.b}</strong>{secondName && <small>{firstName} · {secondName}</small>}</div><span className={`aspect-type ${a.vibe}`}>{a.type}</span><span className="aspect-orb" title="Distance from the exact aspect">{a.orb.toFixed(2)}°</span></summary><p className="workspace-muted text-xs leading-relaxed pb-4 pl-3">{aspectLearning[a.type]} Orb of {a.orb.toFixed(2)}°: distance from the exact angle of {a.angle}°. {secondName ? comparisonKind === 'transit' ? `The first point is in the selected sky; the second is natal for ${secondName}.` : `The first point belongs to ${firstName}; the second to ${secondName}.` : 'Both points belong to this chart.'}</p>{pair && <div className="space-y-3 pb-4 pl-3" data-testid="aspect-list-pair-context"><h4 className="text-sm font-semibold">What these points bring into dialogue</h4><p className="workspace-muted text-xs leading-relaxed">{pair.context}</p><h4 className="text-sm font-semibold">For reflection</h4><p className="workspace-muted text-xs leading-relaxed">{pair.reflection}</p>{secondName && <p className="workspace-muted text-xs leading-relaxed">{comparisonKind === 'transit' ? 'This comparison relates the selected sky instant to the natal chart. Use these questions for reflection; a planetary transit does not determine events.' : 'In synastry, each person can answer from their own experience. Compare needs and agreements; geometry does not determine relationship quality.'}</p>}</div>}</details></li>; })}</ul>
    {!rows.length && <p className="workspace-muted py-8 text-center">No aspects match this filter.</p>}
  </div>;
}

export function ChartDetails({ chart, name, initialLayout = 'guided', initialPlanetId = 'sun', onExplorePlacement, selectedPlanetId, onSelectBody, onSelectAspect, initialView }: { chart: ComputedChart; name: string; initialLayout?: 'guided' | 'research'; initialPlanetId?: string; selectedPlanetId?: string; onSelectBody?: (id: string) => void; onSelectAspect?: (a: string, b: string) => void; initialView?: 'overview' | 'planets' | 'houses' | 'aspects' | 'journal' | 'details' | 'report'; onExplorePlacement?: (placement: PlacementFilter) => void }) {
  const [layout, setLayout] = useState(initialLayout);
  const [view, setView] = useState<'overview' | 'planets' | 'houses' | 'aspects' | 'journal' | 'details' | 'report'>(initialView || 'overview');
  const id = useId();
  const uncertain = chart.metadata?.timeKnown !== true;
  const [selectedPlanet, setSelectedPlanet] = useState(selectedPlanetId || initialPlanetId);
  const [zoom, setZoom] = useState(1);
  const [element, setElement] = useState<ChartElementSelection | null>(null);
  useEffect(() => { if (selectedPlanetId) setSelectedPlanet(selectedPlanetId); }, [selectedPlanetId]);
  function selectPlanet(id: string) { setSelectedPlanet(id); onSelectBody?.(id); setElement(null); }
  function selectAspect(a: string, b: string) { setElement({ kind: 'aspect', a, b }); onSelectAspect?.(a, b); }
  const selectable = selectablePoints(chart);
  const selected = selectable.find(p => p.id === selectedPlanet) || selectable[0];
  return <div className="space-y-6" data-testid="chart-details">
    {chart.metadata?.timeKnown && chart.metadata.warnings.map((warning, index) => <p key={index} className="workspace-note text-sm">{warning}</p>)}
    <div className="chart-layout-switch" role="group" aria-label="Chart presentation"><button className="workspace-secondary" aria-pressed={layout === 'guided'} onClick={() => setLayout('guided')}>Guided view</button><button className="workspace-secondary" aria-pressed={layout === 'research'} onClick={() => setLayout('research')}>Research view</button><button type="button" className="workspace-secondary" onClick={() => { setLayout('guided'); setView('report'); setElement(null); }}>Full report</button></div>
    {layout === 'research' ? <ResearchChart chart={chart} name={name} onExplorePlacement={onExplorePlacement} /> : <>
    <ViewTabs<typeof view> value={view} onChange={setView} label={`Chart sections for ${name}`} options={[{ id: 'overview', label: 'Mandala' }, { id: 'planets', label: 'Planets' }, { id: 'houses', label: 'Houses' }, { id: 'aspects', label: 'Aspects' }, { id: 'report', label: 'Report' }, { id: 'journal', label: 'Journal' }, { id: 'details', label: "Details" }]} />
    <div id={id}>
      {view === 'report' && <Suspense fallback={<p role="status" className="workspace-muted">Preparing chart report…</p>}><ChartReport chart={chart} name={name} onSelectPlanet={id => { selectPlanet(id); setView('overview'); }} onSelectSign={index => { setElement({ kind: 'sign', index }); setView('overview'); }} onSelectHouse={number => { setElement({ kind: 'house', number }); setView('overview'); }} onSelectAspect={(a, b) => { selectAspect(a, b); setView('overview'); }} /></Suspense>}
      {view === 'journal' && <ChartJournal key={journalProfile(chart)} profile={journalProfile(chart)} name={name} context={`Chart for ${name}. UTC reference: ${chart.metadata?.utc || 'not supplied'}. Sun: ${chart.bigThree.sol}. ${uncertain ? 'Unknown birth time: approximate Moon, no houses or Ascendant.' : `Moon: ${chart.bigThree.lua}. Ascendant: ${chart.bigThree.ascendente || 'unavailable'}.`} Engine: ${chart.metadata?.engine || 'not supplied'}.`} />}
      {view === 'overview' && <><div className="big-three summary-three">{[{ id: 'sun', label: 'Sun', value: chart.bigThree.sol }, { id: 'moon', label: 'Moon', value: uncertain ? 'Birth time required' : chart.bigThree.lua }, { id: 'ascendant', label: "Ascendant", value: chart.bigThree.ascendente || (uncertain ? 'Time and location required' : 'Not calculated in this chart') }].map(p => <button type="button" key={p.id} onClick={() => selectPlanet(p.id)} disabled={p.id === 'ascendant' && chart.ascendant == null} aria-label={`Understand ${p.label}: ${p.value}`}><PlanetBadge id={p.id} /><span><small>{p.label}</small><strong>{p.value}</strong></span></button>)}</div>{uncertain && <p className="workspace-note">Unconfirmed birth time: approximate Moon on the wheel; houses and Ascendant unavailable.</p>}<p className="workspace-muted text-xs mb-3">Click planets, signs, houses and aspect lines to understand each part. You can also use Tab and Enter.</p><div className="interactive-mandala"><aside className="mandala-planets" aria-label={"Select a planet on the chart wheel"}>{selectable.map(p => <button key={p.id} aria-pressed={selectedPlanet === p.id} onClick={() => selectPlanet(p.id)}><PlanetBadge id={p.id} /><span>{p.name}<small>{p.id === 'moon' && uncertain ? 'Approximate reference' : p.sign}</small></span></button>)}</aside><div className="mandala-canvas"><div className="mandala-zoom"><button aria-label={"Zoom out"} disabled={zoom <= 1} onClick={() => setZoom(z => Math.max(1, z - 0.25))}>−</button><button onClick={() => setZoom(1)} aria-label={"Reset zoom"}>{Math.round(zoom * 100)}%</button><button aria-label={"Zoom in"} disabled={zoom >= 2} onClick={() => setZoom(z => Math.min(2, z + 0.25))}>+</button></div><div className="mandala-scroll"><div style={{ width: `${zoom * 100}%`, minWidth: '100%' }}><NatalChartWheel chart={chart} selectedPlanet={selectedPlanet} onSelectPlanet={selectPlanet} onSelectSign={index => setElement({ kind: 'sign', index })} onSelectHouse={number => setElement({ kind: 'house', number })} onSelectAspect={(a, b) => setElement({ kind: 'aspect', a, b })} /></div></div></div></div>{!element && <div className="workspace-panel space-y-4" aria-live="polite"><div className="section-heading"><div className="flex gap-3 items-center"><PlanetBadge id={selected.id} /><div><h3>{selected.id === 'moon' && uncertain ? 'Moon · birth time required' : `${selected.name} in ${selected.sign}`}</h3><p className="workspace-muted text-sm">{selected.id === 'moon' && uncertain ? 'Approximate noon reference' : `${selected.degree.toFixed(2)}°`}{selected.house ? ` · House ${selected.house}` : ' · House unavailable'}{selected.retrograde ? ' · Retrograde' : ''}</p></div></div><span>Selected planet</span></div><PlanetInterpretation chart={chart} planetId={selected.id} name={name} onExplorePlacement={onExplorePlacement} /><h4 className="text-sm">Aspects for this placement</h4><AspectsList aspects={chart.aspects.filter(a => a.a === selected.id || a.b === selected.id)} uncertain={uncertain} /></div>}</>}
      {view === 'planets' && <div className="workspace-panel"><div className="section-heading"><h3>Planet positions</h3><span>10 bodies</span></div><div className="planet-table">{chart.planets.map(p => <button key={p.id} className="planet-row" type="button" aria-label={`Read ${p.name} in ${p.sign}`} onClick={() => { selectPlanet(p.id); setView('overview'); }}><PlanetBadge id={p.id} /><div><strong>{p.name}</strong><small>{p.id === 'moon' && uncertain ? 'Noon reference' : p.retrograde ? 'Retrograde' : "Direct"}</small></div><span><AstroGlyph symbol={p.signSymbol} size={18} /> {p.sign}</span><span className="tabular-nums">{p.degree.toFixed(2)}°</span><span className="workspace-muted">{p.house ? `House ${p.house}` : "No house"}</span></button>)}</div></div>}
      {view === 'houses' && <div className="workspace-panel"><div className="section-heading"><h3>The 12 houses</h3><span>{houseSystemNames[chart.metadata?.houseSystem || 'equal']} · tropical</span></div>{chart.houses ? <div className="house-grid">{chart.houses.map(h => <button type="button" key={h.number} aria-label={`Understand House ${h.number} in ${h.sign}`} onClick={() => setElement({ kind: 'house', number: h.number })}><span className="house-number">{String(h.number).padStart(2, '0')}</span><div><strong><AstroGlyph symbol={h.signSymbol} size={18} /> {h.sign}</strong><small>{h.degree.toFixed(2)}° · cusp</small><small>{houseTopics[h.number - 1]}</small></div></button>)}</div> : <div className="workspace-empty"><span><Clock size={32} aria-hidden="true" /></span><h3>{uncertain ? 'Birth time matters.' : 'Houses not calculated in this chart.'}</h3><p>{uncertain ? 'Enter a confirmed time, city and timezone to calculate houses and Ascendant. These inputs are never guessed.' : 'See the method and limitations in Details. A chart can have calculated planet positions without houses or angles.'}</p></div>}</div>}
      {view === 'aspects' && <div className="workspace-panel"><h3 className="mb-5">Chart aspects</h3><AspectsList aspects={chart.aspects} uncertain={uncertain} /></div>}
      {view === 'details' && <div className="workspace-panel space-y-4"><h3>How this chart was calculated</h3><ChartProvenance chart={chart} /><p className="workspace-muted text-sm">Tropical zodiac, geocentric positions and house system {houseSystemNames[chart.metadata?.houseSystem || 'equal']}. Aspects: conjunction, sextile, square, trine and opposition, using the calculation engine orbs.</p><p className="workspace-muted text-sm">Astronomical position accuracy does not validate personality interpretations or forecasts.</p></div>}
      {element && <ChartElementExplanation chart={chart} selection={element} onClose={() => setElement(null)} onSelectPlanet={id => { selectPlanet(id); setView('overview'); }} />}
    </div></>}
  </div>;
}

function selectablePoints(chart: ComputedChart) {
  const angles = chart.metadata?.timeKnown ? [{ id: 'ascendant', symbol: 'AC', lon: chart.ascendant }, { id: 'midheaven', symbol: 'MC', lon: chart.midheaven }].filter(p => p.lon != null).map(p => ({ id: p.id, symbol: p.symbol, name: planetNames[p.id], lon: p.lon!, sign: zodiacNames[Math.floor(p.lon! / 30)], signSymbol: '', degree: p.lon! % 30, house: 0, retrograde: false })) : [];
  return [...chart.planets, ...angles];
}

function ResearchChart({ chart, name, onExplorePlacement }: { chart: ComputedChart; name: string; onExplorePlacement?: (placement: PlacementFilter) => void }) {
  const [selected, setSelected] = useState('sun');
  const [element, setElement] = useState<ChartElementSelection | null>(null);
  function selectPlanet(id: string) { setSelected(id); setElement(null); }
  const uncertain = !chart.metadata?.timeKnown;
  const points = [...chart.planets.filter(p => !uncertain || p.id !== 'moon').map(p => p.id), ...(!chart.metadata?.timeKnown || chart.ascendant == null ? [] : ['ascendant']), ...(!chart.metadata?.timeKnown || chart.midheaven == null ? [] : ['midheaven'])];
  const symbols: Record<number, string> = { 0: '☌', 60: '⚹', 90: '□', 120: '△', 180: '☍' };
  return <div className="space-y-5" data-testid="research-chart"><div className="section-heading"><div><p className="workspace-eyebrow">Positions, houses and aspects</p><h3>{name}</h3></div><span>{houseSystemNames[chart.metadata?.houseSystem || 'equal']} · tropical</span></div>{uncertain && <p className="workspace-note">Unknown birth time: approximate noon Moon, excluded from the matrix. Ascendant, Midheaven and houses unavailable.</p>}<div className="research-grid"><aside className="workspace-panel research-positions" aria-label="Research chart positions"><h3 className="mb-4">Positions</h3>{selectablePoints(chart).map(p => <button key={p.id} aria-pressed={selected === p.id} onClick={() => selectPlanet(p.id)}><PlanetBadge id={p.id} /><span>{p.name}<small>{p.sign}{p.retrograde ? ' · R' : ''}{p.id === 'moon' && uncertain ? ' · approx.' : ''}</small></span><span>{p.degree.toFixed(2)}°<small>{p.house ? `House ${p.house}` : "No house"}</small></span></button>)}{chart.ascendant != null && <p className="workspace-muted text-xs mt-4">ASC {chart.bigThree.ascendente} · {(chart.ascendant % 30).toFixed(2)}°</p>}{chart.midheaven != null && <p className="workspace-muted text-xs mt-2">MC · longitude {chart.midheaven.toFixed(2)}°</p>}</aside><div className="mandala-canvas"><NatalChartWheel chart={chart} selectedPlanet={selected} onSelectPlanet={selectPlanet} onSelectSign={index => setElement({ kind: 'sign', index })} onSelectHouse={number => setElement({ kind: 'house', number })} onSelectAspect={(a, b) => setElement({ kind: 'aspect', a, b })} /></div></div>{element && <ChartElementExplanation chart={chart} selection={element} onClose={() => setElement(null)} onSelectPlanet={selectPlanet} />}<div className="workspace-panel space-y-4"><h3>Aspect matrix</h3><p className="workspace-muted text-xs">Click a cell to understand the pair. The lower triangle shows its angle and orb. A dash means no aspect lies within the chosen orbs.</p><div className="catalog-table-scroll"><table className="catalog-table aspect-matrix"><caption className="sr-only">Chart aspects for {name}</caption><thead><tr><th>Point</th>{points.map(id => <th key={id} scope="col"><button type="button" onClick={() => selectPlanet(id)} aria-label={`Read ${planetNames[id]}`}><PlanetBadge id={id} /></button></th>)}</tr></thead><tbody>{points.map((id, i) => <tr key={id}><th scope="row"><button type="button" onClick={() => selectPlanet(id)}>{planetNames[id]}</button></th>{points.map((other, j) => { const a = i > j ? chart.aspects.find(a => (a.a === id && a.b === other) || (a.b === id && a.a === other)) : undefined; return <td key={other}>{i === j ? <span className="workspace-muted">·</span> : i < j ? null : a ? <button type="button" className="aspect-matrix-action" onClick={() => setElement({ kind: 'aspect', a: id, b: other })} aria-label={`Understand ${a.type} between ${planetNames[id]} and ${planetNames[other]}, orb ${a.orb.toFixed(2)} degrees`}><AstroGlyph symbol={symbols[a.angle]} size={16} /><small>{a.orb.toFixed(2)}°</small></button> : <button type="button" className="aspect-matrix-action workspace-muted" onClick={() => setElement({ kind: 'aspect', a: id, b: other })} aria-label={`Understand the absence of an aspect between ${planetNames[id]} and ${planetNames[other]}`}>—</button>}</td>; })}</tr>)}</tbody></table></div></div><div className="workspace-panel"><h3 className="mb-4">Houses</h3>{chart.houses ? <div className="house-grid">{chart.houses.map(h => <button type="button" key={h.number} aria-label={`Understand House ${h.number} in ${h.sign}`} onClick={() => setElement({ kind: 'house', number: h.number })}><span className="house-number">{h.number}</span><div><strong>{h.sign} · {h.degree.toFixed(2)}°</strong><small>{houseTopics[h.number - 1]}</small></div></button>)}</div> : <p className="workspace-muted text-sm">{uncertain ? 'Confirmed birth time and location are required to calculate cusps.' : 'Houses and angles were not calculated in this chart. See the method and limitations below.'}</p>}</div>{!element && <div className="workspace-panel space-y-5" aria-live="polite"><PlanetInterpretation chart={chart} planetId={selected} name={name} onExplorePlacement={onExplorePlacement} /><h3 className="mb-4">Contacts for {planetNames[selected]}</h3><AspectsList aspects={chart.aspects.filter(a => a.a === selected || a.b === selected)} uncertain={uncertain} /></div>}<div className="workspace-panel"><ChartProvenance chart={chart} /></div></div>;
}

