import type { BirthDetails } from '../types';
import type { ComputedChart } from '../lib/astro';
import type { DailySkyResponse,PlanetCycleEvent,DailyContact } from '../lib/daily-sky';
import { lunationPhaseNamesEn } from '../lib/phase-cycle';
import { AstroGlyph } from './AstroGlyph';
export const bodyNames:Record<string,string>={sun:'Sun',moon:'Moon',mercury:'Mercury',venus:'Venus',mars:'Mars',jupiter:'Jupiter',saturn:'Saturn',uranus:'Uranus',neptune:'Neptune',pluto:'Pluto'};
export const bodyGlyphs:Record<string,string>={sun:'☉',moon:'☽',mercury:'☿',venus:'♀',mars:'♂',jupiter:'♃',saturn:'♄',uranus:'♅',neptune:'♆',pluto:'♇'};
export function eventName(e:PlanetCycleEvent):string{return e.kind==='station'?`${bodyNames[e.bodyId]} station ${e.direction==='retrograde'?'retrograde':'direct'}`:e.kind==='ingress'?`${bodyNames[e.bodyId]} enters ${e.sign||'a sign'}`:e.kind==='lunation'?e.phaseName||'Lunation event':e.kind==='conjunction'?`Mercury ${e.conjunctionType} conjunction with Sun`:`${bodyNames[e.bodyId]} exact aspect with ${bodyNames[e.natalPlanet||'sun']}`;}
export function localTime(at:string,timeZone:string){return new Date(at).toLocaleString('en-GB',{timeZone,dateStyle:'medium',timeStyle:'short'});}
interface Props {date:string;timeZone:string;birth:BirthDetails;chart:ComputedChart|null;featuredPlanetId:string;sky:DailySkyResponse|null;error:string|null;onRetry:()=>void;onDateChange:(date:string)=>void;onBody:(id:string)=>void;onPhase:(phase:number)=>void;onContact:(c:DailyContact)=>void;onEvent:(e:PlanetCycleEvent)=>void;onProfile:()=>void;onLog:()=>void}
export function DailyOverview(p:Props){const s=p.sky,featured=s?.planets.find(b=>b.id===p.featuredPlanetId),cycle=s?.planetCycles.find(c=>c.bodyId===p.featuredPlanetId);
 return <section className="daily-overview" data-testid="daily-overview">
  <p className="workspace-note" data-testid="personalization-status">{p.chart?`Saved profile: ${p.birth.name||'Selected profile'} · ${p.birth.date} · ${p.birth.time||'Birth time unknown'} · ${p.birth.location||p.birth.timezone||'No place supplied'}`:'General sky. Add birth data to compare these transits with a natal chart.'} <button type="button" className="workspace-secondary" onClick={p.onProfile}>{p.chart?'Edit birth data':'Add birth data'}</button></p>
  {p.error?<div role="alert" className="daily-status"><p>{p.error}</p><button className="workspace-primary" onClick={p.onRetry}>Try again</button></div>:!s?<p role="status" className="workspace-note">Calculating the selected day…</p>:<>
  <article className="daily-lunar-card lunation-card"><div><p className="daily-eyebrow">Lunation cycle</p><h2>Day {s.moon.dayOfPhase??'—'} of {s.moon.phaseNameEn}</h2><p>{Math.round(s.moon.illuminationPercent)}% illuminated · {p.date}</p><small>{s.moon.phaseStart?`Phase began ${localTime(s.moon.phaseStart,p.timeZone)}`:'Phase start outside installed coverage'}</small></div><svg viewBox="0 0 240 240" className="lunation-ring" role="img" aria-label={`You are here: phase ${s.moon.phaseNumber}, ${s.moon.phaseNameEn}`}><circle cx="120" cy="120" r="86" fill="none" stroke="#ffffff20" strokeWidth="25"/>{lunationPhaseNamesEn.map((name,i)=>{const a=i*Math.PI/4-Math.PI/2,b=a+Math.PI/4-.04;return <path key={name} d={`M${120+86*Math.cos(a)} ${120+86*Math.sin(a)} A86 86 0 0 1 ${120+86*Math.cos(b)} ${120+86*Math.sin(b)}`} stroke={s.moon.phaseNumber===i+1?'#f0d6ad':'#ffffff38'} strokeWidth="25" fill="none"/>;})}<text x="120" y="113" textAnchor="middle" fill="#fff" fontSize="16">You are here</text><text x="120" y="139" textAnchor="middle" fill="#f0d6ad" fontSize="25">{s.moon.phaseNumber} / 8</text></svg><div className="phase-buttons">{lunationPhaseNamesEn.map((name,i)=><button type="button" aria-pressed={s.moon.phaseNumber===i+1} key={name} onClick={()=>p.onPhase(i+1)}>{i+1}. {name}</button>)}</div></article>
  <button type="button" className="workspace-panel featured-card" onClick={()=>p.onBody(p.featuredPlanetId)} aria-label={`Explore featured planet ${bodyNames[p.featuredPlanetId]}`}><AstroGlyph symbol={bodyGlyphs[p.featuredPlanetId]} size={36}/><div><p className="workspace-eyebrow">Featured planet · Sun-sign ruler or your choice</p><h2>{bodyNames[p.featuredPlanetId]} · {featured?.sign}</h2><p>{featured?.retrograde?'R · Retrograde':'Direct'} · {featured?.degree.toFixed(2)}° in sign</p><small>{cycle?.nextEvent?`Next: ${eventName(cycle.nextEvent)} · ${localTime(cycle.nextEvent.at,p.timeZone)}`:'No upcoming event within the calculated search window.'}</small></div></button>
  <article className="workspace-panel"><h3>Top transits</h3><p className="workspace-muted text-sm">Transiting planets compared with natal planets · noon in {p.timeZone}</p>{s.topContacts.length?<div className="top-transits">{s.topContacts.map(c=><button type="button" className="workspace-secondary" key={`${c.transitPlanet}-${c.natalPlanet}-${c.angle}`} onClick={()=>p.onContact(c)}><span>{bodyNames[c.transitPlanet]} · {c.type} · natal {bodyNames[c.natalPlanet]||c.natalPlanet}</span><small>{c.orb.toFixed(2)}° from exact · {c.applying?'Applying':'Separating'}</small></button>)}</div>:<p className="workspace-muted">{p.chart?'No contacts within the selected orbs at this reference instant.':'Add a birth profile for personal transits.'}</p>}</article>
  <section aria-label="14-day strip"><h3>Explore the next 14 days</h3><div className="fourteen-day-strip">{s.fourteenDayStrip.map(d=><button type="button" key={d.date} aria-pressed={d.date===p.date} aria-label={`${d.date}: ${d.phaseNameEn}`} onClick={()=>p.onDateChange(d.date)}><strong>{d.date.slice(5)}</strong><span>{d.phaseNameEn}</span><small>{d.events.length?'● Event':'·'}</small></button>)}</div></section>
  <button type="button" className="workspace-primary log-prompt" onClick={p.onLog}>How do you feel today?</button>
  </>}
 </section>;
}

