import { useEffect, useId, useRef } from 'react';
import { X } from 'lucide-react';
import type { ComputedChart } from '../lib/astro';
import { zodiacNames } from '../lib/catalog';
import { aspectLearning, houseTopics } from '../lib/chart-learning';
import { describeAspectPair } from '../lib/aspect-interpretation';

export type ChartElementSelection = { kind: 'sign'; index: number } | { kind: 'house'; number: number } | { kind: 'aspect'; a: string; b: string };
const signMeanings = [
  'Aries is a fire sign associated with initiative, directness and beginning. For a planet, it describes a style of action rather than an entire personality.',
  'Taurus is an earth sign associated with consistency, the senses and building security. Consider continuity, resources and sustainable rhythms when reading a planet here.',
  'Gemini is an air sign associated with curiosity, language and exchanging information. Consider how a planet learns, communicates and explores possibilities.',
  'Cancer is a water sign associated with care, memory and belonging. Consider bonds, protection and needs for emotional support.',
  'Leo is a fire sign associated with creativity, expression and participation. Consider generosity and recognition without assuming every placement means extroversion.',
  'Virgo is an earth sign associated with observation, discernment and improvement. Consider habits, standards and practical forms of care.',
  'Libra is an air sign associated with dialogue, reciprocity and different perspectives. Consider choices, negotiation and cooperation.',
  'Scorpio is a water sign associated with depth, trust and investigation. Reflect on intimacy and change without predicting crises or inevitable behavior.',
  'Sagittarius is a fire sign associated with exploration, learning and meaning. Consider expanding horizons, beliefs and possibilities.',
  'Capricorn is an earth sign associated with time, responsibility and consistency. Consider limits and commitments without reducing the sign to ambition or work.',
  'Aquarius is an air sign associated with autonomy, collective perspectives and revising patterns. Consider ideas, networks and alternative ways to participate.',
  'Pisces is a water sign associated with imagination, receptivity and sensitivity. Explore inspiration, empathy and boundaries without assuming special powers or intuitive certainty.',
];


export { describeAspectPair } from '../lib/aspect-interpretation';

export function ChartElementExplanation({ chart, selection, onClose, onSelectPlanet }: { chart: ComputedChart; selection: ChartElementSelection; onClose: () => void; onSelectPlanet: (id: string) => void }) {
  const headingId = useId();
  const headingRef = useRef<HTMLHeadingElement>(null);
  const selectionKey = JSON.stringify(selection);
  useEffect(() => {
    const previous = document.activeElement;
    headingRef.current?.focus({ preventScroll: true });
    headingRef.current?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'nearest' });
    return () => { if ((previous instanceof HTMLElement || previous instanceof SVGElement) && previous.isConnected && previous !== document.body) previous.focus({ preventScroll: true }); };
  }, [selectionKey]);
  let title = '', explanation = '', geometry = '', pairContext = '', reflection = '', members: string[] = [];
  const name = (id: string) => chart.planets.find(p => p.id === id)?.name || ({ ascendant: "Ascendant", midheaven: 'Midheaven' } as Record<string, string>)[id] || id;
  if (selection.kind === 'sign') {
    title = `Understand ${zodiacNames[selection.index]}`;
    explanation = signMeanings[selection.index];
    geometry = `${zodiacNames[selection.index]} occupies ${selection.index * 30}° to ${(selection.index + 1) * 30}° of the tropical zodiac. Signs divide the zodiac into twelve 30° sectors; houses are a different division.`;
    members = chart.planets.filter(p => Math.floor(p.lon / 30) === selection.index && (chart.metadata?.timeKnown || p.id !== 'moon')).map(p => p.id);
  } else if (selection.kind === 'house') {
    const house = chart.metadata?.timeKnown ? chart.houses?.find(h => h.number === selection.number) : null;
    title = `Understand House ${selection.number}`;
    explanation = `In astrology, this house relates to ${houseTopics[selection.number - 1]}. A house describes an area of experience; planets within it add functions and themes.`;
    geometry = house ? `A cusp marks the start of a house. In this chart, House ${house.number} begins in ${house.sign} at ${house.degree.toFixed(2)}° in the sign (longitude ${house.cuspLon.toFixed(2)}°). The selected house system can change this division.` : 'A confirmed time, location and timezone are required to calculate this house.';
    members = house ? chart.planets.filter(p => p.house === house.number).map(p => p.id) : [];
  } else {
    const a = selection.a, b = selection.b;
    const eligible = chart.metadata?.timeKnown || ![a, b].some(id => ['moon', 'ascendant', 'midheaven'].includes(id));
    const aspect = eligible ? chart.aspects.find(item => (item.a === a && item.b === b) || (item.a === b && item.b === a)) : undefined;
    const longitude = (id: string) => id === 'ascendant' ? chart.ascendant : id === 'midheaven' ? chart.midheaven : chart.planets.find(p => p.id === id)?.lon;
    const first = longitude(a), second = longitude(b);
    const separation = first != null && second != null ? Math.min(Math.abs(first - second), 360 - Math.abs(first - second)) : null;
    title = `${name(a)} and ${name(b)}${aspect ? ` · ${aspect.type}` : ''}`;
    geometry = `${separation == null ? '' : `Calculated angular separation: ${separation.toFixed(2)}°. `}${aspect ? `Reference angle: ${aspect.angle}°. Orb: ${aspect.orb.toFixed(2)}°, the distance from that exact angle.` : 'None of the five major aspects falls within the selected orbs for this pair.'}`;
    explanation = aspect ? aspectLearning[aspect.type] || 'An aspect relates two chart functions through their angular separation.' : 'An empty aspect cell does not mean insignificance, conflict or absence of a relationship. This pair simply falls outside the chosen calculation angles and limits.';
    if (aspect) {
      const pair = describeAspectPair(a, b, aspect.angle, { a: name(a), b: name(b) });
      pairContext = pair?.context || ''; reflection = pair?.reflection || '';
    }
    if (!eligible) { explanation = 'Confirmed birth time, location and timezone are required to interpret contacts with the Moon, Ascendant and Midheaven.'; geometry = 'This contact is unavailable as a confirmed reading in this chart.'; }
    members = eligible ? [a, b] : [a, b].filter(id => !['moon', 'ascendant', 'midheaven'].includes(id));
  }
  return <section className="workspace-panel space-y-4" aria-labelledby={headingId} data-testid="chart-element-explanation"><div className="section-heading"><div><p className="workspace-eyebrow">Understand your selection</p><h3 id={headingId} ref={headingRef} tabIndex={-1}>{title}</h3></div><button type="button" className="workspace-secondary" aria-label="Close explanation and return to the planet" onClick={onClose}><X size={15} aria-hidden="true" /></button></div><p className="workspace-muted text-sm leading-relaxed">{explanation}</p><p className="workspace-note text-sm">{geometry}</p>{pairContext && <div className="space-y-3" data-testid="aspect-pair-context"><h4 className="text-sm font-semibold">What this pair brings into dialogue</h4><p className="workspace-muted text-sm leading-relaxed">{pairContext}</p><h4 className="text-sm font-semibold">A question to put into practice</h4><p className="workspace-muted text-sm leading-relaxed">{reflection}</p></div>}{selection.kind === 'house' && chart.metadata?.timeKnown && members.length === 0 && <p className="workspace-muted text-sm">None of the ten calculated bodies occupies this house. An empty house remains part of the chart and does not mean that area of experience is absent from your life.</p>}{members.length > 0 && <div><p className="workspace-muted text-xs mb-2">Open the reading for a point in this chart:</p><div className="flex flex-wrap gap-2">{members.map(id => <button type="button" className="workspace-secondary" key={id} onClick={() => onSelectPlanet(id)}>{name(id)}</button>)}</div></div>}<p className="workspace-muted text-xs">Symbolic meanings from astrological traditions. Geometry is calculated; interpretation does not determine personality or events.</p></section>;
}

