import { useId, useState } from 'react';
import type { BirthDetails } from '../types';
import { LocationInput } from './LocationInput';

export function BirthProfileForm({ initial, onSubmit, busy, onCancel, title }: { initial: BirthDetails; onSubmit: (details: BirthDetails) => void; busy: boolean; onCancel?: () => void; title: string }) {
  const [draft, setDraft] = useState(initial);
  const [unknown, setUnknown] = useState(!initial.time || initial.time === 'SUNRISE');
  const [error, setError] = useState('');
  const id = useId();
  const inputClass = 'workspace-input';
  return <form className="workspace-panel birth-form" onSubmit={e => {
    e.preventDefault(); setError('');
    if (!unknown && (!draft.time || !draft.timezone || !Number.isFinite(draft.lat) || !Number.isFinite(draft.lon))) { setError("Confirm birth time, city and timezone to calculate a chart with houses."); return; }
    onSubmit({ ...draft, name: draft.name.trim() || "My profile", time: unknown ? '' : draft.time, timezone: draft.timezone?.trim() });
  }}><fieldset disabled={busy} className="space-y-5"><div className="section-heading"><h3>{title}</h3><span>Birth details</span></div>
    <div className="grid gap-4 sm:grid-cols-2"><label htmlFor={`${id}-name`}>Name<input id={`${id}-name`} className={inputClass} value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })} placeholder={"What would you like to call this profile?"} maxLength={100} /></label><label htmlFor={`${id}-date`}>Birth date<input id={`${id}-date`} className={inputClass} type="date" min="1200-01-01" max={new Date().toISOString().slice(0, 10)} required value={draft.date} onChange={e => setDraft({ ...draft, date: e.target.value })} /></label></div>
    <label className="unknown-toggle"><input type="checkbox" checked={unknown} onChange={e => setUnknown(e.target.checked)} />  I do not know the birth time</label>
    <div className="grid gap-4 sm:grid-cols-2">{!unknown && <label htmlFor={`${id}-time`}>Local time<input id={`${id}-time`} type="time" step="1" className={inputClass} required value={draft.time === 'SUNRISE' ? '' : draft.time} onChange={e => setDraft({ ...draft, time: e.target.value })} /></label>}<div><span className="block mb-2 text-sm">Birth city</span><LocationInput value={draft.location} onChange={v => setDraft({ ...draft, ...v })} /></div></div>{<details className="workspace-muted text-sm"><summary>Confirm coordinates and timezone manually</summary><div className="grid gap-3 mt-3 sm:grid-cols-3"><label>Latitude<input type="number" step="any" min="-90" max="90" className={inputClass} value={draft.lat ?? ''} onChange={e => setDraft({ ...draft, lat: e.target.value === '' ? undefined : Number(e.target.value), coordinateSource: undefined, locationPrecision: 'manual' })} /></label><label>Longitude<input type="number" step="any" min="-180" max="180" className={inputClass} value={draft.lon ?? ''} onChange={e => setDraft({ ...draft, lon: e.target.value === '' ? undefined : Number(e.target.value), coordinateSource: undefined, locationPrecision: 'manual' })} /></label><label>Confirmed timezone<input className={inputClass} value={draft.timezone ?? ''} placeholder={"America/Sao_Paulo or UTC-03:00"} onChange={e => setDraft({ ...draft, timezone: e.target.value })} /></label></div></details>}
    {!unknown && draft.date && draft.date < '1970-01-01' && draft.timezone && !draft.timezone.startsWith('UTC') && <p className="workspace-note">For dates before 1970, confirm the time standard in the birth record. A city's current timezone may not represent historical local practice; you can enter a documented UTC offset in the manual confirmation.</p>}
    {unknown && <p className="workspace-note">You can still compare planetary positions. Houses, Ascendant and Moon contacts are unavailable without a confirmed birth time.</p>}
    {error && <p role="alert" className="text-red-300 text-sm">{error}</p>}<div className="flex gap-3"><button className="workspace-primary" disabled={busy}>{busy ? "Calculating with Swiss Ephemeris…" : "Calculate chart"}</button>{onCancel && <button type="button" className="workspace-secondary" disabled={busy} onClick={onCancel}>Cancel</button>}</div>
  </fieldset></form>;
}

