import { useId, useState } from 'react';
import type { ComputedChart } from '../lib/astro';
import { computeChartMakeup, ELEMENT_GUIDES, MODALITY_GUIDES, type ChartElement } from '../lib/chart-makeup';
import { interpretationFor } from '../lib/interpretation-content';

export function ChartMakeup({ chart, name, onSelectPlanet }: { chart: ComputedChart; name: string; onSelectPlanet?: (id: string) => void }) {
  const heading = useId();
  const detailId = useId();
  const [selected, setSelected] = useState<ChartElement>('fire');
  const makeup = computeChartMakeup(chart);
  if (makeup.status !== 'ready') return <section className="workspace-panel space-y-3" aria-labelledby={heading} data-testid="chart-makeup-unavailable">
    <p className="workspace-eyebrow">The elements in your chart</p>
    <h3 id={heading}>{name ? `Chart composition for ${name}` : 'Your chart composition'}</h3>
    <p className="workspace-muted text-sm">{makeup.message}</p>
  </section>;
  const current = makeup.groups.find(group => group.element === selected)!;
  const guide = ELEMENT_GUIDES[selected];
  return <section className="workspace-panel space-y-4" aria-labelledby={heading} data-testid="chart-makeup">
    <div><p className="workspace-eyebrow">Another way to explore your chart</p><h3 id={heading}>{name ? `Chart composition for ${name}` : 'Your chart composition'}</h3></div>
    <p className="workspace-muted text-sm"><strong>Calculated</strong> · Ten positions, four elements, three modalities. Tap an element to see its planets.</p>
    {makeup.provisional && <p className="workspace-note" data-testid="makeup-reference">{makeup.referenceNote}</p>}
    <p className="workspace-muted text-xs">Dominant: {makeup.dominantElements.map(id => ELEMENT_GUIDES[id].label).join(', ')}. Zero count: {makeup.lackingElements.map(id => ELEMENT_GUIDES[id].label).join(', ') || 'no elements'}.</p>
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(125px, 1fr))', gap: 10 }} role="group" aria-label="Explore chart elements">
      {makeup.groups.map(group => <button key={group.element} type="button" className="workspace-secondary" aria-pressed={selected === group.element} aria-controls={detailId} onClick={() => setSelected(group.element)} style={{ display: 'grid', gap: 8, textAlign: 'left', padding: 14, outline: selected === group.element ? `2px solid ${ELEMENT_GUIDES[group.element].color}` : undefined, outlineOffset: 2 }}>
        <span>{ELEMENT_GUIDES[group.element].label}</span>
        <strong style={{ fontSize: 24 }}>{group.percentage}%</strong>
        <span className="workspace-muted text-xs">{group.count} of {makeup.total} positions</span>
        <span aria-hidden="true" style={{ display: 'block', width: '100%', height: 5, borderRadius: 5, background: 'rgba(128,128,128,.18)' }}><span style={{ display: 'block', width: `${group.percentage}%`, height: '100%', borderRadius: 5, background: ELEMENT_GUIDES[group.element].color }} /></span>
      </button>)}
    </div>
    <div id={detailId} className="space-y-3" aria-live="polite" aria-atomic="true">
      <h4>{guide.label} in this chart</h4>
      <p className="workspace-muted text-sm"><strong>Astrological meaning</strong> · {guide.meaning}</p>
      <p className="workspace-muted text-xs">Source: {interpretationFor(`element:${selected}`)?.source}</p>
      {current.members.length ? <ul style={{ display: 'flex', gap: 8, flexWrap: 'wrap', listStyle: 'none', padding: 0 }}>{current.members.map(member => <li key={member.id}>{onSelectPlanet ? <button type="button" className="workspace-secondary" onClick={() => onSelectPlanet(member.id)} aria-label={`Explore ${member.name} in ${member.sign}`}>{member.name} in {member.sign} <span aria-hidden="true">↗</span></button> : <span className="workspace-muted text-sm">{member.name} in {member.sign}</span>}</li>)}</ul> : <p className="workspace-muted text-sm">None of these ten positions occupies a sign of {guide.label.toLowerCase()}. This does not mean you lack these qualities.</p>}
      <p className="text-sm">{guide.prompt}</p>
    </div>
    <div className="space-y-3"><h4>Modality</h4><p className="workspace-muted text-xs">Dominant: {makeup.dominantModalities.map(id => MODALITY_GUIDES[id].label).join(', ')}. Zero count: {makeup.lackingModalities.map(id => MODALITY_GUIDES[id].label).join(', ') || 'no modalities'}.</p>{makeup.modalities.map(group => <details key={group.modality} className="workspace-panel" style={{ padding: 14 }}><summary>{MODALITY_GUIDES[group.modality].label} · {group.count} of 10 positions</summary><p className="workspace-muted text-sm mt-3">Astrological meaning · {MODALITY_GUIDES[group.modality].meaning}</p><p className="workspace-muted text-xs">Source: {interpretationFor(`modality:${group.modality}`)?.source}</p><div className="flex gap-2 flex-wrap mt-3">{group.members.map(member => onSelectPlanet ? <button key={member.id} type="button" className="workspace-secondary" onClick={() => onSelectPlanet(member.id)}>{member.name} in {member.sign}</button> : <span key={member.id}>{member.name} in {member.sign}</span>)}{!group.members.length && <p className="workspace-muted text-xs">Zero positions in this modality; this does not measure personal qualities.</p>}</div></details>)}</div>
    {makeup.ascendantExtra && <p className="workspace-muted text-xs">Ascendant (extra, outside the count): {makeup.ascendantExtra.sign}.</p>}
    <p className="workspace-muted text-xs"><strong>Your log</strong> · These counts do not use your journal (n = 0 entries used).</p>
    <details className="workspace-muted text-xs"><summary>What these percentages mean</summary><p className="mt-3">Each of the ten bodies, from the Sun to Pluto, has equal weight and is counted once. Calculated zodiac longitude determines its sign and element. The Sun and Moon are included under this astrological convention. Ascendant, houses, aspects and additional points are excluded. This counts placements by sign rather than measuring personality, health, energy or how a day will unfold.</p></details>
  </section>;
}

src/components/FamousMatches.tsx:
import { useEffect, useMemo, useRef, useState } from 'react';
import type { BirthDetails } from '../types';
import type { ComputedChart, ComputedSynastry } from '../lib/astro';
import { ChartDetails, AspectsList } from './ChartDetails';
import type { comparePositions } from '../lib/similarity';
import type { PublicPerson, PlacementFilter } from '../lib/catalog';
import type { ChartSettings } from '../lib/chart-settings';

type Match = { person: PublicPerson; similarity: ReturnType<typeof comparePositions> };
type Detail = Match & { user: ComputedChart; partner: ComputedChart; crossAspects: ComputedSynastry['crossAspects'] };
const names: Record<string, string> = { sun: "Sun", moon: "Moon", mercury: "Mercury", venus: "Venus", mars: "Mars", jupiter: "Jupiter", saturn: "Saturn", uranus: "Uranus", neptune: "Neptune", pluto: "Pluto" };

export function FamousMatches({ userDetails, autoStart = false, settings, initialPersonId, onExplorePlacement }: { userDetails: BirthDetails; autoStart?: boolean; settings?: ChartSettings; initialPersonId?: string; onExplorePlacement?: (placement: PlacementFilter) => void }) {
  const [matches, setMatches] = useState<Match[]>([]);
  const [detail, setDetail] = useState<Detail | null>(null);
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [engine, setEngine] = useState('');
  const [requestVersion, setRequestVersion] = useState(0);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const detailRef = useRef<HTMLDivElement>(null);
  useEffect(() => { if (detail) detailRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, [detail]);
  const userKey = JSON.stringify(userDetails);
  const settingsKey = JSON.stringify(settings || {});
  useEffect(() => {
    setMatches([]); setDetail(null); setError(''); setSelectedId(initialPersonId || (autoStart ? 'list' : null)); setLoading(false);
  }, [userKey, autoStart, settingsKey, initialPersonId]);
  // Cancel and ignore both list and detail responses after inputs change or unmount.
  useEffect(() => {
    if (!selectedId) return;
    const controller = new AbortController();
    let current = true;
    setLoading(true); setError(''); setDetail(null);
    fetch('/api/famous-matches', { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ user: JSON.parse(userKey), settings: JSON.parse(settingsKey), ...(selectedId !== 'list' ? { personId: selectedId } : {}) }), signal: controller.signal })
      .then(async res => {
        const data = await res.json();
        if (!res.ok) throw new Error(data.message || "Calculation failed.");
        if (!current) return;
        if (selectedId === 'list') { setMatches(data.matches); setEngine(data.engine); setTotal(data.total); }
        else setDetail(data);
      }).catch(err => { if (current && err.name !== 'AbortError') setError(err.message); })
      .finally(() => { if (current) setLoading(false); });
    return () => { current = false; controller.abort(); };
  }, [selectedId, userKey, requestVersion, settingsKey]);
  const visible = useMemo(() => matches.filter(m => (!category || m.person.category === category) &&
    `${m.person.name} ${m.person.country}`.toLocaleLowerCase('en-US').includes(query.toLocaleLowerCase('en-US'))), [matches, query, category]);
  useEffect(() => { setPage(1); }, [query, category]);
  return <section className="glass-card p-7 md:p-10 space-y-5 border-gold/20">
    <h2 className="text-gold font-display text-xl font-bold">Whose chart resembles yours?</h2>
    <p className="text-zinc-400 text-sm">Compare planetary positions with public figures. Similarity and synastry are different comparisons; the percentage is a geometric index, without scientific validation for personality or relationships.</p>
    <p className="text-zinc-400 text-xs">{total !== null ? `Published catalog: ${total} people with a sourced birth date.` : "You can also explore individual placements in the chart database."}  Without a confirmed time, Moon, Ascendant and houses are excluded from similarity. Other positions use the approximate noon reference in the birth timezone.</p>
    <button disabled={loading} className="celestial-btn rounded-xl px-5 py-3 text-black font-bold disabled:opacity-50" onClick={() => { setSelectedId('list'); setRequestVersion(v => v + 1); }}> {loading ? "Calculating…" : "Find similar charts"}</button>
    {error && <p role="alert" className="text-red-300">{error}</p>}
    {!!matches.length && <>
      <div className="flex gap-3 flex-wrap">
        <input aria-label={"Search people or countries"} placeholder={"Name or country"} className="bg-zinc-900 rounded-xl p-3 text-white" value={query} onChange={e => setQuery(e.target.value)} />
        <select aria-label={"Category"} className="bg-zinc-900 rounded-xl p-3 text-white" value={category} onChange={e => setCategory(e.target.value)}><option value="">All categories</option>{[...new Set(matches.map(m => m.person.category))].map(c => <option key={c}>{c}</option>)}</select>
      </div>
      <p className="text-zinc-500 text-xs">Engine: {engine}  · Method: personal-weighted-gaussian-30deg-v1 · {visible.length}  results</p>
      <div className="grid gap-3 sm:grid-cols-2">{visible.slice((page - 1) * 24, page * 24).map(m => <article key={m.person.id} className="rounded-xl border border-white/10 p-4 space-y-2">
        <span className="text-zinc-500 text-xs">#{matches.indexOf(m) + 1}  in the catalog</span>
        <h3 className="text-white font-bold">{m.person.name} <span className="text-gold">{m.similarity.score}%</span></h3>
        <p className="text-zinc-400 text-xs">{m.person.category} · {m.person.country} · {m.person.date} · {m.similarity.partial ? "Partial similarity" : "Planetary index"}</p>
        <a href={m.person.source} target="_blank" rel="noreferrer" className="text-gold underline text-xs">Date source · {m.person.confidence === 'sourced-time' ? "documented birth time" : 'hora desconhecida'}</a>
        {m.person.attribution && <p className="text-zinc-500 text-xs">{m.person.attribution} · <a href={m.person.licenseUrl} target="_blank" rel="noreferrer" className="underline">{m.person.license}</a></p>}
        <button className="block text-white underline text-sm" disabled={loading} onClick={() => { setSelectedId(m.person.id); setRequestVersion(v => v + 1); }}>View placements and synastry aspects</button>
      </article>)}</div>
      <nav aria-label={"Similarity pages"} className="catalog-pagination"><button className="workspace-secondary" disabled={page <= 1} onClick={() => setPage(p => p - 1)}>Previous</button><span className="workspace-muted text-xs">Page {page}  of {Math.max(1, Math.ceil(visible.length / 24))}</span><button className="workspace-secondary" disabled={page * 24 >= visible.length} onClick={() => setPage(p => p + 1)}>Next</button></nav>
      {!visible.length && <p className="text-zinc-400">No people found in this catalog.</p>}
    </>}
    {detail && <div ref={detailRef} className="space-y-3 border-t border-white/10 pt-4 scroll-mt-28">
      <h3 className="text-gold font-bold">You and {detail.person.name} · {detail.similarity.score}% similarity{detail.similarity.partial ? ' parcial' : " planetary"}</h3>
      <p className="text-zinc-400 text-xs">Each planet is compared with the same planet. The index gives more weight to personal planets; a distance of 30° corresponds to 60.7% for that planet. Houses and Ascendant are excluded from this method.</p>
      <p className="text-zinc-500 text-xs"><a href={detail.person.source} target="_blank" rel="noreferrer" className="underline">Birth source</a>{detail.person.attribution && <> · {detail.person.attribution} · <a href={detail.person.licenseUrl} target="_blank" rel="noreferrer" className="underline">{detail.person.license}</a></>}{detail.person.sourceNotes && <> · {detail.person.sourceNotes}</>}</p>
      <ul className="grid sm:grid-cols-2 gap-2 text-zinc-300 text-sm">{detail.similarity.positions.map(p => <li key={p.planet}>{names[p.planet]}: difference of {p.difference.toFixed(2)}° · {p.similarity.toFixed(1)}%</li>)}</ul>
      <details className="workspace-panel"><summary>View the calculated natal chart for {detail.person.name}</summary><div className="mt-4"><ChartDetails key={detail.person.id} chart={detail.partner} name={detail.person.name} onExplorePlacement={onExplorePlacement} /></div></details>
      <h4 className="text-white font-bold">Synastry aspects</h4>
      <p className="text-zinc-400 text-xs">Contacts between points in the two charts, with calculated orbs. {(!detail.user.metadata?.timeKnown || !detail.partner.metadata?.timeKnown) ? "Moon contacts were excluded because a birth time is unconfirmed." : "Moon and angles are included when calculable."}</p>
      <AspectsList aspects={detail.crossAspects} firstName={userDetails.name || "You"} secondName={detail.person.name} uncertain={!detail.user.metadata?.timeKnown || !detail.partner.metadata?.timeKnown} />
      {!detail.crossAspects.length && <p className="text-zinc-400">No aspects within the selected orbs.</p>}
    </div>}
  </section>;
}

