import { useEffect, useId, useRef, useState } from 'react';
import { MapPin, Loader2, Check } from 'lucide-react';
import { searchCities, type GeoResult } from '../lib/location';

interface Props {
  value: string;
  onChange: (v: { location: string; lat?: number; lon?: number; timezone?: string; coordinateSource?: string; locationPrecision?: 'city' | 'manual' }) => void;
  placeholder?: string;
  accent?: 'gold' | 'pink';
}

export function LocationInput({ value, onChange, placeholder = 'CITY, STATE', accent = 'gold' }: Props) {
  const [q, setQ] = useState(value), [results, setResults] = useState<GeoResult[]>([]);
  const [open, setOpen] = useState(false), [loading, setLoading] = useState(false);
  const [active, setActive] = useState(-1);
  const [tz, setTz] = useState<string | null>(null), [error, setError] = useState('');
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const controller = useRef<AbortController | null>(null), version = useRef(0), currentValue = useRef(value);
  const rootRef = useRef<HTMLDivElement>(null), inputRef = useRef<HTMLInputElement>(null);
  const listId = useId();
  function invalidate() { version.current += 1; controller.current?.abort(); if (debounceRef.current) clearTimeout(debounceRef.current); }
  useEffect(() => {
    if (value !== currentValue.current) { invalidate(); currentValue.current = value; setQ(value); setResults([]); setOpen(false); setActive(-1); setLoading(false); setTz(null); setError(''); }
  }, [value]);
  useEffect(() => {
    const outside = (event: MouseEvent) => { if (rootRef.current && !rootRef.current.contains(event.target as Node)) setOpen(false); };
    document.addEventListener('mousedown', outside);
    return () => { document.removeEventListener('mousedown', outside); invalidate(); };
  }, []);
  useEffect(() => {
    if (open && active >= 0) document.getElementById(`${listId}-${active}`)?.scrollIntoView({ block: 'nearest' });
  }, [open, active, listId]);

  function handleInput(text: string) {
    invalidate(); const request = version.current;
    currentValue.current = text; setQ(text); setResults([]); setOpen(false); setActive(-1); setLoading(false); setError(''); setTz(null);
    onChange({ location: text, lat: undefined, lon: undefined, timezone: undefined, coordinateSource: undefined, locationPrecision: undefined });
    if (text.trim().length < 2) return;
    debounceRef.current = setTimeout(async () => {
      const abort = new AbortController(); controller.current = abort; setLoading(true);
      try {
        const cities = await searchCities(text, abort.signal);
        if (request !== version.current || abort.signal.aborted) return;
        setResults(cities); setActive(-1); setOpen(cities.length > 0 && document.activeElement === inputRef.current);
        if (!cities.length) setError("City not found. Try adding the state or country, or enter coordinates and timezone manually.");
      } catch (e) {
        if (request === version.current && !abort.signal.aborted) setError(e instanceof Error ? e.message : "The city search could not be completed.");
      } finally { if (request === version.current) setLoading(false); }
    }, 300);
  }
  function pick(city: GeoResult) {
    invalidate(); currentValue.current = city.display;
    setQ(city.display); setResults([]); setOpen(false); setActive(-1); setLoading(false); setTz(city.timezone || null);
    setError(city.timezone ? '' : "This city's timezone is unconfirmed. Enter it manually before calculating houses.");
    onChange({ location: city.display, lat: city.lat, lon: city.lon, timezone: city.timezone, coordinateSource: city.source, locationPrecision: 'city' });
  }
  function handleKey(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape' && open) { event.preventDefault(); setOpen(false); setActive(-1); return; }
    if (!results.length) return;
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault(); setOpen(true);
      setActive(index => event.key === 'ArrowDown' ? (index + 1) % results.length : (index <= 0 ? results.length - 1 : index - 1));
    } else if (event.key === 'Enter' && open) {
      event.preventDefault(); pick(results[active >= 0 ? active : 0]);
    }
  }
  return <div ref={rootRef} className="relative space-y-2"><div className="relative"><input ref={inputRef} value={q} onChange={e => handleInput(e.target.value)} onKeyDown={handleKey} onBlur={e => { if (!rootRef.current?.contains(e.relatedTarget)) { setOpen(false); setActive(-1); } }} onFocus={() => results.length > 0 && setOpen(true)} placeholder={placeholder} aria-label={"Birth city"} role="combobox" aria-autocomplete="list" aria-expanded={open} aria-controls={open ? listId : undefined} aria-activedescendant={open && active >= 0 ? `${listId}-${active}` : undefined} autoComplete="off" className={`workspace-location-input w-full bg-white/[0.03] border border-white/10 rounded-2xl px-5 py-4 pr-12 text-white focus:outline-none focus:ring-2 ${accent === 'pink' ? 'focus:ring-astro-pink/20' : 'focus:ring-gold/20'}`} /><div className={`absolute right-4 top-1/2 -translate-y-1/2 ${accent === 'pink' ? 'text-astro-pink/50' : 'text-gold/50'}`}>{loading ? <Loader2 className="w-4 h-4 animate-spin" aria-label={"Searching cities"} /> : <MapPin className="w-4 h-4" aria-hidden="true" />}</div></div>{tz && <p className="text-xs text-zinc-400"><Check size={13} aria-hidden="true" className="inline-block text-gold mr-1" />Timezone: {tz}  · city reference coordinates</p>}{error && <p role="status" className="text-xs text-amber-200">{error}</p>}<p className="text-[10px] text-zinc-500">Local catalog search · <a href="https://www.geonames.org/" target="_blank" rel="noreferrer" className="underline">GeoNames</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer" className="underline">CC BY 4.0</a></p>{open && results.length > 0 && <div id={listId} role="listbox" aria-label={"Matching cities"} className="workspace-location-results absolute z-50 top-full left-0 right-0 mt-2 bg-[#0a0614] border border-white/10 rounded-2xl shadow-xl max-h-72 overflow-y-auto">{results.map((city, index) => <button type="button" tabIndex={-1} id={`${listId}-${index}`} role="option" aria-selected={active === index} onMouseDown={e => e.preventDefault()} key={city.id || city.display} onClick={() => pick(city)} className={`w-full text-left px-5 py-3 hover:bg-white/5 border-b border-white/5 ${active === index ? 'bg-white/10' : ''}`}><span className="block text-white text-sm">{city.display}</span><span className="block text-zinc-400 text-xs">{city.timezone || "Timezone requires manual confirmation"}</span></button>)}</div>}</div>;
}

