import { useEffect, useMemo, useState } from 'react';
import type { SkyObject } from '../lib/fomalhaut/explorer';

type Props = { instant?: string; latitude?: number; longitude?: number; body: string; onBody: (id: string) => void };
function point(object: SkyObject) {
  const r = 95 * (90 - object.altitude) / 90;
  const angle = object.azimuth * Math.PI / 180;
  return { cx: 100 + r * Math.sin(angle), cy: 100 - r * Math.cos(angle) };
}
export function FomalhautPanel({instant, latitude, longitude, body, onBody}: Props) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [star, setStar] = useState('');
  const [attempt, setAttempt] = useState(0);
  const [result, setResult] = useState<{key: string; objects: SkyObject[]; search: typeof import('../lib/fomalhaut/explorer').searchSky} | null>(null);
  const [failed, setFailed] = useState('');
  const hasCoordinates = Number.isFinite(latitude) && Number.isFinite(longitude);
  const lat = hasCoordinates ? latitude! : 0, lon = hasCoordinates ? longitude! : 0;
  const key = JSON.stringify([instant, lat, lon, attempt]);
  useEffect(() => {
    if (!open || !instant) return;
    let active = true;
    import('../lib/fomalhaut/explorer').then(async ({observerSky, searchSky}) => {
      const objects = await observerSky(instant, lat, lon);
      if (active) setResult({key, objects, search: searchSky});
    }).catch(() => { if (active) setFailed(key); });
    return () => { active = false; };
  }, [open, instant, key, lat, lon]);
  const current = result?.key === key ? result : null;
  const selected = current?.objects.find(o => o.id === (star || body));
  const matches = useMemo(() => current?.search(current.objects, query) ?? [], [current, query]);
  const visible = useMemo(() => current?.objects.filter(o => o.altitude >= 0 && (o.magnitude < 3.5 || o.kind !== 'Star')) ?? [], [current]);
  return <section className="workspace-panel" aria-label="Fomalhaut">
    <button className="workspace-secondary" aria-expanded={open} onClick={() => setOpen(!open)}>Fomalhaut sky explorer</button>
    {open && <>{!instant ? <p>Choose a day with a calculated sky to open the horizon map.</p> :
      failed === key ? <p role="alert">Could not load the local sky pack. <button onClick={()=>setAttempt(n => n+1)}>Retry sky pack</button></p> :
      !current ? <p role="status">Preparing local star map…</p> : <>
        <p>{instant} · {hasCoordinates ? 'Profile coordinates' : 'Reference observer'} ({lat}°, {lon}°)</p>
        <svg role="img" aria-label="Horizon map, north up and east right" viewBox="0 0 200 200" style={{width:'min(100%, 24rem)'}}>
          <circle cx="100" cy="100" r="95" fill="#10162a" stroke="#798296" />
          {visible.map(o=><circle key={o.id} {...point(o)} r={o.kind === 'Star' ? 0.8 : 1.8} fill={o.kind === 'Star' ? '#f5f1dc' : '#ffd078'}/>)}
          {selected && selected.altitude >= 0 && <circle {...point(selected)} r="4" fill="none" stroke="#81efff"/>}
        </svg>
        <label>Find a star or planet <input type="search" maxLength={80} value={query} onChange={e=>setQuery(e.target.value)} /></label>
        {query.trim() && (matches.length ? <div className="legacy-tools">{matches.map(o=><button className="workspace-secondary" key={o.id} onClick={()=>{
          if (o.kind === 'Star') setStar(o.id); else { setStar(''); onBody(o.id); }
          setQuery('');
        }}>{o.name}</button>)}</div> : <p>No objects match this search.</p>)}
        {star && <button className="workspace-secondary" onClick={()=>setStar('')}>Return to selected planet</button>}
        {selected && <p aria-live="polite">{selected.name} · {selected.altitude < 0 ? 'Below horizon' : 'Above horizon'} · altitude {selected.altitude.toFixed(1)}° · azimuth {selected.azimuth.toFixed(1)}°</p>}
        <small>Bright objects shown. Search all 8,920 stars. <a href="/fomalhaut/data/LICENSE-stars.txt">HYG 4.1 credits and licence</a></small>
      </>}</>}
  </section>;
}

