import { useState } from 'react';
import type { DailySkyResponse } from '../lib/daily-sky';

const paths = [
  { theme: 'Communication', body: 'mercury', question: 'Think of a recent conversation. What did you mean to say, and what might the other person have heard?' },
  { theme: 'Creativity', body: 'venus', question: 'Which small detail caught your attention today? What could you make from it?' },
  { theme: 'Commitment', body: 'saturn', question: 'Which promise feels worth keeping this week? What is one manageable step toward it?' },
] as const;

export function HermitGuide({ sky, onExplain, onReflect }: { sky: DailySkyResponse; onExplain: (id: string) => void; onReflect: () => void }) {
  const [theme, setTheme] = useState(0);
  const path = paths[theme];
  const planet = sky.planets.find(p => p.id === path.body);
  if (!planet) return null;
  return <section className="workspace-panel" aria-label="Hermit guide">
    <h2>What would you like to explore?</h2>
    <div className="legacy-tools">{paths.map((item, i) => <button className="workspace-secondary" key={item.theme}
      aria-pressed={theme === i} onClick={() => setTheme(i)}>{item.theme}</button>)}</div>
    <p>For {path.theme.toLowerCase()}, explore the symbolism of {planet.name}. On {sky.date} it is in {planet.sign}.</p>
    <p>{path.question}</p>
    <button className="workspace-secondary" onClick={() => onExplain(path.body)}>Explore {planet.name}</button>
    <button className="workspace-primary" onClick={onReflect}>Write a reflection</button>
  </section>;
}

