import { useEffect, useState } from 'react';
import { motion } from 'motion/react';
import type { ComputedSynastry, TransitsToday } from '../lib/astro';
import { loadTransits, natalTransitPoints } from '../lib/astro';
import { AstroGlyph } from './AstroGlyph';
import { ChartJournal } from './ChartJournal';
import { journalProfile } from '../lib/journal';
import { planetNames } from './ChartDetails';
import { aspectLearning } from '../lib/chart-learning';

// ───────────────────────── Bi-Wheel ─────────────────────────
// Inner ring: user's planets inside user's house structure.
// Outer ring: partner's planets overlaid on the same house structure.

export function BiWheelChart({ synastry }: { synastry: ComputedSynastry }) {
  const size = 620;
  const cx = size / 2;
  const cy = size / 2;
  const rZodiac = 285;
  const rZodiacInner = 250;
  const rHouseOuter = 225;
  const rHouseInner = 95;
  const rUserRing = 155;    // inner ring for user's planets
  const rPartnerRing = 205; // outer ring for partner's planets

  const polar = (r: number, deg: number) => {
    const rad = (180 - (deg - (synastry.user.ascendant ?? 0))) * (Math.PI / 180);
    return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
  };

  const zodiacSegments = Array.from({ length: 12 }).map((_, i) => {
    const s = polar(rZodiac, i * 30);
    const e = polar(rZodiac, (i + 1) * 30);
    const si = polar(rZodiacInner, i * 30);
    const ei = polar(rZodiacInner, (i + 1) * 30);
    return {
      path: `M ${s.x} ${s.y} A ${rZodiac} ${rZodiac} 0 0 0 ${e.x} ${e.y} L ${ei.x} ${ei.y} A ${rZodiacInner} ${rZodiacInner} 0 0 1 ${si.x} ${si.y} Z`,
      glyphPos: polar((rZodiac + rZodiacInner) / 2, i * 30 + 15),
      glyph: ['♈','♉','♊','♋','♌','♍','♎','♏','♐','♑','♒','♓'][i],
    };
  });

  const houseSpokes = (synastry.user.houses || []).map((house, i) => {
    const deg = house.cuspLon;
    const a = polar(rHouseOuter, deg);
    const b = polar(rHouseInner, deg);
    const next = synastry.user.houses![(i + 1) % 12];
    const width = ((next.cuspLon - deg) % 360 + 360) % 360;
    return { a, b, labelPos: polar(rHouseInner + 14, deg + width / 2), num: i + 1 };
  });

  const PLANET_COLOR: Record<string, string> = {
    sun: '#ffd166', moon: '#cbd5ff', mercury: '#b8f2e6', venus: '#ffb6d9', mars: '#ff8b7a',
    jupiter: '#ffe29a', saturn: '#9fb4c7', uranus: '#77e8ff', neptune: '#7a9aff', pluto: '#c084ff',
  };

  return (
    <svg viewBox={`0 0 ${size} ${size}`} className="w-full h-full" style={{ filter: 'drop-shadow(0 0 40px rgba(192,132,252,0.25))' }}>
      <defs>
        <radialGradient id="biwheelBg" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#2a0f4a" stopOpacity="0.85" />
          <stop offset="100%" stopColor="#050508" stopOpacity="1" />
        </radialGradient>
      </defs>

      <circle cx={cx} cy={cy} r={rZodiac} fill="url(#biwheelBg)" />

      {zodiacSegments.map((s, i) => (
        <g key={i}>
          <path d={s.path} fill="rgba(255,210,140,0.05)" stroke="rgba(255,210,140,0.25)" strokeWidth={0.5} />
          <AstroGlyph symbol={s.glyph} color="#ffd98a" size={23} x={s.glyphPos.x - 11.5} y={s.glyphPos.y - 11.5} />
        </g>
      ))}

      <circle cx={cx} cy={cy} r={rHouseOuter} fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth={1} />
      <circle cx={cx} cy={cy} r={rHouseInner} fill="none" stroke="rgba(255,210,140,0.3)" strokeWidth={1} />
      <circle cx={cx} cy={cy} r={rUserRing} fill="none" stroke="rgba(255,119,255,0.2)" strokeDasharray="2 4" />
      <circle cx={cx} cy={cy} r={rPartnerRing} fill="none" stroke="rgba(192,132,252,0.2)" strokeDasharray="2 4" />

      {houseSpokes.map((h, i) => (
        <g key={i}>
          <line x1={h.a.x} y1={h.a.y} x2={h.b.x} y2={h.b.y} stroke="rgba(255,255,255,0.1)" strokeWidth={0.5} />
          <text x={h.labelPos.x} y={h.labelPos.y} textAnchor="middle" dominantBaseline="central" fill="rgba(255,255,255,0.35)" fontSize="10" fontWeight="700">{h.num}</text>
        </g>
      ))}

      {/* User planets · inner ring */}
      {synastry.user.planets.map((p, i) => {
        const pos = polar(rUserRing, p.lon);
        const c = PLANET_COLOR[p.id] || '#ffffff';
        return (
          <g key={`u-${i}`}>
            <circle cx={pos.x} cy={pos.y} r={13} fill="rgba(10,6,20,0.9)" stroke={c} strokeWidth={1.3} />
            <AstroGlyph symbol={p.symbol} color={c} size={19} x={pos.x - 9.5} y={pos.y - 9.5} />
          </g>
        );
      })}

      {/* Partner planets · outer ring */}
      {synastry.partner.planets.map((p, i) => {
        const pos = polar(rPartnerRing, p.lon);
        const c = PLANET_COLOR[p.id] || '#ffffff';
        return (
          <g key={`p-${i}`}>
            <circle cx={pos.x} cy={pos.y} r={13} fill="rgba(40,10,60,0.95)" stroke={c} strokeWidth={1.5} strokeDasharray="2 1" />
            <AstroGlyph symbol={p.symbol} color={c} size={19} x={pos.x - 9.5} y={pos.y - 9.5} />
          </g>
        );
      })}

      {/* Center hub */}
      <circle cx={cx} cy={cy} r={70} fill="#050508" stroke="rgba(255,204,0,0.2)" strokeWidth={1} />
      <text x={cx} y={cy - 6} textAnchor="middle" fill="rgba(255,255,255,0.5)" fontSize="9" fontWeight="700" letterSpacing="1.5">TOGETHER</text>
      <text x={cx} y={cy + 10} textAnchor="middle" fill="#ffd98a" fontSize="12" fontWeight="900" letterSpacing="0.5" style={{ fontFamily: 'Cinzel, serif' }}>BI-WHEEL</text>
    </svg>
  );
}

// ───────────────────────── Composite ─────────────────────────

export function CompositeCard({ synastry }: { synastry: ComputedSynastry }) {
  const c = synastry.composite;
  const big = c.planets.filter((p) => ['sun','moon','venus','mars'].includes(p.id));
  return (
    <div className="glass-card p-8 md:p-10 bg-gradient-to-br from-astro-pink/10 via-transparent to-gold/5 border-astro-pink/20 space-y-5">
      <div className="flex items-center justify-between">
        <span className="text-astro-pink font-display text-xs font-black tracking-[0.3em] uppercase">Composite chart</span>
        <span className="text-[9px] md:text-[10px] text-zinc-400 font-bold uppercase tracking-widest">The relationship as a whole</span>
      </div>
      <p className="text-zinc-300 text-sm md:text-base leading-relaxed">
        A composite chart uses midpoints between the two natal charts. In astrology it symbolizes the relationship you create together.
      </p>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {big.map((p) => (
          <div key={p.id} className="text-center p-3 rounded-2xl bg-white/[0.04] border border-white/10">
            <div className="mb-1"><AstroGlyph symbol={p.symbol} color="#ffd98a" size={24} /></div>
            <div className="text-white font-display font-bold text-sm">{p.sign}</div>
            <div className="text-zinc-500 text-[10px] uppercase tracking-widest font-bold">{p.name}</div>
            <div className="text-zinc-400 text-[10px] font-mono mt-0.5">{p.degree.toFixed(1)}°</div>
          </div>
        ))}
      </div>
      {c.ascendant !== null && (
        <div className="text-center py-3 rounded-2xl bg-astro-pink/5 border border-astro-pink/20">
          <div className="text-[9px] uppercase tracking-widest text-astro-pink/70 font-black mb-1">Composite Ascendant</div>
          <div className="text-white font-display text-lg font-bold">
            {(() => {
              const idx = Math.floor((c.ascendant % 360) / 30);
              return ['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'][idx];
            })()}{' '}
            · {(c.ascendant % 30).toFixed(1)}°
          </div>
        </div>
      )}
    </div>
  );
}

