// ───────────────────────── Transits Today ─────────────────────────

export function TransitsTodayCard({ synastry, userName = 'You', partnerName = 'Partner', initialUtc }: { synastry: ComputedSynastry; userName?: string; partnerName?: string; initialUtc?: string }) {
  const [data, setData] = useState<TransitsToday | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [at, setAt] = useState(() => (initialUtc || new Date().toISOString()).slice(0, 16));
  const [showAll, setShowAll] = useState(false);
  const [journalTarget, setJournalTarget] = useState<'user' | 'partner'>('user');
  const step = (days: number) => setAt(value => new Date(new Date(`${value}:00Z`).getTime() + days * 86400000).toISOString().slice(0, 16));

  useEffect(() => {
    let cancelled = false;
    setData(null); setErr(null);
    (async () => {
      try {
        const userPlanets = natalTransitPoints(synastry.user);
        const partnerPlanets = natalTransitPoints(synastry.partner);
        const d = await loadTransits(userPlanets, partnerPlanets, `${at}:00Z`);
        if (!cancelled) setData(d);
      } catch (e: any) {
        if (!cancelled) setErr(e?.message || 'erro');
      }
    })();
    return () => { cancelled = true; };
  }, [synastry.user, synastry.partner, at]);

  const moodColor = {
    'harmônico': 'text-gold border-gold/40 bg-gold/10',
    'intenso': 'text-astro-pink border-astro-pink/40 bg-astro-pink/10',
    'misto': 'text-purple-300 border-purple-400/40 bg-purple-400/10',
    'calmo': 'text-zinc-300 border-white/20 bg-white/5',
  } as const;

  return (
    <div className="glass-card p-7 md:p-9 bg-white/[0.02] border-white/10 space-y-4">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <span className="text-gold font-display text-xs font-black tracking-[0.3em] uppercase">Transits over time</span>
        {data && (
          <span className={`px-3 py-1 rounded-full border text-[10px] uppercase tracking-widest font-black ${moodColor[data.mood]}`}>
            Tone {{'harmônico':'Harmonious',intenso:'Intense',misto:'Mixed',calmo:'Calm'}[data.mood]}
          </span>
        )}
      </div>
      <div className="flex gap-2 flex-wrap items-center"><button className="workspace-secondary" onClick={() => step(-1)}>← 1 day</button><label className="text-xs text-zinc-400">UTC instant <input className="workspace-input" type="datetime-local" min="1200-01-01T00:00" max="2399-12-31T23:59" value={at} onChange={e => { if (e.target.value) setAt(e.target.value); }} /></label><button className="workspace-secondary" onClick={() => step(1)}>1 day →</button><button className="workspace-secondary" onClick={() => setAt(new Date().toISOString().slice(0, 16))}>Now</button></div>
      {!data && !err && <div role="status" className="text-zinc-500 text-xs">Calculating the sky for this instant…</div>}
      {err && <div className="text-astro-pink text-xs">{err}</div>}
      {data && (
        <>
          <p className="text-zinc-300 text-xs md:text-sm leading-relaxed">
            Contacts calculated for {data.utc} using {data.engine}. The orb shows proximity to the exact angle at this instant; it does not predict when the aspect becomes exact.
          </p>
          <div className="space-y-2">
            {data.topHits.length === 0 && <div className="text-zinc-500 text-xs">No contacts within the chosen orbs at this instant.</div>}
            {(showAll ? data.hits || data.topHits : data.topHits).map((h, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: i * 0.04 }}
                className="grid grid-cols-[auto_1fr_auto] items-center gap-x-3 py-2 border-b border-white/5 last:border-0"
              >
                <span className="text-xl" style={{ color: '#ffd98a' }}><AstroGlyph symbol={h.transitSymbol} color="#ffd98a" size={22} /></span>
                <div className="min-w-0">
                  <div className="text-white font-display text-sm md:text-base font-bold">
                    {planetNames[h.transitPlanet]} {h.type.toLowerCase()} {planetNames[h.natalPlanet]}
                    <span className="text-zinc-400 font-normal"> · {h.natalTarget === 'user' ? userName : partnerName}</span>
                  </div>
                  <div className="text-zinc-500 text-[10px] md:text-xs">in {h.transitSign} · orb {h.orb.toFixed(1)}°</div>
                  <details className="text-zinc-400 text-xs mt-2"><summary>Understand this contact</summary><p className="mt-2">{aspectLearning[h.type]} At this instant, {planetNames[h.transitPlanet]} in transit forms this angle with {planetNames[h.natalPlanet]} natal for {h.natalTarget === 'user' ? userName : partnerName}, with an orb of {h.orb.toFixed(2)}°. This is a symbolic reading and does not determine events.</p></details>
                </div>
                <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded-full ${h.vibe === 'harmonico' ? 'text-gold bg-gold/10' : h.vibe === 'tenso' ? 'text-astro-pink bg-astro-pink/10' : 'text-zinc-400 bg-white/5'}`}>
                  {{harmonico:'Harmonious',tenso:'Tense',neutro:'Neutral'}[h.vibe]}
                </span>
              </motion.div>
            ))}
          </div>
          <button className="workspace-secondary" onClick={() => setShowAll(v => !v)}>{showAll ? 'Show highlights' : `Show all ${data.hits?.length || 0} contacts`}</button>
          <label className="block text-sm">Reflect on transits for <select className="ml-2" value={journalTarget} onChange={e => setJournalTarget(e.target.value as 'user' | 'partner')}><option value="user">{userName}</option><option value="partner">{partnerName}</option></select></label>
          <ChartJournal key={journalProfile(synastry[journalTarget])} profile={journalProfile(synastry[journalTarget])} name={journalTarget === 'user' ? userName : partnerName} prompt="What would you like to record about this day? Your observations do not need to match a forecast." context={`Transits at ${data.utc} · ${data.engine}. ${((data.hits || data.topHits).filter(h => h.natalTarget === journalTarget)).map(h => `${planetNames[h.transitPlanet]} in transit: ${h.type} with ${planetNames[h.natalPlanet]} natal, orb ${h.orb.toFixed(2)}°`).join('; ') || 'No contacts within the chosen orbs.'}`} />
        </>
      )}
    </div>
  );
}

