/p><h3>{term.title}</h3><p className="workspace-muted text-sm leading-relaxed">{term.definition}</p><section className="space-y-3"><h4 className="text-sm font-semibold">{chart ? `In the chart of ${name}` : 'Your own example'}</h4><p className="workspace-note text-sm">{context.text}</p>{chart && (context.pointId || context.selection) && <button type="button" className="workspace-secondary" onClick={() => { setOpenContext(true); setPoint(context.pointId || null); }}>Open this example’s explanation</button>}</section></article>{openContext && chart && (point ? <div className="workspace-panel"><PlanetInterpretation chart={chart} planetId={point} name={name} /></div> : context.selection && <ChartElementExplanation chart={chart} selection={context.selection} onClose={() => setOpenContext(false)} onSelectPlanet={setPoint} />)}</div></div></section>;
