import { lazy, Suspense, useEffect, useRef, useState, useReducer, type ReactNode } from 'react';
import { Heart, Compass, UsersRound, MessageCircle, Pencil, Plus, Orbit, Sparkles, CalendarClock, Sun } from 'lucide-react';
import type { BirthDetails, Interpretation } from '../types';
import { computeChart, type ChartPayload, type ComputedChart, type ComputedSynastry } from '../lib/astro';
import { ChartDetails, AspectsList, ViewTabs } from './ChartDetails';
import { BirthProfileForm } from './BirthProfileForm';
import { PublicPeopleExplorer } from './PublicPeopleExplorer';
import { FamousMatches } from './FamousMatches';
import { WorkspaceProfiles, type ProfileSlot } from './WorkspaceProfiles';
import { AdvancedCharts } from './AdvancedCharts';
import { SynastryReading } from './SynastryReading';
import { CalculationSettings } from './CalculationSettings';
import { DailySky } from './DailySky';
import { FomalhautPanel } from './FomalhautPanel';
import { HermitGuide } from './HermitGuide';
import { DailyOverview } from './DailyOverview';
import { ExplainSheet } from './ExplainSheet';
import { YouPanel, MoodLogEditor } from './YouPanel';
import { useDailySky } from '../lib/daily-context';
import { initialSelection, selectionReducer, BODY_IDS, type BodyId } from '../lib/selection-state';
import { featuredPlanetForChart } from '../lib/featured-planet';
import type { DailyContact, PlanetCycleEvent } from '../lib/daily-sky';
import { ChartMakeup } from './ChartMakeup';
import { localNoon } from '../lib/civil-day';
const LearningGuide = lazy(() => import('./LearningGuide').then(module => ({ default: module.LearningGuide })));
import { useWorkspaceTheme, WorkspaceThemeButton } from './WorkspaceTheme';
import type { PlacementFilter } from '../lib/catalog';
import { defaultChartSettings, type ChartSettings } from '../lib/chart-settings';
import { BiWheelChart, CompositeCard, HouseOverlay, TransitsTodayCard } from './PremiumSynastry';

type Destination = 'you' | 'space' | 'today' | 'calendar' | 'user' | 'partner' | 'synastry' | 'explore' | 'profiles' | 'community' | 'timing' | 'learn';
const blank: BirthDetails = { name: '', date: '', time: '', location: '' };
interface Props {
  offline?: boolean; initialUser?: BirthDetails; initialPartner?: BirthDetails; initialChart?: ChartPayload | null; initialSlot?: ProfileSlot;
  interpretation?: Interpretation; premium?: boolean; onUnlock?: () => void;
  cloudLibrary?: ReactNode; community?: ReactNode;
  onComputed?: (user: BirthDetails, partner: BirthDetails, chart: ChartPayload, standaloneSlot?: ProfileSlot) => void;
  initialProfiles?: BirthDetails[]; transitReferenceUtc?: string;
}
export function ChartWorkspace({ offline = false, initialUser = blank, initialPartner = blank, initialChart, initialSlot = 'user', interpretation, premium = false, onUnlock, cloudLibrary, community, onComputed, initialProfiles, transitReferenceUtc }: Props) {
  const { theme, toggleTheme } = useWorkspaceTheme();
  const initialSynastry = initialChart && 'user' in initialChart ? initialChart : null;
  const [user, setUser] = useState(initialUser);
  const [partner, setPartner] = useState(initialPartner);
  const [userChart, setUserChart] = useState<ComputedChart | null>(initialSynastry?.user || (initialSlot === 'user' && initialChart && 'planets' in initialChart ? initialChart : null));
  const [partnerChart, setPartnerChart] = useState<ComputedChart | null>(initialSynastry?.partner || (initialSlot === 'partner' && initialChart && 'planets' in initialChart ? initialChart : null));
  const [synastry, setSynastry] = useState<ComputedSynastry | null>(initialSynastry);
  const [destination, setDestination] = useState<Destination>('today');
  const [timeZone, setTimeZone] = useState(() => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; } catch { return 'UTC'; } });
  const [selection, dispatchSelection] = useReducer(selectionReducer, undefined, () => {
    let slot = initialSlot;
    try { const saved = localStorage.getItem('astrolove_selected_person'); if (saved === 'user' || saved === 'partner') slot = saved; } catch {}
    return initialSelection(slot, timeZone);
  });
  const skySlot = selection.selectedPersonId as ProfileSlot;
  const selectedDate = selection.selectedDate;
  function setSkySlot(slot: ProfileSlot) { setExplainOpen(false); setLogOpen(false); dispatchSelection({type:'person',id:slot}); try { localStorage.setItem('astrolove_selected_person',slot); } catch {} }
  function setSelectedDate(date: string) { dispatchSelection({type:'date',date}); }
  const [explainOpen, setExplainOpen] = useState(false);
  const [logOpen, setLogOpen] = useState(false);
  const [chartSection,setChartSection] = useState<'overview'|'aspects'>('overview');
  const [featuredOverrides,setFeaturedOverrides] = useState<Record<string,BodyId>>(()=>{try{const value = JSON.parse(localStorage.getItem('astrolove_featured_planets') || '{}'); return value && typeof value === 'object' && !Array.isArray(value) ? Object.fromEntries(Object.entries(value).filter(([, id]) => BODY_IDS.includes(id as BodyId))) as Record<string,BodyId> : {};}catch{return {};}});
  const [timingSeed, setTimingSeed] = useState<{ date: string; zone: string; at: string; planet?: string; natalPoint?: string; angle?: number } | null>(null);
  const [chartLens, setChartLens] = useState<'chart' | 'makeup'>('chart');
  const focusPlanet = selection.selectedBody || 'sun';
  function setFocusPlanet(id: string) { if (BODY_IDS.includes(id as BodyId)) dispatchSelection({type:'body',id:id as BodyId}); }
  function navigate(next: Destination) {
    if (next === 'user' || next === 'partner') setSkySlot(next);
    setDestination(next); setExplainOpen(false); setLogOpen(false); setEditing(null); setError('');
  }
  const [editing, setEditing] = useState<ProfileSlot | null>(null);
  const [busy, setBusy] = useState(false);
  const calculation = useRef<AbortController | null>(null);
  useEffect(() => () => { calculation.current?.abort(); }, []);
  const [error, setError] = useState('');
  const [relationshipView, setRelationshipView] = useState<'wheel' | 'aspects' | 'houses' | 'composite' | 'today' | 'reading'>('aspects');
  const [exploreView, setExploreView] = useState<'catalog' | 'similarity'>('catalog');
  const [explorePlacement, setExplorePlacement] = useState<PlacementFilter | undefined>();
  const [compareId, setCompareId] = useState<string | undefined>();
  const [learningSlot, setLearningSlot] = useState<ProfileSlot>(initialSlot);
  const [exploreSlot, setExploreSlot] = useState<ProfileSlot>('user');
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [settings, setSettings] = useState<ChartSettings>(() => {
    const metadata = initialSynastry?.user.metadata || (initialChart && 'planets' in initialChart ? initialChart.metadata : undefined);
    if (metadata?.settings) return metadata.settings;
    try { const stored = JSON.parse(localStorage.getItem('astrolove_calculation_settings') || 'null'); if (stored && ['equal', 'whole-sign', 'placidus'].includes(stored.houseSystem) && Object.keys(stored.orbs || {}).length === 5 && Object.keys(defaultChartSettings.orbs).every(k => typeof stored.orbs[k] === 'number' && stored.orbs[k] >= 0 && stored.orbs[k] <= 12)) return stored; } catch {}
    return structuredClone(defaultChartSettings);
  });
  async function calculate(details: BirthDetails, slot: ProfileSlot, nextSettings = settings) {
    if (calculation.current && !calculation.current.signal.aborted) return;
    const controller = new AbortController();
    calculation.current = controller;
    setBusy(true); setError('');
    const timedSignal = AbortSignal.any([controller.signal, AbortSignal.timeout(45000)]);
    const nextUser = slot === 'user' ? details : user;
    const nextPartner = slot === 'partner' ? details : partner;
    let persistedChart: ChartPayload | undefined;
    try {
      if ((slot === 'user' ? partnerChart : userChart) && nextUser.date && nextPartner.date) {
        const result = await computeChart('compatibility', nextUser, nextPartner, nextSettings, timedSignal) as ComputedSynastry;
        if (controller.signal.aborted) return;
        setUserChart(result.user); setPartnerChart(result.partner); setSynastry(result);
        persistedChart = result;
      } else {
        const result = await computeChart('chart', details, undefined, nextSettings, timedSignal) as ComputedChart;
        if (controller.signal.aborted) return;
        if (slot === 'user') setUserChart(result); else setPartnerChart(result);
        persistedChart = result;
        setSynastry(null);
      }
      setUser(nextUser); setPartner(nextPartner); setEditing(null); setSkySlot(slot); navigate('today'); setSettings(nextSettings); setSettingsOpen(false);
      try { localStorage.setItem('astrolove_calculation_settings', JSON.stringify(nextSettings)); } catch {}
      if (persistedChart) {
        try { onComputed?.(nextUser, nextPartner, persistedChart, slot); }
        catch { setError("The chart was calculated, but the result could not be saved on this device. The displayed chart still matches your entered details."); }
      }
    } catch (err) { if (!controller.signal.aborted) setError(err instanceof Error ? err.message : "This chart could not be calculated."); }
    finally { if (!controller.signal.aborted) setBusy(false); if (calculation.current === controller) calculation.current = null; }
  }
  const activeSlot = destination === 'partner' ? 'partner' : destination === 'user' ? 'user' : skySlot;
