  function openChart(planetId = focusPlanet) { setFocusPlanet(planetId); setChartLens('chart'); navigate(skySlot); }
  function openTimeline(at?: string, planet?: string, natalPoint?: string, angle?: number) { if (at) setTimingSeed({ date: selectedDate, zone: timeZone, at, planet, natalPoint, angle }); navigate('timing'); }
