  return <div className="astro-workspace" data-theme={theme} data-testid="chart-workspace"><aside className="workspace-sidebar"><div className="workspace-brand"><span><Orbit size={26} aria-hidden="true" /></span><div>Hermit<small>YOUR SKY, YOUR RHYTHM</small></div></div><nav aria-label={"Primary navigation"}>{navigation.map(n => <button key={n.id} aria-current={section === n.id ? 'page' : undefined} disabled={busy} onClick={() => navigate(n.destination)}><n.icon size={18} /><span>{n.label}</span></button>)}</nav><div className="workspace-sidebar-note"><span className="engine-dot" /> Swiss Ephemeris<small>Calculated charts. Visible sources.</small></div></aside>
    <div className="workspace-content"><header className="workspace-header"><div><p className="workspace-eyebrow">{destination === 'synastry' ? "Two charts, one comparison" : destination === 'explore' ? "Connections beyond your circle" : "A place for your sky"}</p><h1>{headings[destination]}</h1></div><WorkspaceThemeButton theme={theme} onToggle={toggleTheme} /><button className="workspace-secondary" disabled={busy} onClick={() => navigate('profiles')}><UsersRound size={16} />  Choose profiles</button><button className="workspace-secondary" disabled={busy} aria-expanded={settingsOpen} onClick={() => setSettingsOpen(o => !o)}>Settings</button></header><div className="sky-context" aria-label={"Selected sky context"}><label>Person <select aria-label={"Selected sky person"} value={skySlot} disabled={busy} onChange={e => { const slot = e.target.value as ProfileSlot; setSkySlot(slot); setExplainOpen(false); if (destination === 'user' || destination === 'partner') navigate(slot); }}><option value="user">{user.name || "My profile"}</option><option value="partner">{partner.name || "Another person"}</option></select></label><label>Calendar timezone <select aria-label={"Calendar timezone"} value={timeZone} onChange={e => setTimeZone(e.target.value)}>{Array.from(new Set([timeZone, user.timezone, partner.timezone, 'UTC', 'America/Campo_Grande', 'America/Sao_Paulo', 'America/New_York', 'Europe/London', 'Asia/Tokyo', ...(typeof Intl.supportedValuesOf === 'function' ? Intl.supportedValuesOf('timeZone') : [])].filter(Boolean) as string[])).map(zone => <option key={zone} value={zone}>{zone.replaceAll('_', ' ')}</option>)}</select></label><span className="workspace-muted">{selectedDate.split('-').reverse().join('/')} · {activeChart ? activeDetails.name || "Selected profile" : "General sky: add a chart to personalize"}</span></div>
