        {['houses', 'composite', 'today', 'reading'].includes(relationshipView) && (!premium ? <div className="workspace-empty"><span><Sparkles size={32} aria-hidden="true" /></span><h3>Explore your reading further.</h3><p>House overlays, composite chart, transits and interpretation are included in the existing premium access.</p>{onUnlock && <button className="workspace-primary" onClick={onUnlock}>View premium access</button>}</div> : <>{relationshipView === 'houses' && <><HouseOverlay synastry={synastry} userName={user.name} partnerName={partner.name} /><HouseOverlay synastry={{ ...synastry, user: synastry.partner, partner: synastry.user, houseOverlay: { partnerInUser: synastry.houseOverlay.userInPartner, userInPartner: synastry.houseOverlay.partnerInUser } }} userName={partner.name} partnerName={user.name} /></>}{relationshipView === 'composite' && <CompositeCard synastry={synastry} />}{relationshipView === 'today' && <TransitsTodayCard synastry={synastry} userName={user.name} partnerName={partner.name} initialUtc={transitReferenceUtc} />}{relationshipView === 'reading' && <SynastryReading synastry={synastry} firstName={user.name || "You"} secondName={partner.name || "Partner"} onOpenChart={navigate} />}</>)}
