      {destination === 'profiles' && <div className="space-y-6"><WorkspaceProfiles user={userChart ? user : undefined} partner={partnerChart ? partner : undefined} onPick={calculate} busy={busy} initialProfiles={initialProfiles} />{cloudLibrary && <details className="workspace-panel"><summary>Account-synced library</summary><div className="mt-5">{cloudLibrary}</div></details>}</div>}
