import { useState } from 'react';
import { addJournalEntry, journalStorageKey, parseJournal, type JournalEntry } from '../lib/journal';

export function ChartJournal({ profile, name, context, prompt = 'What have you noticed in your experience that you would like to record?' }: { profile: string; name: string; context: string; prompt?: string }) {
  const [initial] = useState(() => { try { return { entries: parseJournal(localStorage.getItem(journalStorageKey)), error: '' }; } catch { return { entries: [] as JournalEntry[], error: 'Unable to read the saved journal. Existing data has been preserved and will not be overwritten.' }; } });
  const [entries, setEntries] = useState<JournalEntry[]>(initial.entries);
  const [text, setText] = useState('');
  const [error, setError] = useState(initial.error);
  const [saved, setSaved] = useState(false);
  const visible = entries.filter(e => e.profile === profile);
  function save() {
    try {
      // Re-read at every mutation to preserve notes written in another tab and fail closed on corrupt data.
      const current = parseJournal(localStorage.getItem(journalStorageKey));
      const next = addJournalEntry(current, { id: crypto.randomUUID(), profile, createdAt: new Date().toISOString(), text: text.trim(), context });
      localStorage.setItem(journalStorageKey, JSON.stringify(next)); setEntries(next); setText(''); setError(''); setSaved(true);
    } catch (e) { setError(e instanceof Error ? e.message : 'Unable to save on this device.'); }
  }
  function remove(id: string) {
    try { const next = parseJournal(localStorage.getItem(journalStorageKey)).filter(e => e.id !== id || e.profile !== profile); localStorage.setItem(journalStorageKey, JSON.stringify(next)); setEntries(next); setError(''); setSaved(false); }
    catch { setError('Unable to delete. Existing data has been preserved.'); }
  }
  function exportNotes() {
    try { const current = parseJournal(localStorage.getItem(journalStorageKey)).filter(e => e.profile === profile); const url = URL.createObjectURL(new Blob([JSON.stringify({ version: 1, name, entries: current }, null, 2)], { type: 'application/json' })); const link = document.createElement('a'); link.href = url; link.download = 'hermit-journal.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
    catch { setError('Unable to export saved notes.'); }
  }
  return <section className="workspace-panel space-y-5" aria-label={`Journal for ${name}`}><div className="section-heading"><div><p className="workspace-eyebrow">Your space for reflection</p><h3>Journal for {name}</h3></div><button className="workspace-secondary" onClick={exportNotes}>Export notes</button></div><p className="workspace-muted text-sm">Saved only in this browser, without being sent to a server or AI. Anyone using this browser can read the notes. Clearing browser data also erases your journal; export a copy to keep it.</p><form className="space-y-3" onSubmit={e => { e.preventDefault(); save(); }}><label className="block space-y-2"><span>{prompt}</span><textarea className="workspace-input w-full" rows={5} maxLength={10000} required value={text} onChange={e => { setText(e.target.value); setSaved(false); }} placeholder="Write in your own words…" /></label><details className="workspace-muted text-xs"><summary>Context saved with the note</summary><p className="mt-2">{context}</p></details><button className="workspace-primary" disabled={!text.trim()}>Save note</button>{saved && <p role="status" className="workspace-muted text-sm">Note saved in this browser.</p>}{error && <p role="alert" className="workspace-error">{error}</p>}</form><div className="space-y-4">{!visible.length && <p className="workspace-muted text-sm">Your journal begins with your first note. Notes are kept separate for each chart.</p>}{visible.map(e => <article key={e.id} className="border-t border-white/10 pt-4 space-y-2"><div className="flex justify-between gap-3"><time dateTime={e.createdAt} className="workspace-muted text-xs">{new Date(e.createdAt).toLocaleString('en-US')}</time><button className="workspace-secondary" aria-label={`Delete note from ${new Date(e.createdAt).toLocaleString('en-US')}`} onClick={() => remove(e.id)}>Delete</button></div><p className="whitespace-pre-wrap break-words">{e.text}</p><details className="workspace-muted text-xs"><summary>Recorded context</summary><p className="mt-2">{e.context}</p></details></article>)}</div></section>;
}

