}
function displayUtc(value: string): string { return `${value.replace('T', ' ').replace(/Z$/, '')} UTC`; }
const localZone = (() => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone; } catch { return undefined; } })();
/** Same instant in the device's civil time, because a UTC date can be a different calendar day locally. */
export function displayLocal(value: string, zone = localZone): string | null {
  if (!zone || zone === 'UTC' || zone === 'Etc/UTC') return null;
  try { return `${new Intl.DateTimeFormat('sv-SE', { timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(value))} · ${zone}`; } catch { return null; }
}
function Instant({ at }: { at: string }) { const local = displayLocal(at); return <><time dateTime={at}>{displayUtc(at)}</time>{local && <small className="block workspace-muted mt-1">{local} (device local time)</small>}</>; }
export function describeTimelineEvent(event: ExactEvent): string {
