  if (event.kind === 'station') return `${body} stations and becomes ${motion} at ${event.orb?.toFixed(2)}° of ${aspect} with ${natal} natal`;
  const orb = event.orb === undefined ? '' : ` · orb ${event.orb.toFixed(2)}°`;
