    return { tool: 'astrolover-timeline-repro' as const, schema: 1, capturedAt: new Date().toISOString(), search: lastSearch.current, selectedEvent: opened };
  }
  async function copyRepro() {
    const repro = buildReproCase(); if (!repro) return;
    try { await navigator.clipboard.writeText(JSON.stringify(repro, null, 2)); setReproCopied(true); setTimeout(() => setReproCopied(false), 2000); } catch { setReproCopied(false); }
