  return <section className="space-y-5" data-testid="advanced-charts"><div className="section-heading"><div><p className="workspace-eyebrow">Real geometry, explicit methods</p><h2>Cycles and dates for {birth.name || 'your profile'}</h2></div><CalendarClock size={25} className="workspace-muted" aria-hidden="true" /></div><ViewTabs<Mode> label="Timing techniques" value={mode} onChange={setMode} options={[{ id: 'transits', label: "Exact dates" }, { id: 'timeline', label: 'Timeline' }, { id: 'return', label: "Returns" }, { id: 'progression', label: 'Progressions' }]} />
