        <p className="workspace-muted text-xs">Click a milestone to open its calculated sky. The contact appears in the transit list using the timeline orb. Duration describes geometry rather than the intensity of an experience.</p>
        {visible.precision && <details className="workspace-muted text-xs"><summary>Search precision and method</summary><p className="mt-3">Entries, exits and exact passes use the same search with samples every {String(visible.precision.sampleStepHours)} hours and bisection to {String(visible.precision.rootBracketSeconds)} seconds and maximum angular residual of {String(visible.precision.maxResidualDegrees)}°. Stations are located by speed reversal. Speed is numerically noisy near zero, so station instants have a tolerance of {String(visible.precision.stationToleranceSeconds)} seconds. These limits describe the calculation, not birth-record accuracy or a forecast.</p></details>}</div>}
      {visible.mode === 'progression' && visible.chart && <div className="space-y-4"><div className="workspace-note"><p>Requested date: {displayUtc(utcInput(at))}.</p><p>Progressed ephemeris instant: {visible.progressedAt ? displayUtc(visible.progressedAt) : 'not supplied'}.</p><p>{visible.elapsedYears?.toFixed(6)}  elapsed tropical years.</p></div><ChartDetails key={`progression:${visible.progressedAt}`} chart={visible.chart} name={`${birth.name || "Profile"} · progressed positions`} onExplorePlacement={onExplorePlacement} /></div>}
      {eventLoading && <div className="flex items-center gap-3 flex-wrap"><p role="status" className="workspace-note">Opening sky for {selectedEvent ? displayUtc(selectedEvent.at) : 'this instant'}…</p><button className="workspace-secondary" onClick={clearEvent}>Cancel opening</button></div>}{eventError && <p role="alert" className="workspace-error">{eventError}</p>}{snapshot && selectedEvent && <div className="space-y-5"><div className="section-heading"><div><p className="workspace-eyebrow">{visible.mode === 'return' ? 'Return chart' : visible.mode === 'timeline' ? kindNames[selectedEvent.kind || 'exact'] : 'Sky at the exact instant'}</p><h3><Instant at={selectedEvent.at} /></h3>{visible.mode !== 'return' && <p className="workspace-muted text-sm mt-2" data-testid="event-geometry">{describeTimelineEvent(selectedEvent)} · {planetNames[selectedEvent.body] || selectedEvent.body} in {snapshot.planets.find(p => p.id === selectedEvent.body)?.sign} {snapshot.planets.find(p => p.id === selectedEvent.body)?.degree.toFixed(2)}°</p>}</div><button className="workspace-secondary" aria-label="Close instant chart" onClick={clearEvent}><X size={15} /></button></div>{snapshotWarnings.map(warning => <p className="workspace-note" key={warning}>{warning}</p>)}<ChartDetails key={`${visible.mode}:${selectedEvent.at}`} chart={snapshot} name={`${birth.name || "Profile"} · ${visible.mode === 'return' ? 'return' : 'transit'}`} onExplorePlacement={onExplorePlacement} />{transitLike && <div className="workspace-panel"><h3 className="mb-4">Transiting sky contacts with your natal chart</h3>{visible.mode === 'timeline' && <p className="workspace-muted text-xs mb-3">Orb limit for this list: {Math.max(visible.orb || 0, selectedEvent.orb || 0).toFixed(2)}°, the same as the timeline.</p>}<AspectsList aspects={contacts} firstName="Sky at this instant" secondName={birth.name || "Natal profile"} comparisonKind="transit" /></div>}</div>}
      {buildReproCase() && <details className="workspace-panel" data-testid="repro-case"><summary>Replay this case</summary><p className="workspace-muted text-xs leading-relaxed mt-3">If a date looks wrong later, copy this case and run <code>node scripts/replay-timeline-case.mjs</code> locally to investigate without repeating the screen steps. Nothing here is saved or sent automatically; this case is generated only when this panel is opened.</p><textarea readOnly className="workspace-input mt-3" style={{ fontFamily: 'monospace', fontSize: 11 }} rows={8} value={JSON.stringify(buildReproCase(), null, 2)} onFocus={e => e.currentTarget.select()} /><button type="button" className="workspace-secondary mt-3" onClick={copyRepro}><ClipboardCopy size={14} aria-hidden="true" />Copy case</button>{reproCopied && <span role="status" className="workspace-muted text-xs ml-3">Copied.</span>}</details>}
    </div>}
  </section>;
}

