import { useEffect, useState } from 'react';
import { Download, Pencil, Save, Trash2, Upload } from 'lucide-react';
import type { ComputedChart } from '../lib/astro';
import type { BirthDetails } from '../types';
import type { DailySkyResponse } from '../lib/daily-sky';
import { lunationPhase, phaseFromElongation, lunationPhaseNames } from '../lib/phase-cycle';
import { bodyIds, featuredPlanetForChart, traditionalRulers, type BodyId } from '../lib/featured-planet';
import { computeMoodPatterns, deleteMoodEntry, exportMoodLog, importMoodLog, MOOD_LOG_EVENT, MOOD_LOG_KEY, MOOD_TAGS, readMoodLog, saveMoodEntry, type MoodEntry, type MoodTag } from '../lib/mood-log';
import { interpretationFor } from '../lib/interpretation-content';
import { ChartMakeup } from './ChartMakeup';
import { AstroGlyph } from './AstroGlyph';

const names: Record<string, string> = { sun: 'Sun', moon: 'Moon', mercury: 'Mercury', venus: 'Venus', mars: "Mars", jupiter: 'Jupiter', saturn: "Saturn", uranus: "Uranus", neptune: "Neptune", pluto: 'Pluto' };
const glyphs: Record<string, string> = { sun: '☉', moon: '☽', mercury: '☿', venus: '♀', mars: '♂', jupiter: '♃', saturn: '♄', uranus: '♅', neptune: '♆', pluto: '♇' };
const signNames = ['Aries', "Taurus", 'Gemini', 'Cancer', 'Leo', "Virgo", 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', "Pisces"];
function snapshot() { try { return { entries: readMoodLog(), error: '' }; } catch (e) { return { entries: [] as MoodEntry[], error: e instanceof Error ? e.message : 'Unable to open the local journal.' }; } }
function useMoodLog() {
  const [state, setState] = useState(snapshot);
  useEffect(() => { const reload = () => setState(snapshot()); const onStorage = (event: StorageEvent) => { if (event.key === MOOD_LOG_KEY || event.key === null) reload(); }; window.addEventListener(MOOD_LOG_EVENT, reload); window.addEventListener('storage', onStorage); return () => { window.removeEventListener(MOOD_LOG_EVENT, reload); window.removeEventListener('storage', onStorage); }; }, []);
  return state;
}
interface LogProps { personId: string; date: string; timeZone: string; featuredPlanetId: string; sky?: DailySkyResponse | null; onSaved?: () => void }
export function MoodLogEditor(props: LogProps) { return <MoodLogForm key={`${props.personId}:${props.date}`} {...props} />; }
function MoodLogForm({ personId, date, timeZone, featuredPlanetId, sky, onSaved }: LogProps) {
  const { entries, error: storageError } = useMoodLog();
  const existing = entries.find(e => e.personId === personId && e.date === date);
  const [mood, setMood] = useState(existing?.mood || 3), [energy, setEnergy] = useState(existing?.energy || 3);
  const [tags, setTags] = useState<MoodTag[]>(existing?.tags || []), [note, setNote] = useState(existing?.note || '');
  const [error, setError] = useState(''), [message, setMessage] = useState('');
  useEffect(() => { setMood(existing?.mood || 3); setEnergy(existing?.energy || 3); setTags(existing?.tags || []); setNote(existing?.note || ''); }, [existing?.updatedAt]);
  const skyPlanet = sky?.date === date && sky.timeZone === timeZone ? sky.planets.find(p => p.id === featuredPlanetId) : undefined;
  function save() {
    try {
      if (storageError) throw new Error(storageError);
      const context = sky && skyPlanet ? { phase: phaseFromElongation(sky.moon.phaseAngle).phaseNumber, featuredPlanetId, motion: skyPlanet.retrograde ? 'retrograde' as const : 'direct' as const, at: sky.at, timeZone } : undefined;
      saveMoodEntry({ personId, date, mood, energy, tags, note, context });
      setMessage("Entry saved on this device."); setError(''); onSaved?.();
    } catch (e) { setError(e instanceof Error ? e.message : 'Unable to save.'); }
  }
  function remove() { try { deleteMoodEntry(personId, date); setMessage('Entry for this date deleted.'); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to delete.'); } }
  return <section className="you-card mood-editor" aria-label="Record of how you felt">
    <p className="you-label">Your log</p><h3>How do you feel today?</h3><p className="you-muted">{date} · {timeZone} · one entry per person and date</p>
    <form onSubmit={event => { event.preventDefault(); save(); }}>
      <fieldset><legend>Mood · from difficult to pleasant</legend><div className="mood-scale">{[1, 2, 3, 4, 5].map(value => <button key={value} type="button" aria-label={`Mood ${value} of 5`} aria-pressed={mood === value} onClick={() => setMood(value)}>{value}<small>{value === 1 ? 'Difficult' : value === 5 ? 'Pleasant' : ''}</small></button>)}</div></fieldset>
      <fieldset><legend>Energy · from low to high</legend><div className="mood-scale">{[1, 2, 3, 4, 5].map(value => <button key={value} type="button" aria-label={`Energy ${value} of 5`} aria-pressed={energy === value} onClick={() => setEnergy(value)}>{value}<small>{value === 1 ? "Low" : value === 5 ? "High" : ''}</small></button>)}</div></fieldset>
      <fieldset><legend>Which words fit your day? <small>Optional</small></legend><div className="mood-tags">{MOOD_TAGS.map(tag => <button key={tag} type="button" aria-pressed={tags.includes(tag)} onClick={() => setTags(current => current.includes(tag) ? current.filter(t => t !== tag) : [...current, tag])}>{tag}</button>)}</div></fieldset>
      <label className="mood-note">A note for yourself<textarea rows={3} value={note} maxLength={280} onChange={e => setNote(e.target.value)} placeholder="What would you like to remember about this day?" /><small>{Array.from(note).length}/280 characters</small></label>
      <p className="you-muted">{skyPlanet ? `Calculated · phase ${phaseFromElongation(sky!.moon.phaseAngle).phaseNumber}; ${names[featuredPlanetId]} ${skyPlanet.retrograde ? 'R · Retrograde' : 'Direct'}. This context is saved with your entry.` : 'You can record how you felt even without a calculated sky. Entries without calculated context are excluded from phase and motion patterns.'}</p>
      <div className="you-actions"><button type="submit" className="workspace-primary" disabled={Boolean(storageError)}><Save size={15} />{existing ? "Update entry" : 'Save entry'}</button>{existing && <button type="button" className="workspace-secondary" onClick={remove}><Trash2 size={15} />Delete entry</button>}</div>
    </form>{(error || storageError) && <p role="alert" className="workspace-error">{error || storageError}</p>}{message && <p role="status" className="you-muted">{message}</p>}
  </section>;
}

interface YouProps { chart: ComputedChart | null; birth: BirthDetails; personId: string; date: string; timeZone: string; featuredPlanetId: string; onFeaturedPlanetChange: (id: string) => void; onEditBirth: () => void; onSelectPlanet: (id: string) => void; sky?: DailySkyResponse | null }
export function YouPanel({ chart, birth, personId, date, timeZone, featuredPlanetId, onFeaturedPlanetChange, onEditBirth, onSelectPlanet, sky }: YouProps) {
  const { entries, error: storageError } = useMoodLog(), personEntries = entries.filter(e => e.personId === personId);
  const patterns = computeMoodPatterns(entries, personId, featuredPlanetId);
  const [exportText, setExportText] = useState(''), [importText, setImportText] = useState(''), [dataError, setDataError] = useState(''), [dataMessage, setDataMessage] = useState('');
  const [historyDate, setHistoryDate] = useState<string | null>(null);
  const sun = chart?.planets.find(p => p.id === 'sun'), moon = chart?.planets.find(p => p.id === 'moon');
  const phase = sun && moon ? lunationPhase(sun.lon, moon.lon) : null;
  const feature = chart ? featuredPlanetForChart(chart) : null;
  const content = phase ? interpretationFor(`phase:${phase.phaseNumber}`) : undefined;
  function download() { try { const json = exportMoodLog(); setExportText(json); setDataError(''); const blob = new Blob([json], { type: 'application/json' }), url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = 'hermit-mood-log.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (e) { setDataError(e instanceof Error ? e.message : 'Unable to export.'); } }
  function restore() { try { const restored = importMoodLog(importText); setDataMessage(`${restored.length} entries imported. The local journal was replaced.`); setImportText(''); setDataError(''); } catch (e) { setDataError(e instanceof Error ? e.message : 'Unable to import.'); } }
  return <div className="you-panel">
    <section className="you-card"><div className="you-heading"><div><p className="you-label">YOUR PROFILE</p><h2>{birth.name || 'Your space'}</h2></div><button type="button" className="workspace-secondary" onClick={onEditBirth}><Pencil size={15} />{chart ? "Edit birth details" : 'Create my chart'}</button></div><dl className="you-facts"><div><dt>Birth</dt><dd>{birth.date || 'Not supplied'}</dd></div><div><dt>Birth time</dt><dd>{chart?.metadata?.timeKnown ? birth.time : 'birth time unknown'}</dd></div><div><dt>Birthplace</dt><dd>{birth.location || 'Not supplied'}</dd></div><div><dt>Birth timezone</dt><dd>{birth.timezone || (chart?.metadata?.timeKnown ? 'Check the profile details' : 'UTC reference without a place')}</dd></div><div><dt>Resolved instant · UTC</dt><dd>{chart?.metadata?.utc || 'Calculate a chart to see the instant'}</dd></div><div><dt>Calendar timezone</dt><dd>{timeZone}</dd></div></dl>{chart?.metadata?.timeKnown === false && <p className="workspace-note">Birth time unknown · 12:00 local birth reference (UTC if no place was supplied). The Ascendant, houses and chart ruler are not estimated. The exact Moon position depends on the birth time.</p>}</section>
    <section className="you-card"><p className="you-label">YOUR FEATURED PLANET</p><h3>Featured planet</h3><p className="you-muted">The default is the traditional Sun-sign ruler. You can choose any of the ten bodies. The chart ruler is the Ascendant’s ruler and requires a birth time and place.</p><div className="you-featured-grid">{bodyIds.map(id => <button type="button" key={id} aria-pressed={featuredPlanetId === id} onClick={() => onFeaturedPlanetChange(id)}><AstroGlyph symbol={glyphs[id]} size={22} /><span>{names[id]}</span></button>)}</div>{feature && <p className="you-muted">Calculated · Sun-sign ruler of {signNames[feature.sunSignIndex]}: {names[feature.bodyId]}.</p>}{feature?.uncertainSunSign && <label className="you-confirm-sign">Sun sign may differ · the reference Sun is within 1° of a sign boundary. Confirm the sign used to select the featured planet:<select aria-label="Confirm Sun sign for the featured planet" defaultValue="" onChange={e => { if (e.target.value !== '') onFeaturedPlanetChange(traditionalRulers[Number(e.target.value)]); }}><option value="" disabled>Choose confirmed sign</option>{signNames.map((name, i) => <option key={name} value={i}>{name}</option>)}</select></label>}</section>
    {chart && <ChartMakeup chart={chart} name={birth.name} onSelectPlanet={onSelectPlanet} />}
    {phase && <section className="you-card"><p className="you-label">YOUR BIRTH PHASE</p><h3>{phase.phaseName}</h3><p><strong>Calculated</strong>  · phase {phase.phaseNumber} of 8 · elongation {phase.phaseAngle.toFixed(2)}° · illumination {phase.illuminationPercent.toFixed(1)}%.</p>{chart?.metadata?.timeKnown !== true && <p className="you-muted">Provisional noon reference; the exact birth phase may differ.</p>}<p><strong>Astrological meaning</strong> · {content?.short}</p><p className="you-muted">Source: {content?.source}</p><p><strong>Your log</strong> · n = {personEntries.length} personal entries; the natal phase does not predict your mood.</p></section>}
    <MoodLogEditor personId={personId} date={date} timeZone={timeZone} featuredPlanetId={featuredPlanetId} sky={sky} />
    <section className="you-card"><p className="you-label">Your log</p><h3>Your history</h3><p className="you-muted">Only on this device · n = {personEntries.length} entries for this profile.</p>{!personEntries.length ? <p className="you-muted">Your first entry appears here after you save it.</p> : <div className="you-log-history">{[...personEntries].reverse().map(entry => <button key={entry.date} type="button" onClick={() => setHistoryDate(historyDate === entry.date ? null : entry.date)} aria-expanded={historyDate === entry.date}><span>{entry.date}<small>{entry.tags.join(' · ') || "No tags"}</small></span><span>Mood {entry.mood}/5 · Energy {entry.energy}/5</span></button>)}</div>}{historyDate && personEntries.some(e => e.date === historyDate) && <MoodLogEditor personId={personId} date={historyDate} timeZone={timeZone} featuredPlanetId={featuredPlanetId} sky={sky?.date === historyDate ? sky : null} />}</section>
    <section className="you-card"><p className="you-label">YOUR PATTERNS</p><h3>Observe and draw your own conclusions.</h3><p className="you-muted">Each group appears only after 10 entries with calculated context. Average mood and energy use a 1–5 scale; motion groups use the featured planet selected when you logged the day.</p>{patterns.length ? <div className="you-pattern-grid">{patterns.map(pattern => <article key={`${pattern.kind}-${pattern.key}`}><h4>{pattern.kind === 'phase' ? `Phase ${pattern.key} · ${lunationPhaseNames[Number(pattern.key) - 1]}` : `${names[featuredPlanetId]} · ${pattern.key === 'direct' ? 'Direct' : 'R · Retrograde'}`}</h4><p>Average mood {pattern.averageMood.toFixed(1)}/5<br />Average energy {pattern.averageEnergy.toFixed(1)}/5</p><p>n = {pattern.n}</p><strong>Your own log, not proof</strong></article>)}</div> : <p className="you-muted">There are no groups with at least 10 entries yet. No pattern is inferred for days without entries.</p>}</section>
    <section className="you-card"><p className="you-label">YOUR DATA</p><h3>Take your journal with you.</h3><p className="you-muted">The JSON includes all local entries for every profile with their original context and dates. It is not sent to a server.</p><button type="button" className="workspace-secondary" onClick={download}><Download size={15} />Export journal JSON</button>{exportText && <details className="you-import"><summary>View exported JSON</summary><textarea readOnly rows={5} value={exportText} aria-label="Exported journal JSON" /></details>}<details className="you-import"><summary>Import journal JSON</summary><p className="you-muted">Import and replace replaces all entries on this device with the file’s entries. An invalid file does not change existing records.</p><label>Choose JSON file<input type="file" accept="application/json,.json" onChange={async e => { const file = e.target.files?.[0]; if (file) { if (file.size > 20 * 1024 * 1024) { setDataError('The file exceeds 20 MB.'); return; } setImportText(await file.text()); } }} /></label><textarea rows={5} value={importText} onChange={e => setImportText(e.target.value)} aria-label="JSON to import" placeholder="Paste JSON exported from Hermit here" /><button type="button" className="workspace-secondary" disabled={!importText.trim()} onClick={restore}><Upload size={15} />Import and replace</button></details>{(dataError || storageError) && <p role="alert" className="workspace-error">{dataError || storageError}</p>}{dataMessage && <p role="status" className="you-muted">{dataMessage}</p>}</section>
  </div>;
}

