import { useId } from 'react';
import { AstroGlyph } from './AstroGlyph';
import { layoutPlanetMarkers, formatSignDegree } from '../lib/chart-wheel-layout';
import { zodiacNames } from '../lib/catalog';
import type { ComputedChart } from '../lib/astro';

type Props = {
  teaser?: boolean;
  chart?: ComputedChart | null;
  selectedPlanet?: string;
  onSelectPlanet?: (id: string) => void;
  onSelectSign?: (index: number) => void;
  onSelectHouse?: (number: number) => void;
  onSelectAspect?: (a: string, b: string) => void;
  hideUncertainMoon?: boolean;
};

const ZODIAC_GLYPHS = ['♈', '♉', '♊', '♋', '♌', '♍', '♎', '♏', '♐', '♑', '♒', '♓'];
const ZODIAC_COLORS = [
  '#ff6b6b', '#7bd389', '#ffd166', '#77c7ff',
  '#ffb347', '#a6c36f', '#ff8ec7', '#c06cff',
  '#ff5e5e', '#6b8cff', '#5ad6ff', '#b388ff',
];

const PLANET_COLORS: Record<string, string> = {
  sun: '#ffd166', moon: '#cbd5ff', mercury: '#b8f2e6', venus: '#ffb6d9',
  mars: '#ff8b7a', jupiter: '#ffe29a', saturn: '#9fb4c7', uranus: '#77e8ff',
  neptune: '#7a9aff', pluto: '#c084ff',
};

export function NatalChartWheel({ teaser = false, chart, selectedPlanet, onSelectPlanet, onSelectSign, onSelectHouse, onSelectAspect, hideUncertainMoon = false }: Props) {
  const svgId = useId().replaceAll(':', '');
  if (!chart?.planets?.length) return <div role="status" className="text-zinc-400 text-center p-8">Calculated chart unavailable.</div>;
  const size = 560;
  const cx = size / 2;
  const cy = size / 2;
  const rOuter = 260;
  const rZodiac = 230;
  const rHouseOuter = 205;
  const rHouseInner = 95;
  const rInnerHub = 80;

  const polar = (r: number, deg: number) => {
    // Wheel convention: 0° Aries at left (9 o'clock), counterclockwise.
    // If ascendant present, rotate so Asc sits at left. Otherwise use raw lon.
    const asc = chart?.ascendant ?? 0;
    const d = ((deg - asc) % 360 + 360) % 360;
    const rad = (180 - d) * (Math.PI / 180);
    return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
  };

  const realPlanets = chart?.planets?.length
    ? layoutPlanetMarkers(chart.planets.filter(p => !(hideUncertainMoon && !chart.metadata?.timeKnown && p.id === 'moon'))).map((p, i) => {
        const color = PLANET_COLORS[p.id] || ZODIAC_COLORS[i % 12];
        return {
          id: p.id,
          glyph: p.symbol || ZODIAC_GLYPHS[i % 12],
          name: p.name,
          degree: p.degree,
          lon: p.lon,
          displayLon: p.displayLon,
          color,
          approximate: p.id === 'moon' && !chart.metadata?.timeKnown,
          r: 196,
        };
      })
    : [];

  const zodiacSegments = Array.from({ length: 12 }).map((_, i) => {
    const start = polar(rOuter, i * 30);
    const end = polar(rOuter, (i + 1) * 30);
    const startInner = polar(rZodiac, i * 30);
    const endInner = polar(rZodiac, (i + 1) * 30);
    return {
      path: `M ${start.x} ${start.y} A ${rOuter} ${rOuter} 0 0 0 ${end.x} ${end.y} L ${endInner.x} ${endInner.y} A ${rZodiac} ${rZodiac} 0 0 1 ${startInner.x} ${startInner.y} Z`,
      glyph: ZODIAC_GLYPHS[i],
      glyphPos: polar((rOuter + rZodiac) / 2, i * 30 + 15),
      color: ZODIAC_COLORS[i],
    };
  });

  const aspectPoints = [...realPlanets,
    ...(!chart.metadata?.timeKnown || chart.ascendant == null ? [] : [{ id: 'ascendant', name: "Ascendant", glyph: 'AC', degree: chart.ascendant % 30, lon: chart.ascendant, color: '#d6c69f', r: rHouseOuter }]),
    ...(!chart.metadata?.timeKnown || chart.midheaven == null ? [] : [{ id: 'midheaven', name: "Midheaven", glyph: 'MC', degree: chart.midheaven % 30, lon: chart.midheaven, color: '#b7add0', r: rHouseOuter }])];
  const aspectPairs = chart?.aspects?.length
    ? chart.aspects
        .filter(a => chart.metadata?.timeKnown || (a.a !== 'moon' && a.b !== 'moon'))
        .filter(a => selectedPlanet ? a.a === selectedPlanet || a.b === selectedPlanet : a.strength === 'forte' || Math.abs(a.orb) <= 3)
        .slice(0, selectedPlanet ? chart.aspects.length : 24)
        .map((a) => {
          const from = aspectPoints.find((p) => p.id === a.a);
          const to = aspectPoints.find((p) => p.id === a.b);
          if (!from || !to) return null;
          const color = a.vibe === 'harmonico' ? '#7bd389' : a.vibe === 'tenso' ? '#ff8ec7' : '#ffd166';
          return { from, to, color, aspect: a };
        })
        .filter(Boolean) as Array<{ from: typeof realPlanets[0]; to: typeof realPlanets[0]; color: string; aspect: ComputedChart['aspects'][number] }>
    : [];

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`0 0 ${size} ${size}`}
      aria-label={"Calculated chart: planets, signs and houses when available"}
      className="w-full h-full"
      style={{ filter: 'drop-shadow(0 0 40px rgba(255, 210, 140, 0.15))' }}
    >
      <defs>
        <radialGradient id={`${svgId}-chartBg`} cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#1a0f2e" stopOpacity="0.95" />
          <stop offset="60%" stopColor="#0a0614" stopOpacity="0.9" />
          <stop offset="100%" stopColor="#050508" stopOpacity="1" />
        </radialGradient>
        <radialGradient id={`${svgId}-hubGrad`} cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#ffd98a" stopOpacity="0.4" />
          <stop offset="100%" stopColor="#050508" stopOpacity="0" />
        </radialGradient>
        {teaser && (
          <linearGradient id={`${svgId}-fadeMask`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="white" stopOpacity="1" />
            <stop offset="55%" stopColor="white" stopOpacity="1" />
            <stop offset="100%" stopColor="white" stopOpacity="0.05" />
          </linearGradient>
        )}
        <mask id={`${svgId}-chartFade`}>
          <rect width={size} height={size} fill={teaser ? `url(#${svgId}-fadeMask)` : 'white'} />
        </mask>
      </defs>

      <g mask={`url(#${svgId}-chartFade)`}>
        <circle cx={cx} cy={cy} r={rOuter} fill={`url(#${svgId}-chartBg)`} />

        {zodiacSegments.map((seg, i) => (
          <g key={i} role={onSelectSign ? 'button' : undefined} tabIndex={onSelectSign ? 0 : undefined} aria-label={`Understand the sign of ${zodiacNames[i]}`} onClick={() => onSelectSign?.(i)} onKeyDown={e => { if (onSelectSign && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); onSelectSign(i); } }} style={{ cursor: onSelectSign ? 'pointer' : undefined }} className="chart-hit-target">
            <title>{`${zodiacNames[i]} · click to understand this sign`}</title>
            <path d={seg.path} fill={seg.color} fillOpacity={0.08} stroke={seg.color} strokeOpacity={0.35} strokeWidth={0.5} />
            <AstroGlyph symbol={seg.glyph} color={seg.color} size={23} x={seg.glyphPos.x - 11.5} y={seg.glyphPos.y - 11.5} />
          </g>
        ))}

        <circle cx={cx} cy={cy} r={rZodiac} fill="none" stroke="rgba(255,210,140,0.25)" strokeWidth={1} />
        <circle cx={cx} cy={cy} r={rHouseOuter} fill="none" stroke="rgba(255,255,255,0.1)" strokeWidth={0.5} strokeDasharray="2 3" />
        <circle cx={cx} cy={cy} r={rHouseInner} fill="none" stroke="rgba(255,210,140,0.25)" strokeWidth={1} />

        {(chart.metadata?.timeKnown ? chart.houses || [] : []).map((house, i) => {
          const next = chart.houses![(i + 1) % 12];
          const width = ((next.cuspLon - house.cuspLon) % 360 + 360) % 360;
          const outer = polar(rHouseOuter, house.cuspLon);
          const inner = polar(rHouseInner, house.cuspLon);
          const labelPos = polar(rHouseInner + 14, house.cuspLon + width / 2);
          return (
            <g key={i} role={onSelectHouse ? 'button' : undefined} tabIndex={onSelectHouse ? 0 : undefined} aria-label={`Understand House ${house.number}, cusp in ${house.sign} at ${house.degree.toFixed(2)} degrees`} onClick={() => onSelectHouse?.(house.number)} onKeyDown={e => { if (onSelectHouse && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); onSelectHouse(house.number); } }} style={{ cursor: onSelectHouse ? 'pointer' : undefined }} className="chart-hit-target">
              <title>{`House ${house.number} · ${house.sign} · ${house.degree.toFixed(2)}°`}</title>
              {onSelectHouse && <><line x1={inner.x} y1={inner.y} x2={outer.x} y2={outer.y} stroke="transparent" strokeWidth={12} pointerEvents="stroke" /><circle cx={labelPos.x} cy={labelPos.y} r={12} fill="transparent" /></>}
              <line x1={inner.x} y1={inner.y} x2={outer.x} y2={outer.y} stroke="rgba(255,255,255,0.08)" strokeWidth={0.5} />
              <text x={labelPos.x} y={labelPos.y} textAnchor="middle" dominantBaseline="central" fill="rgba(255,255,255,0.6)" fontSize="9" fontWeight="700">
                {house.number}
              </text>
            </g>
          );
        })}

        {aspectPairs.map((asp, i) => {
          const p1 = polar(asp.from.r, asp.from.lon);
          const p2 = polar(asp.to.r, asp.to.lon);
          return (
            <g key={i} role={onSelectAspect ? 'button' : undefined} tabIndex={onSelectAspect ? 0 : undefined} aria-label={`Understand ${asp.aspect.type} between ${asp.from.name} and ${asp.to.name}, orb ${asp.aspect.orb.toFixed(2)} degrees`} onClick={() => onSelectAspect?.(asp.from.id, asp.to.id)} onKeyDown={e => { if (onSelectAspect && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); onSelectAspect(asp.from.id, asp.to.id); } }} style={{ cursor: onSelectAspect ? 'pointer' : undefined }} className="chart-hit-target"><title>{`${asp.from.name} · ${asp.aspect.type} · ${asp.to.name} · orb ${asp.aspect.orb.toFixed(2)}°`}</title>{onSelectAspect && <line x1={p1.x} y1={p1.y} x2={p2.x} y2={p2.y} stroke="transparent" strokeWidth={10} pointerEvents="stroke" />}<line
              x1={p1.x}
              y1={p1.y}
              x2={p2.x}
              y2={p2.y}
              stroke={asp.color}
              strokeOpacity={!selectedPlanet || asp.from.id === selectedPlanet || asp.to.id === selectedPlanet ? 0.65 : 0.08}
              strokeWidth={selectedPlanet && (asp.from.id === selectedPlanet || asp.to.id === selectedPlanet) ? 2 : 0.8}
              strokeDasharray="3 4"
            /></g>
          );
        })}

        <circle cx={cx} cy={cy} r={rInnerHub} fill={`url(#${svgId}-hubGrad)`} />
        <circle cx={cx} cy={cy} r={4} fill="#ffd98a" style={{ filter: 'drop-shadow(0 0 10px #ffd98a)' }} />

        {aspectPoints.filter(p => p.id === 'ascendant' || p.id === 'midheaven').map(p => { const pos = polar(p.r, p.lon); return <g key={p.id} role={onSelectPlanet ? 'button' : undefined} tabIndex={onSelectPlanet ? 0 : undefined} aria-label={`Select ${p.name}`} aria-pressed={onSelectPlanet ? selectedPlanet === p.id : undefined} onClick={() => onSelectPlanet?.(p.id)} onKeyDown={e => { if (onSelectPlanet && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); onSelectPlanet(p.id); } }} style={{ cursor: onSelectPlanet ? 'pointer' : 'default' }}><title>{`${p.name} · longitude ${p.lon.toFixed(2)}°`}</title><circle cx={pos.x} cy={pos.y} r={13} fill="#101116" stroke={p.color} /><AstroGlyph symbol={p.glyph} color={p.color} size={19} x={pos.x - 9.5} y={pos.y - 9.5} /></g>; })}

        {realPlanets.map((planet, i) => {
          const pos = polar(167, planet.displayLon);
          const anchor = polar(planet.r, planet.lon);
          return (
            <g key={i} role={onSelectPlanet ? 'button' : undefined} tabIndex={onSelectPlanet ? 0 : undefined} aria-label={`Select ${planet.name}${planet.approximate ? " · approximate position at local noon in the birth timezone" : ''} · ${planet.degree.toFixed(2)} degrees in sign`} aria-pressed={onSelectPlanet ? selectedPlanet === planet.id : undefined} onClick={() => onSelectPlanet?.(planet.id)} onKeyDown={e => { if (onSelectPlanet && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); onSelectPlanet(planet.id); } }} style={{ cursor: onSelectPlanet ? 'pointer' : 'default' }}>
              <title>{`${planet.name}${planet.approximate ? " · approximate local-noon reference in the birth timezone" : ''} · ${planet.lon.toFixed(2)}°`}</title>
              <line x1={anchor.x} y1={anchor.y} x2={pos.x} y2={pos.y} stroke={planet.color} strokeOpacity={0.5} strokeWidth={0.8} />
              <circle cx={anchor.x} cy={anchor.y} r={2.2} fill={planet.color} />
              <circle cx={pos.x} cy={pos.y} r={selectedPlanet === planet.id ? 18 : 14} fill="rgba(10,6,20,0.85)" stroke={planet.color} strokeWidth={selectedPlanet === planet.id ? 3 : 1} />
              <AstroGlyph symbol={planet.glyph} color={planet.color} size={20} x={pos.x - 10} y={pos.y - 10} />
              <text x={pos.x} y={pos.y + 25} textAnchor="middle" fill={planet.color} fontSize="9" fontWeight="500">{planet.approximate ? '≈ ' : ''}{formatSignDegree(planet.lon)}</text>
            </g>
          );
        })}
      </g>
      <text x={cx} y={size - 5} textAnchor="middle" fill="#a1a1aa" fontSize="8">Points: actual longitudes · fine lines: marker positions · degrees and minutes</text>
    </svg>
  );
}

