import { useState } from 'react';
import { defaultChartSettings, houseSystemNames, type ChartSettings, type HouseSystem } from '../lib/chart-settings';
export function CalculationSettings({ value, busy, onApply }: { value: ChartSettings; busy: boolean; onApply: (value: ChartSettings) => void }) {
  const [draft, setDraft] = useState(value);
  return <form className="workspace-panel space-y-4" onSubmit={e => { e.preventDefault(); onApply(draft); }}><div className="section-heading"><h3>Your calculation settings</h3><span>All active charts are recalculated</span></div><label className="block text-sm">House system <select value={draft.houseSystem} onChange={e => setDraft({ ...draft, houseSystem: e.target.value as HouseSystem })}>{Object.entries(houseSystemNames).map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></label><p className="workspace-muted text-xs">Placidus may be unavailable at polar latitudes. The engine reports the error without silently changing systems. The composite uses equal houses from the midpoint Ascendant.</p><div className="grid grid-cols-2 sm:grid-cols-5 gap-3">{Object.entries({ '0': "Conjunction", '60': "Sextile", '90': "Square", '120': "Trine", '180': "Opposition" }).map(([angle, name]) => <label key={angle} className="text-xs">{name}<input className="workspace-input" aria-label={`Orb for ${name}`} type="number" required min={0} max={12} step={0.1} value={draft.orbs[angle]} onChange={e => setDraft({ ...draft, orbs: { ...draft.orbs, [angle]: Number(e.target.value) } })} /></label>)}</div><div className="flex flex-wrap gap-3"><button className="workspace-primary" disabled={busy}>Apply and recalculate</button><button type="button" className="workspace-secondary" disabled={busy} onClick={() => setDraft(structuredClone(defaultChartSettings))}>Restore defaults</button></div></form>;
}

src/components/SynastryReading.tsx:
import type { ComputedSynastry } from '../lib/astro';
import { AspectsList } from './ChartDetails';

export function SynastryReading({ synastry, firstName, secondName, onOpenChart }: { synastry: ComputedSynastry; firstName: string; secondName: string; onOpenChart?: (slot: 'user' | 'partner') => void }) {
  const uncertain = !synastry.user.metadata?.timeKnown || !synastry.partner.metadata?.timeKnown;
  const contacts = synastry.crossAspects.filter(a => !uncertain || (a.a !== 'moon' && a.b !== 'moon'));
  return <article className="workspace-panel space-y-6" data-testid="synastry-reading"><header className="space-y-3"><p className="workspace-eyebrow">Two charts in dialogue</p><h3>Reading for {firstName}  and {secondName}</h3><p className="workspace-muted text-sm">Synastry compares points in two charts. Here there are {contacts.length} contacts within the selected orbs; each identifies the source person, the aspect and its distance from the exact angle.</p></header>{uncertain && <p className="workspace-note">A birth time is unknown. Lunar contacts are omitted; houses and angles appear only for profiles where they could be calculated. Other planets in that profile use the approximate noon reference in the birth timezone.</p>}<section className="space-y-3"><h4 className="font-semibold">How to read together</h4><p className="workspace-muted text-sm leading-relaxed">The Sun and Moon invite questions about self-expression and emotional care; Mercury, communication; Venus and Mars, affection, desire and boundaries. Begin with a contact you recognize in daily life and compare your experiences, allowing each person a different perspective.</p><p className="workspace-muted text-sm leading-relaxed">Conjunctions bring functions together; sextiles and trines suggest opportunities for cooperation; squares and oppositions invite questions about adjustments and different perspectives. These are symbolic conventions. A contact or percentage does not determine relationship quality.</p></section><section className="space-y-4"><h4 className="font-semibold">Your contacts, one by one</h4><p className="workspace-muted text-sm">Open a contact to read about both points, the aspect’s context and a practical discussion prompt. A smaller orb means greater geometric closeness.</p><AspectsList aspects={contacts} firstName={firstName} secondName={secondName} uncertain={uncertain} /></section><section className="space-y-3"><h4 className="font-semibold">Keep the individual charts nearby</h4><p className="workspace-muted text-sm">The same position also belongs to each person’s own chart. Check its sign, house and individual aspects alongside the contact between you.</p>{onOpenChart && <div className="flex gap-3 flex-wrap"><button type="button" className="workspace-secondary" onClick={() => onOpenChart('user')}>Chart and report for {firstName}</button><button type="button" className="workspace-secondary" onClick={() => onOpenChart('partner')}>Chart and report for {secondName}</button></div>}</section></article>;
}

