import { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, List, LayoutGrid, Search, Plus, X, Globe2, ExternalLink } from 'lucide-react';
import type { CatalogDetail, CatalogFilters, CatalogPage, PlacementFilter } from '../lib/catalog';
import { zodiacNames } from '../lib/catalog';
import { ChartDetails, PlanetBadge, planetNames } from './ChartDetails';

export function PublicPeopleExplorer({ onCompare, initialPlacement }: { onCompare?: (id: string) => void; initialPlacement?: PlacementFilter }) {
  const [filters, setFilters] = useState<CatalogFilters>(() => ({ sort: 'name', placements: initialPlacement ? [initialPlacement] : undefined }));
  const [browseMode, setBrowseMode] = useState<'placement' | 'advanced'>(initialPlacement?.house ? 'advanced' : 'placement');
  const [browsePoint, setBrowsePoint] = useState(initialPlacement?.point || 'sun');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(24);
  const [layout, setLayout] = useState<'cards' | 'table'>('cards');
  const [data, setData] = useState<CatalogPage | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [detail, setDetail] = useState<CatalogDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const [listError, setListError] = useState('');
  const [detailError, setDetailError] = useState('');
  const [listAttempt, setListAttempt] = useState(0);
  const [detailAttempt, setDetailAttempt] = useState(0);
  const detailRequestVersion = useRef(0);
  const detailRef = useRef<HTMLDivElement>(null);
  const initialPlacementKey = JSON.stringify(initialPlacement || null);
  const filterKey = JSON.stringify({ ...filters, placements: filters.placements?.filter(p => p.sign !== undefined || p.house !== undefined) });
  function closeDetail() { detailRequestVersion.current += 1; setSelected(null); setDetail(null); setDetailLoading(false); setDetailError(''); }
  function changePage(next: number) { setPage(next); closeDetail(); }
  function update(next: Partial<CatalogFilters>) { setFilters(f => ({ ...f, ...next })); setPage(1); closeDetail(); }
  function placement(index: number, next: Partial<PlacementFilter>) { update({ placements: filters.placements?.map((p, i) => i === index ? { ...p, ...next } : p) }); }
  useEffect(() => {
    const incoming = JSON.parse(initialPlacementKey) as PlacementFilter | null;
    if (!incoming) return;
    setBrowsePoint(incoming.point); setBrowseMode(incoming.house !== undefined ? 'advanced' : 'placement');
    update({ placements: [incoming] });
  }, [initialPlacementKey]);
  function browse(point: string, sign?: number) { setBrowsePoint(point); update({ placements: sign === undefined ? undefined : [{ point, sign }] }); }
  function switchBrowseMode(next: 'placement' | 'advanced') {
    setBrowseMode(next);
    if (next === 'placement') { const first = filters.placements?.[0]; browse(first?.point || browsePoint, first?.sign); }
  }
  useEffect(() => {
    const controller = new AbortController(); let current = true;
    setLoading(true); setListError('');
    const requestFilters = JSON.parse(filterKey) as CatalogFilters;
    if ([requestFilters.fromYear, requestFilters.toYear].some(year => year !== undefined && (!Number.isInteger(year) || year < 1200 || year > 2399))) {
      setListError('Informe anos inteiros entre 1200 e 2399.'); setLoading(false); return;
    }
    if (requestFilters.fromYear !== undefined && requestFilters.toYear !== undefined && requestFilters.fromYear > requestFilters.toYear) {
      setListError("The start year must be no later than the end year."); setLoading(false); return;
    }
    if (requestFilters.placements?.some(p => (p.degree !== undefined && (p.degree < 0 || p.degree >= 30)) || (p.tolerance !== undefined && (p.tolerance < 0 || p.tolerance > 15)))) {
      setListError("Use degrees from 0 to less than 30, and a margin between 0 and 15 degrees."); setLoading(false); return;
    }
    const timer = setTimeout(() => {
      fetch('/api/people', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ filters: requestFilters, page, pageSize }), signal: controller.signal })
        .then(async res => { const next = await res.json(); if (!res.ok) throw new Error(next.message || "The catalog could not be loaded."); if (current) setData(next); })
        .catch(e => { if (current && e.name !== 'AbortError') { setListError(e.message); } })
        .finally(() => { if (current) setLoading(false); });
    }, 250);
    return () => { current = false; clearTimeout(timer); controller.abort(); };
  }, [filterKey, page, pageSize, listAttempt]);
  useEffect(() => {
    if (!selected) { setDetailLoading(false); setDetailError(''); return; }
    const controller = new AbortController(); let current = true;
    const requestVersion = ++detailRequestVersion.current;
    const active = () => current && requestVersion === detailRequestVersion.current;
    let scrollTimer: ReturnType<typeof setTimeout> | undefined;
    setDetailLoading(true); setDetail(null); setDetailError('');
    fetch('/api/people', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ personId: selected }), signal: controller.signal })
      .then(async res => { const next = await res.json(); if (!res.ok) throw new Error(next.message || "Chart unavailable."); if (active()) { setDetail(next); scrollTimer = setTimeout(() => detailRef.current?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' }), 50); } })
      .catch(e => { if (active() && e.name !== 'AbortError') setDetailError(e.message); }).finally(() => { if (active()) setDetailLoading(false); });
    return () => { current = false; controller.abort(); clearTimeout(scrollTimer); };
  }, [selected, detailAttempt]);
  const activePlacements = filters.placements?.filter(p => p.sign !== undefined || p.house !== undefined) || [];
  const simplePlacement = activePlacements.length === 1 ? activePlacements[0] : undefined;
  const selectedBrowseSign = browseMode === 'placement' ? simplePlacement?.sign : undefined;
  const catalogTitle = simplePlacement?.sign !== undefined ? `People with ${planetNames[simplePlacement.point] || simplePlacement.point} in ${zodiacNames[simplePlacement.sign]}` : activePlacements.length ? "People matching combined criteria" : "Chart database";
  const timeRequired = filters.timeKnown === true || filters.placements?.some(p => (p.sign !== undefined || p.house !== undefined) && (['moon', 'ascendant', 'midheaven'].includes(p.point) || p.house !== undefined));
  const pageStart = data?.total ? (data.page - 1) * data.pageSize + 1 : 0;
  const pageEnd = data ? Math.min(data.page * data.pageSize, data.total) : 0;
  const pageWindow = data ? Array.from({ length: Math.min(5, data.pages) }, (_, i) => Math.max(1, Math.min(data.page - 2, data.pages - 4)) + i) : [];
  const pageNumbers = data ? [...new Set([1, ...pageWindow, data.pages])] : [];
  function pagination(position: "start" | 'fim') {
    if (!data?.total || listError) return null;
    return <nav aria-label={`Catalog pages (${position})`} className="catalog-pagination">
      <button className="workspace-secondary" disabled={loading || data.page <= 1} onClick={() => changePage(data.page - 1)}><ChevronLeft size={14} aria-hidden="true" />  Previous</button>
      <div>{pageNumbers.map((n, i) => <span className="catalog-page-number" key={n}>{i > 0 && n > pageNumbers[i - 1] + 1 && <span className="workspace-muted" aria-hidden="true">…</span>}<button className="workspace-secondary" aria-label={`Page ${n}`} aria-current={n === data.page ? 'page' : undefined} disabled={loading} onClick={() => changePage(n)}>{n}</button></span>)}</div>
      <button className="workspace-secondary" disabled={loading || data.page >= data.pages} onClick={() => changePage(data.page + 1)}>Next <ChevronRight size={14} aria-hidden="true" /></button>
      <span className="workspace-muted text-xs">Page {data.page}  of {data.pages}</span>
    </nav>;
  }
  return <section className="space-y-5" data-testid="public-catalog" aria-busy={loading}><div className="section-heading"><div><p className="workspace-eyebrow">Search people and placements</p><h2>{catalogTitle}</h2></div><Globe2 size={25} className="workspace-muted" aria-hidden="true" /></div>
    <div className="workspace-panel catalog-placement-browser space-y-4" data-testid="placement-browser">
      <div className="section-heading"><div><p className="workspace-eyebrow">Discover who shares a placement</p><h3>Explore by planet or Ascendant</h3></div></div>
      <div className="catalog-browse-modes" aria-label={"Astrology search mode"}><button className="workspace-secondary" aria-pressed={browseMode === 'placement'} onClick={() => switchBrowseMode('placement')}>Single placement</button><button className="workspace-secondary" aria-pressed={browseMode === 'advanced'} onClick={() => switchBrowseMode('advanced')}>Combine criteria</button></div>
      {browseMode === 'placement' && <div className="space-y-4"><div className="catalog-browse-point"><PlanetBadge id={browsePoint} /><label>Planet or point<select value={browsePoint} onChange={e => browse(e.target.value, selectedBrowseSign)}>{Object.entries(planetNames).map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></label><button className="workspace-secondary" onClick={() => browse('ascendant', 4)}>Ascendant in Leo</button></div><div className="catalog-sign-grid" aria-label={`Sign for ${planetNames[browsePoint]}`}><button className="workspace-secondary" aria-pressed={selectedBrowseSign === undefined} onClick={() => browse(browsePoint)}>All signs</button>{zodiacNames.map((sign, i) => <button className="workspace-secondary" key={sign} aria-label={`${planetNames[browsePoint]} in ${sign}`} aria-pressed={selectedBrowseSign === i} onClick={() => browse(browsePoint, i)}>{sign}</button>)}</div><p className="workspace-muted text-xs">Choose a point and sign to see a paginated list of people with individual sources. You can search without creating a profile.</p></div>}
      {timeRequired && <p className="workspace-note">This placement requires a documented birth time. {data ? `${data.knownTimeTotal} published records have a validated birth time.` : "Birth-time coverage will be shown with the results."}  People without a birth time are excluded from this list.</p>}
    </div>
    <div className="workspace-panel space-y-4"><h3>Refine the list</h3><div className="catalog-filter-grid"><label>Name, occupation or city<div className="relative"><Search size={14} aria-hidden="true" className="absolute right-3 top-3 workspace-muted" /><input className="workspace-input pr-8" maxLength={150} placeholder={"Search the database"} value={filters.query || ''} onChange={e => update({ query: e.target.value })} /></div></label><label>Country<select value={filters.country || ''} onChange={e => update({ country: e.target.value })}><option value="">All countries</option>{data?.facets.countries.map(c => <option key={c}>{c}</option>)}</select></label><label>Occupation<select value={filters.occupation || ''} onChange={e => update({ occupation: e.target.value })}><option value="">All occupations</option>{data?.facets.occupations.map(c => <option key={c}>{c}</option>)}</select></label><label>Category<select value={filters.category || ''} onChange={e => update({ category: e.target.value })}><option value="">All categories</option>{data?.facets.categories.map(c => <option key={c}>{c}</option>)}</select></label><label>Start year<input className="workspace-input" type="number" min={1200} max={2399} value={filters.fromYear ?? ''} onChange={e => update({ fromYear: e.target.value ? Number(e.target.value) : undefined })} /></label><label>End year<input className="workspace-input" type="number" min={1200} max={2399} value={filters.toYear ?? ''} onChange={e => update({ toYear: e.target.value ? Number(e.target.value) : undefined })} /></label><label>Birth time<select value={filters.timeKnown === undefined ? '' : String(filters.timeKnown)} onChange={e => update({ timeKnown: e.target.value ? e.target.value === 'true' : undefined })}><option value="">All records</option><option value="true">With documented time</option><option value="false">Without documented time</option></select></label></div>
