    {!listError && !!data?.rows.length && (layout === 'cards' ? <div className="catalog-cards">{data.rows.map(row => <article key={row.person.id} className="workspace-panel space-y-3"><p className="workspace-eyebrow">{row.person.category}</p><h3>{row.person.name}</h3><p className="workspace-muted text-xs">{row.person.date} · {row.person.countries.join(' / ') || "Country not supplied"}</p><p className="workspace-muted text-xs">{row.person.occupations.join(' · ')}</p><p className="workspace-muted text-xs">{row.person.birthPlaces.join(' · ') || "Place not supplied"}</p><div className="text-xs flex flex-wrap gap-2"><span>Sun in {row.planets.find(p => p.id === 'sun')?.sign || "Unavailable"}</span><span className="workspace-muted">ASC {row.ascendant?.sign || "unavailable"}</span></div><button className="workspace-secondary" disabled={loading} onClick={() => setSelected(row.person.id)} aria-label={`Open chart and sources for ${row.person.name}`}>Open chart and sources</button></article>)}</div> : <div className="catalog-table-scroll" tabIndex={0} role="region" aria-label={"People table; scroll to see all columns"}><table className="catalog-table"><caption className="sr-only">People and astrological placement search results</caption><thead><tr><th scope="col">Person</th><th scope="col">Birth</th><th scope="col">Country / occupation</th><th scope="col">Sun</th><th scope="col">Ascendant</th><th scope="col"><span className="sr-only">Chart</span></th></tr></thead><tbody>{data.rows.map(row => <tr key={row.person.id}><td>{row.person.name}</td><td>{row.person.date}</td><td>{row.person.countries.join(' / ') || "Country not supplied"}<small>{row.person.occupations.join(' · ')}</small></td><td>{row.planets.find(p => p.id === 'sun')?.sign || "Unavailable"}</td><td>{row.ascendant?.sign || "Birth time required"}</td><td><button className="workspace-secondary" disabled={loading} onClick={() => setSelected(row.person.id)} aria-label={`View chart for ${row.person.name}`}>View chart</button></td></tr>)}</tbody></table></div>)}
