ernalLink size={13} /></a>{detail.chart.metadata?.timeKnown && detail.person.timeEvidence && <div className="workspace-note"><a href={detail.person.timeEvidence.source} target="_blank" rel="noreferrer" className="inline-flex gap-2 items-center underline">Birth-time source <ExternalLink size={13} /></a><p>{detail.person.timeEvidence.note}</p><small>Reviewed on {detail.person.timeEvidence.checkedAt}</small></div>}{detail.person.attribution && <p className="workspace-muted text-xs">{detail.person.attribution}{detail.person.licenseUrl && <> · <a className="underline" href={detail.person.licenseUrl} target="_blank" rel="noreferrer">Data license</a></>}</p>}{detail.person.sourceNotes && <p className="workspace-muted text-xs">{detail.person.sourceNotes}</p>}<p className="workspace-muted text-xs">Reviewed on {detail.person.checkedAt} · {detail.person.license} · {detail.chart.metadata?.timeKnown ? "Documented birth time" : "Date only; approximate Moon, no houses or Ascendant"}</p>{onCompare && <button className="workspace-primary" onClick={() => onCompare(detail.person.id)}>Compare with selected profile</button>}</div><ChartDetails key={detail.person.id} chart={detail.chart} name={detail.person.name} initialLayout="research" onExplorePlacement={p => { setBrowseMode(p.house !== undefined ? 'advanced' : 'placement'); setBrowsePoint(p.point); update({ placements: [p] }); }} /></div>}
