import { useState } from 'react';
import { Moon, Sun } from 'lucide-react';

export type WorkspaceTheme = 'dark' | 'light';
const key = 'astrolove_workspace_theme';
function savedTheme(): WorkspaceTheme {
  try { return localStorage.getItem(key) === 'light' ? 'light' : 'dark'; }
  catch { return 'dark'; }
}
export function useWorkspaceTheme() {
  const [theme, setTheme] = useState<WorkspaceTheme>(savedTheme);
  function toggleTheme() {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    try { localStorage.setItem(key, next); } catch { /* Theme still works for this session. */ }
  }
  return { theme, toggleTheme };
}
export function WorkspaceThemeButton({ theme, onToggle }: { theme: WorkspaceTheme; onToggle: () => void }) {
  return <button type="button" className="workspace-secondary" onClick={onToggle} aria-label={theme === 'dark' ? "Use light theme" : "Use dark theme"} title={theme === 'dark' ? "Use light theme" : "Use dark theme"}>
    {theme === 'dark' ? <Sun size={16} aria-hidden="true" /> : <Moon size={16} aria-hidden="true" />}
    <span>{theme === 'dark' ? "Light theme" : "Dark theme"}</span>
  </button>;
}

