import { useMemo, useRef, useState } from 'react';
import { Download, FileText } from 'lucide-react';
import type { ComputedChart } from '../lib/astro';
import { buildChartReport, chartReportHtml } from '../lib/chart-report';
import { houseSystemNames } from '../lib/chart-settings';
import { houseTopics } from '../lib/chart-learning';
import { NatalChartWheel } from './NatalChartWheel';
import { ChartProvenance } from './ChartProvenance';

export function ChartReport({ chart, name, onSelectPlanet, onSelectSign, onSelectHouse, onSelectAspect }: { chart: ComputedChart; name: string; onSelectPlanet?: (id: string) => void; onSelectSign?: (index: number) => void; onSelectHouse?: (number: number) => void; onSelectAspect?: (a: string, b: string) => void }) {
  const wheelRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState('');
  const result = useMemo(() => {
    try { return { report: buildChartReport(chart, name), error: '' }; }
    catch (e) { return { report: null, error: e instanceof Error ? e.message : "The report could not be prepared." }; }
  }, [chart, name]);
  const report = result.report;
  if (!report) return <p className="workspace-error" role="alert">{result.error}</p>;
  function download() {
    setError('');
    try {
      const svg = wheelRef.current?.querySelector('svg')?.outerHTML;
      if (!svg) throw new Error("The chart wheel is not ready yet. Wait and try again.");
      const html = chartReportHtml(chart, name, svg);
      const url = URL.createObjectURL(new Blob([html], { type: 'text/html;charset=utf-8' }));
      const link = document.createElement('a');
      link.href = url; link.download = `hermit-${(name.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 60) || 'chart')}-report.html`;
      document.body.appendChild(link); link.click(); link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (e) { setError(e instanceof Error ? e.message : "The report could not be downloaded."); }
  }
  return <article className="space-y-6" data-testid="chart-report">
    <header className="workspace-panel space-y-4"><div className="section-heading"><div><p className="workspace-eyebrow">Chart and reading, together</p><h2>Report for {report.name}</h2></div><button type="button" className="workspace-secondary" onClick={download}><Download size={16} aria-hidden="true" />Download full report</button></div><p className="workspace-muted text-sm">Read the summary, check the numbers and explore each placement. The file includes the chart wheel, positions, houses, aspects and the same original readings. To create a PDF, open the file and choose Print → Save as PDF.</p><p className="workspace-muted text-xs">The download contains this profile's details and is created only when you request it. Share it only by choice.</p>{error && <p role="alert" className="workspace-error">{error}</p>}{report.input && <p className="workspace-note text-sm">{[report.input.date, report.input.time || "Birth time unknown", report.input.location, report.input.timezone].filter(Boolean).join(' · ')}</p>}{report.provenance?.source && <p className="workspace-muted text-xs"><a href={report.provenance.source} target="_blank" rel="noreferrer" className="underline">Provided birth source</a>{report.provenance.attribution && <> · {report.provenance.attribution}</>}{report.provenance.license && <> · {report.provenance.licenseUrl ? <a href={report.provenance.licenseUrl} target="_blank" rel="noreferrer" className="underline">{report.provenance.license}</a> : report.provenance.license}</>}</p>}{report.provenance?.note && <p className="workspace-muted text-xs">{report.provenance.note}</p>}{report.provenance?.coordinateSource && <p className="workspace-muted text-xs">City coordinates: <a href={report.provenance.coordinateSource} target="_blank" rel="noreferrer" className="underline">GeoNames · CC BY 4.0</a></p>}<ChartProvenance chart={chart} /></header>
    {!!report.limitations.length && <aside className="workspace-note space-y-2" aria-label={"Precision and limitations"}>{report.limitations.map((note, i) => <p key={i}>{note}</p>)}</aside>}
    <section className="workspace-panel space-y-4"><h3 className="flex items-center gap-2"><FileText size={18} aria-hidden="true" />How to read your chart</h3><p className="workspace-muted text-sm">Planets represent symbolic functions, signs describe modes of expression, houses indicate areas of experience, and aspects connect two points. Start with the Sun, Moon and Ascendant; then read placements alongside their contacts.</p><div ref={wheelRef} className="max-w-xl mx-auto"><NatalChartWheel chart={chart} hideUncertainMoon onSelectPlanet={onSelectPlanet} onSelectSign={onSelectSign} onSelectHouse={onSelectHouse} onSelectAspect={onSelectAspect} /></div><div className="grid gap-4 md:grid-cols-3">{report.summary.map(reading => <section key={reading.id} className="space-y-2"><h4 className="font-semibold">{reading.title}</h4><p className="workspace-muted text-xs">{reading.subtitle}</p><p className="workspace-muted text-sm">{reading.sections[0].text}</p><p className="workspace-muted text-sm">{reading.sections[1].text}</p>{onSelectPlanet && <button className="workspace-secondary" type="button" onClick={() => onSelectPlanet(reading.id)}>Open this placement's reading</button>}</section>)}</div></section>
    <section className="workspace-panel space-y-4"><h3>Calculated positions</h3><div className="catalog-table-scroll"><table className="catalog-table"><caption className="sr-only">Chart positions for {report.name}</caption><thead><tr>{["Point", "Sign", "Degree in sign", 'Longitude', "House", "Motion"].map(h => <th scope="col" key={h}>{h}</th>)}</tr></thead><tbody>{report.positions.map(p => <tr key={p.id}><th scope="row">{onSelectPlanet ? <button type="button" className="underline" onClick={() => onSelectPlanet(p.id)}>{p.name}</button> : p.name}</th><td>{p.sign}</td><td>{p.degree.toFixed(4)}°</td><td>{p.lon.toFixed(6)}°</td><td>{p.house || "Not calculated"}</td><td>{p.retrograde ? "Apparent retrograde" : "Direct"}</td></tr>)}{report.angularPositions.map(p => <tr key={p.id}><th scope="row">{onSelectPlanet ? <button type="button" className="underline" onClick={() => onSelectPlanet(p.id)}>{p.name}</button> : p.name}</th><td>{p.sign}</td><td>{p.degree.toFixed(4)}°</td><td>{p.lon.toFixed(6)}°</td><td colSpan={2}>Chart angle</td></tr>)}</tbody></table></div></section>
    <section className="workspace-panel space-y-4"><h3>Houses and cusps · {houseSystemNames[report.metadata.houseSystem]}</h3>{report.houses ? <div className="catalog-table-scroll"><table className="catalog-table"><caption className="sr-only">Calculated cusps</caption><thead><tr>{["House", "Sign", "Degree", 'Longitude', "Symbolic theme"].map(h => <th key={h} scope="col">{h}</th>)}</tr></thead><tbody>{report.houses.map(h => <tr key={h.number}><th scope="row">{h.number}</th><td>{h.sign}</td><td>{h.degree.toFixed(4)}°</td><td>{h.cuspLon.toFixed(6)}°</td><td>{houseTopics[h.number - 1]}</td></tr>)}</tbody></table></div> : <p className="workspace-muted">Houses are unavailable in this chart.</p>}</section>
    <section className="workspace-panel space-y-5"><h3>Readings by placement</h3><p className="workspace-muted text-sm">These original readings accompany the calculated positions. Local AI is optional and available within each planet's reading; this report provides a stable reference.</p>{report.readings.map(reading => <details key={reading.id} className="border-t border-white/10 pt-4"><summary className="font-semibold cursor-pointer">{reading.title} · {reading.subtitle}</summary><div className="space-y-4 mt-4">{reading.notes.map((note, i) => <p className="workspace-note text-sm" key={i}>{note}</p>)}{reading.sections.map(section => <section key={section.title}><h4 className="font-semibold text-sm mb-2">{section.title}</h4><p className="workspace-muted text-sm leading-relaxed">{section.text}</p></section>)}</div></details>)}</section>
    <section className="workspace-panel space-y-4"><h3>Calculated aspects · {report.aspects.length}  contacts</h3><p className="workspace-muted text-sm">The orb is the distance from the exact angle. The list starts with the smallest orbs; geometric closeness does not establish certainty about personality.</p>{report.aspects.map(a => <details key={`${a.a}-${a.b}`} className="border-t border-white/10 pt-3"><summary className="cursor-pointer text-sm">{a.firstName} · {a.type} · {a.secondName}  · orb {a.orb.toFixed(4)}°</summary><div className="space-y-3 mt-3"><p className="workspace-note text-xs">Separation {a.separation.toFixed(4)}° · exact angle {a.angle}°</p>{a.interpretation && <><p className="workspace-muted text-sm">{a.interpretation.context}</p><p className="workspace-muted text-sm">{a.interpretation.reflection}</p></>}</div></details>)}{!report.aspects.length && <p className="workspace-muted">No major aspects within the selected orbs.</p>}</section>
  </article>;
}

