import { useId } from 'react';
import { ArrowUpRight } from 'lucide-react';
import type { ComputedChart } from '../lib/astro';
import type { PlacementFilter } from '../lib/catalog';

import { describePlanet } from '../lib/planet-interpretation';

export function PlanetInterpretation({ chart, planetId, name, onExplorePlacement }: { chart: ComputedChart; planetId: string; name?: string; onExplorePlacement?: (placement: PlacementFilter) => void }) {
  const heading = useId();
  const reading = describePlanet(chart, planetId);
  return <section aria-labelledby={heading} className="space-y-5 planet-interpretation" data-testid="planet-interpretation">
    <div><h3 id={heading} className="text-lg font-semibold">{reading.title}</h3>{(name || reading.subtitle) && <p className="workspace-muted text-sm mt-1">{[name, reading.subtitle].filter(Boolean).join(' · ')}</p>}</div>
    {reading.notes.map(note => <p key={note} className="workspace-note text-sm">{note}</p>)}
    <div className="grid gap-5 sm:grid-cols-2">{reading.sections.map(section => <section key={section.title} className={['Essence', 'Aspects'].includes(section.title) ? 'sm:col-span-2' : ''}><h4 className="text-sm font-semibold mb-2">{section.title}</h4><p className="workspace-muted text-sm leading-relaxed">{section.text}</p></section>)}</div>
    {onExplorePlacement && reading.placement && <div><button type="button" className="workspace-secondary inline-flex items-center gap-2" onClick={() => onExplorePlacement(reading.placement!)}>{reading.discoveryLabel}<ArrowUpRight size={15} aria-hidden="true" /></button>{!chart.metadata?.timeKnown && <p className="workspace-muted text-xs mt-2">Search uses the reference position; unknown birth times remain identified in the catalog.</p>}</div>}
    <p className="workspace-muted text-xs leading-relaxed">Symbolic reading based on astrological conventions rather than a scientific description of personality.</p>
  </section>;
}

