  mercury: { short: 'Ideas and communication', about: 'Mercury represents thinking, exchanging ideas and learning. Traditionally associated with Gemini and Virgo, it is part of every chart.', prompt: 'Is there a conversation you would like to approach more clearly?' },
  venus: { short: "Affection and values", about: 'Venus symbolizes affection, pleasure, relationships and what we value.', prompt: 'What small pleasure would you like to make time for today?' },
  mars: { short: 'Action and initiative', about: 'Mars is associated with initiative, desire and how we act and set boundaries.', prompt: 'What next step fits your energy today?' },
  jupiter: { short: 'Learning and expansion', about: 'Jupiter symbolizes growth, perspective and meaning. This is a reflective language rather than a guarantee of luck.', prompt: 'What would you like to learn a little more about?' },
  saturn: { short: "Structure and commitment", about: 'Saturn is associated with time, responsibility and gradual development. Its presence does not announce difficulty.', prompt: 'Which commitment still feels meaningful to you?' },
  uranus: { short: 'Change and autonomy', about: 'In astrology, Uranus represents change, experimentation and autonomy.', prompt: 'Could you try a different approach to something familiar?' },
  neptune: { short: 'Imagination and sensitivity', about: 'Neptune symbolizes imagination, sensitivity and the boundaries between ideals and reality.', prompt: 'What inspires you, and what needs more clarity?' },
  pluto: { short: 'Transformation and depth', about: 'Pluto is associated with slow processes of transformation, power and revisiting patterns.', prompt: 'What are you ready to reconsider at your own pace?' },
};
const shortNames: Record<string, string> = { sun: 'Sun', moon: 'Moon', mercury: 'Mer', venus: 'Ven', mars: 'Mar', jupiter: 'Jup', saturn: 'Sat', uranus: 'Ura', neptune: "Nep", pluto: 'Plu' };
function offset(date: string, amount: number): string { const d = new Date(`${date}T12:00:00Z`); d.setUTCDate(d.getUTCDate() + amount); return d.toISOString().slice(0, 10); }
function moveMonth(date: string, amount: number): string { const d = new Date(`${date.slice(0, 7)}-01T12:00:00Z`); d.setUTCMonth(d.getUTCMonth() + amount); return d.toISOString().slice(0, 10); }
function dayLabel(date: string, options: Intl.DateTimeFormatOptions): string { return new Intl.DateTimeFormat('en-US', { ...options, timeZone: 'UTC' }).format(new Date(`${date}T12:00:00Z`)); }
function todayAt(timeZone: string): string { try { const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date()); return ['year', 'month', 'day'].map(type => parts.find(p => p.type === type)?.value).join('-'); } catch { return new Date().toISOString().slice(0, 10); } }

/** Projected illuminated hemisphere. The supplied phase angle comes from the ephemeris. */
function MoonDisc({ angle, illumination, small = false }: { angle: number; illumination: number; small?: boolean }) {
  const r = 44, side = angle <= 180 ? 1 : -1, terminator = 1 - 2 * Math.max(0, Math.min(1, illumination));
  const outline = Array.from({ length: 65 }, (_, i) => { const y = -r + 2 * r * i / 64; return `${50 + side * Math.sqrt(Math.max(0, r * r - y * y))},${50 + y}`; });
  const edge = Array.from({ length: 65 }, (_, i) => { const y = r - 2 * r * i / 64; return `${50 + side * terminator * Math.sqrt(Math.max(0, r * r - y * y))},${50 + y}`; });
  return <svg viewBox="0 0 100 100" className={small ? 'daily-moon-mini' : 'daily-moon-disc'} aria-hidden="true"><circle cx="50" cy="50" r={r} fill="#343746" /><polygon points={[...outline, ...edge].join(' ')} fill="#f3dfb5" /><circle cx="50" cy="50" r={r} fill="none" stroke="#b6a884" strokeOpacity=".35" /></svg>;
}

export function DailySky({ view, date, timeZone, birth, chart, settings, onDateChange, onOpenChart, onOpenTimeline, selectedBody, onSelectBody, onDayInspect, sharedSky }: Props) {
  const [response, setResponse] = useState<{ key: string; sky: Sky } | null>(null);
  const [failure, setFailure] = useState<{ key: string; message: string } | null>(null);
  const [retry, setRetry] = useState(0);
  const [selectedId, setSelectedId] = useState('moon');
  const generation = useRef(0);
  const headingId = useId();
  const key = JSON.stringify({ date, timeZone, birth, settings, chart: chart?.metadata });
  useEffect(() => {
    if (sharedSky) return;
    const controller = new AbortController(), version = ++generation.current;
    setFailure(null);
    fetchDailySky({ date, timeZone, birth, settings }, controller.signal).then(sky => {
      if (!controller.signal.aborted && generation.current === version) setResponse({ key, sky });
    }).catch(error => { if (!controller.signal.aborted && generation.current === version) setFailure({ key, message: error instanceof Error ? error.message : 'Unable to load this sky.' }); });
    return () => { controller.abort(); };
  }, [key, retry]);
  const sky = sharedSky ? sharedSky.data : response?.key === key ? response.sky : null;
  const error = sharedSky ? sharedSky.error : failure?.key === key ? failure.message : null;
  const selected = sky?.planets.find(p => p.id === (selectedBody || selectedId)) || sky?.planets[0];
  const topic = selected ? topics[selected.id] : undefined;
  const currentDate = todayAt(timeZone);
  const change = (next: string) => { if (next >= '1200-01-01' && next <= '2399-12-31') { onDateChange(next); onDayInspect?.(); } };
  const chooseBody = (id: string) => { setSelectedId(id); onSelectBody?.(id); };
  const monthLength = new Date(`${date.slice(0, 7)}-01T12:00:00Z`);
  monthLength.setUTCMonth(monthLength.getUTCMonth() + 1, 0);
  const monthDates = Array.from({ length: monthLength.getUTCDate() }, (_, i) => `${date.slice(0, 7)}-${String(i + 1).padStart(2, '0')}`);
  const selectedNatal = chart?.planets.find(p => p.id === selected?.id);
  const personal = Boolean(birth?.date && chart);
  const contacts = sky?.contacts.filter(c => c.transitPlanet === selected?.id) || [];
  return <section className="daily-sky" aria-labelledby={headingId}>
    <div className="daily-intro"><div><p className="daily-eyebrow">HERMIT · YOUR RHYTHM, YOUR SKY</p><h2 id={headingId}>{view === 'calendar' ? 'One day at a time.' : 'Your sky has stories.'}</h2><p>{view === 'calendar' ? 'Choose a date. Explore the Moon, planets and their connections.' : 'A little curiosity. A new way to understand yourself.'}</p></div><span className="daily-engine"><span /> Swiss Ephemeris</span></div>
    <div className="daily-datebar"><button type="button" aria-label={"Previous day"} onClick={() => change(offset(date, -1))} disabled={date <= '1200-01-01'}><ChevronLeft size={18} /></button><label><CalendarDays size={16} /><input aria-label="Sky date" type="date" value={date} min="1200-01-01" max="2399-12-31" onChange={e => { if (e.target.value) change(e.target.value); }} /></label><button type="button" aria-label="Next day" onClick={() => change(offset(date, 1))} disabled={date >= '2399-12-31'}><ChevronRight size={18} /></button><button type="button" className="daily-back-today" onClick={() => change(currentDate)} disabled={date === currentDate}>Today</button><small>{timeZone}</small></div>
    {error ? <div role="alert" className="daily-status"><CircleHelp size={26} /><h3>Shall we try again?</h3><p>{error}</p><button className="daily-action" onClick={() => sharedSky ? sharedSky.retry() : setRetry(r => r + 1)}><RefreshCw size={15} />  Try again</button></div> : !sky ? <div role="status" className="daily-status"><Orbit className="daily-loading" size={30} /><h3>Finding the sky for this date…</h3><p>Calculating actual positions and phases.</p></div> : <>
      <div className="daily-top-grid"><article className="daily-lunar-card"><div className="daily-lunar-copy"><span className="daily-pill"><Moon size={13} />  THE MOON ON THIS DATE</span><p className="daily-day-name">{dayLabel(date, { weekday: 'long', day: 'numeric', month: 'long' })}</p><h3>{sky.moon.phaseName}</h3><p>A phase to observe.<br />You help give it meaning.</p><button type="button" className="daily-text-button" onClick={() => chooseBody('moon')}>Explore the Moon <ArrowUpRight size={16} /></button></div><div className="daily-lunar-art"><MoonDisc angle={sky.moon.phaseAngle} illumination={sky.moon.illumination} /><span>{Math.round(sky.moon.illumination * 100)}% illuminated</span></div><div className="daily-lunar-bottom"><span>{sky.planets.find(p => p.id === 'moon')?.sign || 'Calculated Moon'}</span><span>{sky.moon.waxing ? 'Illumination increasing' : 'Illumination decreasing'}</span></div></article>
      <article className="daily-guide-card"><span className="daily-eyebrow">AN INVITATION TO CURIOSITY</span><Sparkles size={24} /><h3>{personal ? 'The sky meets your chart.' : 'Everyone has a universe.'}</h3><p>{personal ? 'Explore contacts between this date’s planets and your selected birth chart.' : 'Explore the Moon’s phases and the planets now. Add birth details to discover connections with your chart.'}</p><button type="button" className="daily-action" onClick={() => onOpenChart()}>{personal ? 'Explore my chart' : 'Create my chart'} <ArrowUpRight size={16} /></button><small>Your natal chart stays fixed. The sky changes with the date.</small></article></div>
      {view === 'calendar' ? <article className="daily-calendar daily-card"><div className="daily-section-heading"><div><p className="daily-eyebrow">YOUR LUNAR CALENDAR</p><h3>{dayLabel(date, { month: 'long', year: 'numeric' })}</h3></div><div className="daily-month-controls"><button type="button" aria-label="Previous month" onClick={() => change(moveMonth(date, -1))} disabled={date.slice(0, 7) === '1200-01'}><ArrowLeft size={17} /></button><button type="button" aria-label="Next month" onClick={() => change(moveMonth(date, 1))} disabled={date.slice(0, 7) === '2399-12'}><ArrowRight size={17} /></button></div></div><div className="daily-month-grid"><div className="daily-weekdays">{["Mon", "Tue", "Wed", "Thu", "Fri", 'Sat', "Sun"].map(w => <span key={w}>{w}</span>)}</div><div className="daily-month-days">{Array.from({ length: (new Date(`${date.slice(0, 7)}-01T12:00:00Z`).getUTCDay() + 6) % 7 }, (_, i) => <span key={`blank-${i}`} />)}{monthDates.map(dayDate => { const day = sky.month.find(sample => sample.date === dayDate); return !day ? <button key={dayDate} type="button" disabled aria-label={`${dayLabel(dayDate, { day: 'numeric', month: 'long' })}: civil date unavailable in this timezone`}><span>{Number(dayDate.slice(-2))}</span><small>This date does not exist in the timezone</small></button> : <button key={day.date} type="button" aria-pressed={day.date === date} aria-label={`${dayLabel(day.date, { day: 'numeric', month: 'long' })}: ${day.phaseName}`} onClick={() => change(day.date)} className={day.date === currentDate ? 'is-today' : ''}><span>{Number(day.date.slice(-2))}</span><MoonDisc angle={day.phaseAngle} illumination={day.illumination} small /><small>{day.phaseName}</small></button>; })}</div></div><p className="daily-caption">Tap a day to update the sky below. The phase is calculated at that date’s reference instant.</p></article> : <div className="daily-week-strip" aria-label="Explore nearby days">{Array.from({ length: 7 }, (_, i) => offset(date, i - 3)).filter(d => d >= '1200-01-01' && d <= '2399-12-31').map(day => <button key={day} type="button" aria-pressed={day === date} onClick={() => change(day)}><small>{dayLabel(day, { weekday: 'short' })}</small><strong>{Number(day.slice(-2))}</strong><span>{day === currentDate ? 'Today' : dayLabel(day, { month: 'short' })}</span></button>)}</div>}
      <article className="daily-card daily-planet-section"><div className="daily-section-heading"><div><p className="daily-eyebrow">TAP. DISCOVER. EXPLORE.</p><h3>Get to know the planets.</h3><p className="daily-caption">Sky for the selected date · actual zodiac positions</p></div><Orbit size={25} /></div><div className="daily-explore-grid"><div className="daily-orbit-wrap"><svg className="daily-orbit" viewBox="0 0 420 420" role="group" aria-label="Zodiac positions of the planets. You can also use the planet list alongside this view."><circle cx="210" cy="210" r="183" className="daily-orbit-ring" />{[60, 100, 140].map(r => <circle key={r} cx="210" cy="210" r={r} className="daily-orbit-ring" />)}{Array.from({ length: 12 }, (_, i) => { const a = i * Math.PI / 6 - Math.PI / 2; return <line key={i} x1={210 + 165 * Math.cos(a)} y1={210 + 165 * Math.sin(a)} x2={210 + 182 * Math.cos(a)} y2={210 + 182 * Math.sin(a)} className="daily-orbit-tick" />; })}<circle cx="210" cy="210" r="29" className="daily-orbit-center" /><text x="210" y="208" textAnchor="middle" className="daily-orbit-center-text">YOUR</text><text x="210" y="222" textAnchor="middle" className="daily-orbit-center-text">VIEW</text>{sky.planets.map((planet, i) => { const a = (planet.lon - 90) * Math.PI / 180, r = 70 + i % 4 * 30, x = 210 + r * Math.cos(a), y = 210 + r * Math.sin(a); return <g key={planet.id} role="button" tabIndex={0} aria-label={`Explore ${planet.name} in ${planet.sign}, ${planet.degree.toFixed(2)} degrees`} aria-pressed={selected?.id === planet.id} onClick={() => chooseBody(planet.id)} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); chooseBody(planet.id); } }} className={`daily-orbit-planet ${selected?.id === planet.id ? 'is-selected' : ''}`}><circle cx={x} cy={y} r="20" className="daily-orbit-target" /><circle cx={x} cy={y} r={planet.id === 'sun' ? 10 : 7} className={`daily-orbit-body planet-${planet.id}`} /><text x={x} y={y + 27} textAnchor="middle">{shortNames[planet.id] || planet.name}</text></g>; })}</svg><p className="daily-caption">Direction represents zodiac longitude. Radii and sizes are illustrative; this is not a distance map of the Solar System.</p></div><div className="daily-planet-list" aria-label="Choose a planet">{sky.planets.map(planet => <button type="button" key={planet.id} aria-pressed={selected?.id === planet.id} onClick={() => chooseBody(planet.id)}><span className={`daily-planet-dot planet-${planet.id}`} /><span><strong>{planet.name}</strong><small>{topics[planet.id]?.short || 'Explore this position'}</small></span><span>{planet.sign}<small>{planet.degree.toFixed(2)}°{planet.retrograde ? ' · retrograde' : ''}</small></span></button>)}</div></div></article>
      {selected && <article className="daily-card daily-meaning" aria-live="polite"><div className="daily-section-heading"><div><p className="daily-eyebrow">{topic?.short || 'SELECTED POSITION'}</p><h3>{selected.name} in {selected.sign}</h3><p className="daily-caption">{selected.degree.toFixed(2)}° in sign · longitude {selected.lon.toFixed(4)}°{selected.retrograde ? ' · retrograde motion' : ' · direct motion'}</p></div><span className="daily-pill">Sky on {dayLabel(date, { day: 'numeric', month: 'short' })}</span></div><div className="daily-meaning-grid"><div><h4>What it represents</h4><p>{topic?.about || 'Explore this chart position and its relationships with other points.'}</p><p className="daily-caption">The position above belongs to this date’s sky, rather than your birth chart.</p></div><div><h4>A question for you</h4><p className="daily-reflection">{topic?.prompt || 'What would you like to understand better in your chart?'}</p><button type="button" className="daily-text-button" onClick={() => onOpenChart(selected.id)}>{selectedNatal ? `At your birth: ${selectedNatal.name} in ${selectedNatal.sign}` : 'See this planet in my chart'} <ArrowUpRight size={15} /></button></div></div>{personal && <div className="daily-personal-contacts"><h4>Contacts with your chart</h4>{contacts.length ? <div className="daily-contact-list">{contacts.slice(0, 6).map((c, i) => <button key={`${c.transitPlanet}-${c.natalPlanet}-${c.angle}-${i}`} type="button" onClick={() => onOpenTimeline(sky.at, c.transitPlanet, c.natalPlanet, c.angle)}><span><strong>{selected.name} · {c.type}</strong><small>with {chart?.planets.find(p => p.id === c.natalPlanet)?.name || (c.natalPlanet === 'ascendant' ? "Ascendant" : c.natalPlanet === 'midheaven' ? 'Midheaven' : c.natalPlanet)} natal · angle {c.angle}° · orb {c.orb.toFixed(2)}°</small></span><ArrowUpRight size={17} /></button>)}</div> : <p>No contacts from this planet meet the selected orbs at the calculated instant. This does not describe how your day will unfold.</p>}<button type="button" className="daily-text-button" onClick={() => onOpenTimeline(sky.at, selected.id)}>Find this planet’s periods <ArrowRight size={15} /></button></div>}</article>}
      {sky.warnings.some(w => /unknown|no sample|1970|approximat|unavailable/i.test(w)) && <div className="daily-notes">{sky.warnings.filter(w => /unknown|no sample|1970|approximat|unavailable/i.test(w)).map((warning, i) => <p key={i}>{warning}</p>)}</div>}
      <details className="daily-method"><summary>How this sky was calculated</summary><p>{sky.engine} · tropical zodiac · reference instant: {new Date(sky.at).toLocaleString('en-US', { timeZone })} ({timeZone}) · UTC: {sky.at}.</p>{sky.warnings.map((warning, i) => <p key={i}>{warning}</p>)}<p>Positions and lunar illumination are astronomical calculations. Meanings and questions are interpretations for reflection rather than mood predictions. A reference instant does not capture every change during a day.</p></details>
    </>}
  </section>;
}

