import { useState } from 'react';
import { UsersRound } from 'lucide-react';
import type { BirthDetails } from '../types';
import { BirthProfileForm } from './BirthProfileForm';

export type ProfileSlot = 'user' | 'partner';
type Profile = { id: string; relationship: string; details: BirthDetails };
const storageKey = 'astrolove_workspace_profiles_v1';
const relationshipLabel = (value: string) => ({ Eu: 'Me', Par: 'Partner', 'Família': 'Family', Amigos: 'Friends', Outros: 'Other' } as Record<string, string>)[value] || value;
export function WorkspaceProfiles({ user, partner, onPick, busy, initialProfiles = [] }: { user?: BirthDetails; partner?: BirthDetails; onPick: (details: BirthDetails, slot: ProfileSlot) => void; busy: boolean; initialProfiles?: BirthDetails[] }) {
  const [profiles, setProfiles] = useState<Profile[]>(() => {
    const examples = initialProfiles.map((details, i) => ({ id: `example-${i}`, relationship: i === 0 ? 'Me' : i === 1 ? "Partner" : "Friends", details }));
    try { const raw = localStorage.getItem(storageKey); if (!raw) return examples; const stored = JSON.parse(raw); return Array.isArray(stored) ? stored.filter(p => typeof p.id === 'string' && typeof p.details?.date === 'string' && typeof p.details?.name === 'string') : examples; } catch { return examples; }
  });
  const [editing, setEditing] = useState<Profile | null>(null);
  const [category, setCategory] = useState("Family");
  const [query, setQuery] = useState('');
  const [error, setError] = useState('');
  const persist = (next: Profile[]) => { try { localStorage.setItem(storageKey, JSON.stringify(next)); setProfiles(next); setError(''); return true; } catch { setError("Could not save on this device. Check the browser's storage."); return false; } };
  const saveCurrent = (details: BirthDetails, relationship: string) => {
    const existing = profiles.find(p => JSON.stringify(p.details) === JSON.stringify(details));
    if (!existing) persist([...profiles, { id: crypto.randomUUID(), relationship, details }]);
  };
  return <div className="space-y-6"><div className="section-heading"><div><p className="workspace-eyebrow">Your circle</p><h2>The people in your life.</h2></div><button className="workspace-primary" disabled={busy} onClick={() => setEditing({ id: crypto.randomUUID(), relationship: "Family", details: { name: '', date: '', time: '', location: '' } })}>+ New profile</button></div>
    <p className="workspace-muted text-sm">Profiles are saved on this device. Choose a person for either chart; synastry uses the selected pair. Birth details are personal: save them with consent.</p>
    <div className="flex gap-3 flex-wrap">{user?.date && <button className="workspace-secondary" disabled={busy} onClick={() => saveCurrent(user, 'Me')}>Save {user.name || "my profile"}</button>}{partner?.date && <button className="workspace-secondary" disabled={busy} onClick={() => saveCurrent(partner, "Partner")}>Save {partner.name || "partner profile"}</button>}</div>
    {error && <p role="alert" className="text-red-300">{error}</p>}
    {editing && <div className="space-y-3"><label className="workspace-muted text-sm">Relationship <select value={category} onChange={e => setCategory(e.target.value)}>{['Me', "Partner", "Family", "Friends", "Other"].map(c => <option key={c}>{c}</option>)}</select></label><BirthProfileForm key={editing.id} initial={editing.details} title={"Save profile details"} busy={busy} onCancel={() => setEditing(null)} onSubmit={details => { if (persist([...profiles.filter(p => p.id !== editing.id), { ...editing, relationship: category, details }])) setEditing(null); }} /></div>}
    <input className="workspace-input" aria-label={"Search profiles"} placeholder={"Search by name or relationship"} value={query} onChange={e => setQuery(e.target.value)} />
    <div className="profile-library-grid">{profiles.filter(p => `${p.details.name} ${p.relationship}`.toLocaleLowerCase().includes(query.toLocaleLowerCase())).map(p => <article className="workspace-panel" key={p.id}><div className="profile-avatar">{p.details.name.slice(0, 1).toUpperCase()}</div><h3 className="mt-4">{p.details.name}</h3><p className="workspace-muted text-sm mt-1">{relationshipLabel(p.relationship)} · {p.details.date}</p><p className="workspace-muted text-xs mt-2">{p.details.time && p.details.time !== 'SUNRISE' ? p.details.time : "Birth time unknown"}{p.details.location ? ` · ${p.details.location}` : ''}</p><div className="grid grid-cols-2 gap-2 mt-5"><button className="workspace-secondary" disabled={busy} onClick={() => onPick(p.details, 'user')}>My chart</button><button className="workspace-secondary" disabled={busy} onClick={() => onPick(p.details, 'partner')}>Partner chart</button></div><div className="flex gap-4 mt-4 text-xs workspace-muted"><button disabled={busy} onClick={() => { setCategory(relationshipLabel(p.relationship)); setEditing(p); }}>Edit profile</button><button disabled={busy} onClick={() => { if (confirm(`Delete the saved profile for ${p.details.name}?`)) persist(profiles.filter(x => x.id !== p.id)); }}>Delete</button></div></article>)}</div>
    {!profiles.length && <div className="workspace-empty"><span><UsersRound size={32} aria-hidden="true" /></span><h3>Your circle starts here.</h3><p>Add your partner, family and friends. Then choose two people to compare.</p></div>}
  </div>;
}

