nt-size:9px;letter-spacing:.08em;line-height:1.5}.daily-day-name{font-size:11px;color:#c5becf;margin:20px 0 9px;text-transform:capitalize}.daily-lunar-copy h3{font-size:30px!important;font-weight:500!important;margin-bottom:15px}.daily-lunar-copy>p:last-of-type{font-size:13px;line-height:1.8;color:#d8d0df}.daily-lunar-art{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px}.daily-moon-disc{width:150px;max-width:100%;filter:drop-shadow(0 0 24px #ecd5b01c)}.daily-lunar-art>span{font-size:10px;color:#d0c6d5}.daily-lunar-bottom{border-top:1px solid #ffffff15;padding-top:17px;display:flex;gap:16px;justify-content:space-between;grid-column:1/-1;font-size:10px;color:#c6becf}.daily-lunar-bottom>span:first-child{color:#ebd4ac}.daily-text-button{display:inline-flex;align-items:center;gap:8px;color:var(--ws-accent);font-size:12px!important;text-align:left;line-height:1.7;padding:8px 0;border-bottom:1px solid transparent}.daily-text-button:hover{border-bottom-color:currentColor}.daily-lunar-copy .daily-text-button{color:#ecd4a9;margin-top:12px}.daily-guide-card{border:1px solid var(--ds-line);border-radius:24px;padding:28px;background:linear-gradient(135deg,#ac86d313,transparent 90%),var(--ws-card);display:flex;flex-direction:column;align-items:flex-start}.daily-guide-card>svg{color:var(--ds-lilac);margin:0 0 17px}.daily-guide-card h3{font-size:24px!important;line-height:1.3!important;max-width:230px;margin-bottom:13px}.daily-guide-card>p{color:var(--ws-muted);font-size:12px;line-height:1.9;margin:0 0 21px}.daily-action{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:44px;background:var(--ws-accent);color:var(--ws-bg);padding:12px 16px;border-radius:11px;font-size:12px!important;font-weight:600!important}.daily-action:hover{filter:brightness(1.08)}.daily-guide-card>small{color:var(--ws-muted);font-size:10px;line-height:1.7;margin-top:17px}.daily-week-strip{display:grid;grid-template-columns:repeat(7,minmax(0,1fr