anet-venus{fill:#e6a5bb;background:#e6a5bb}.planet-mars{fill:#df9c7a;background:#df9c7a}.planet-jupiter{fill:#d0b08a;background:#d0b08a}.planet-saturn{fill:#ccc195;background:#ccc195}.planet-uranus{fill:#8ec6c9;background:#8ec6c9}.planet-neptune{fill:#8ea5d6;background:#8ea5d6}.planet-pluto{fill:#b8a1bd;background:#b8a1bd}.daily-planet-list{display:flex;flex-direction:column;gap:3px}.daily-planet-list>button{display:flex;align-items:center;gap:12px;padding:11px;border-radius:12px;min-height:54px;border:1px solid transparent;text-align:left}.daily-planet-list>button:hover{background:var(--ds-soft)}.daily-planet-list>button[aria-pressed=true]{border-color:#bfa5e75c;background:#bfa5e70c}.daily-planet-dot{width:8px;height:8px;flex-shrink:0;border-radius:50%}.daily-planet-list strong{display:block;font-size:12px;font-weight:550}.daily-planet-list small{display:block;font-size:9px;color:var(--ws-muted);margin-top:4px;line-height:1.5}.daily-planet-list>button>span:last-child{margin-left:auto;font-size:11px;text-align:right}.daily-meaning-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.daily-meaning h4{font-size:12px;font-weight:600;margin:0 0 12px}.daily-meaning p{font-size:12px;line-height:1.9;color:var(--ws-muted)}.daily-meaning .daily-caption{font-size:10px}.daily-meaning .daily-reflection{color:var(--ws-text);font-size:19px;line-height:1.6;max-width:320px;margin-bottom:12px}.daily-meaning .daily-pill{color:var(--ws-accent);border-color:var(--ds-line);white-space:nowrap}.daily-personal-contacts{margin-top:25px;padding-top:25px;border-top:1px solid var(--ds-line)}.daily-contact-list{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px}.daily-contact-list>button{border:1px solid var(--ds-line);border-radius:12px;background:var(--ds-soft);padding:14px;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:12px}.daily-contact-list strong{font-size:11px;font-weight:550}.daily-contact-list small{display:block;font-size:10px;color:var(--ws-muted);line-height:1.7;margin-top:5px}.daily-contact-list svg{flex-shrink:0;color:var(--ws-accent)}.daily-method{color:var(--ws-muted);font-size:10px;line-height:1.9;border-top:1px solid var(--ds-line);padding-top:16px}.daily-method summary{cursor:pointer;color:var(--ws-accent);font-size:11px}.daily-method p{margin-top:12px;overflow-wrap:anywhere}.daily-notes{background:#c5aa6c0c;border:1px solid #c5aa6c25;border-radius:12px;padding:13px 16px;color:var(--ws-muted);font-size:11px;line-height:1.8}.daily-status{padding:70px 25px;border:1px solid var(--ds-line);border-radius:22px;text-align:center;background:var(--ws-card);min-height:280px;display:flex;flex-direction:column;align-items:center;gap:15px}.daily-status>svg{color:var(--ws-accent)}.daily-status h3{font-size:22px!important}.daily-status p{color:var(--ws-muted);font-size:12px;line-height:1.8}.daily-loading{animation:daily-turn 8s linear infinite}.daily-month-controls{display:flex;gap:4px}.daily-weekdays,.daily-month-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.daily-weekdays>span{text-align:center;padding:10px 0;font-size:10px;color:var(--ws-muted)}.daily-month-days>button{border:1px solid var(--ds-line);border-radius:12px;min-height:94px;padding:10px 4px;display:flex;flex-direction:column;align-items:center;gap:5px;min-width:0}.daily-month-days>button>span{font-size:12px}.daily-month-days>button small{font-size:8px;line-height:1.5;color:var(--ws-muted);text-align:center}.daily-month-days>button.is-today>span{text-decoration:underline;text-underline-offset:4px;color:var(--ws-accent)}.daily-month-days>button[aria-pressed=true]{background:#bfa5e71a;border-color:#bfa5e77a}.daily-moon-mini{width:25px;height:25px}.daily-month-days>button:hover{background:var(--ds-soft)}
.astro-workspace[data-theme=light] .daily-sky{--ds-line:#30283e1c;--ds-soft:#74608b06;--ds-lilac:#72549c;--ds-warm:#7a5b25}.astro-workspace[data-theme=light] .daily-datebar input{color-scheme:light}.astro-workspace[data-theme=light] .daily-guide-card{background:linear-gradient(140deg,#e8ddf330,#fff 90%)}.astro-workspace[data-theme=light] .daily-engine>span{background:#46744a}.astro-workspace[data-theme=light] .daily-meaning .daily-pill{background:#71608608}
