const pointThemes: Record<string, { theme: string; practice: string }> = {
 sun:{theme:'identity, vitality and personal direction',practice:'a choice that expresses your values'},
 moon:{theme:'emotional needs, care and security',practice:'a need for emotional support'},
 mercury:{theme:'thought, learning and communication',practice:'a clear way of communicating what you think'},
 venus:{theme:'affection, pleasure and relationship values',practice:'an agreement about affection and reciprocity'},
 mars:{theme:'initiative, desire and assertiveness',practice:'a direct request or initiative'},
 jupiter:{theme:'confidence, expansion and meaning',practice:'an opportunity to learn'},
 saturn:{theme:'limits, responsibility and consistency',practice:'a boundary or commitment you can sustain'},
 uranus:{theme:'autonomy, experimentation and change',practice:'a desire for change that respects your autonomy'},
 neptune:{theme:'imagination, sensitivity and ideals',practice:'an inspiration that needs form and boundaries'},
 pluto:{theme:'depth, transformation and power',practice:'a pattern of control that could be reconsidered'},
 ascendant:{theme:'presence and how you begin encounters',practice:'how you present yourself in a new situation'},
 midheaven:{theme:'public direction, vocation and contribution',practice:'a contribution you want to develop over time'},
};
const pairQuestions:Record<string,string>={
 'sun:moon':'Does what you want to express fit the care you need? Name a personal choice and an emotional need, making room for both.',
 'sun:saturn':'Which commitment supports your chosen direction, and when does pressure replace that choice? Define a realistic responsibility and a limit to self-criticism.',
 'sun:ascendant':'Does the way you begin an encounter reveal what matters to you? Try expressing a preference clearly without needing a perfect first impression.',
 'sun:midheaven':'What public contribution fits your personal values? Distinguish a goal you chose from an outside expectation of recognition.',
 'moon:mercury':'How can you put an emotional need into understandable words? Name the feeling, the need and a request without assuming someone already understands.',
 'moon:venus':'Does the affection you offer also make room for the care you need? Discuss an affectionate gesture that matters to each person.',
 'moon:mars':'How can you express discomfort or desire while respecting your need for security? Pause and turn a reaction into a clear request.',
 'moon:saturn':'Which boundaries provide security, and which make care harder to receive? Choose a realistic commitment and a concrete way to ask for support.',
 'mercury:venus':'Does how you communicate preferences leave room to hear someone else’s? Make a kind request without hiding an important boundary.',
 'mercury:mars':'When does a quick reply help you be direct, and when does it prevent listening? Confirm what someone means before defending an idea.',
 'mercury:saturn':'How can you organize an idea carefully without demanding perfection? Review an important point and allow a question or correction.',
 'venus:mars':'How can you connect what you appreciate with what you want to do? State interest and boundaries while allowing consent, reciprocity and different paces.',
