const norm = (n: number) => (n % 360 + 360) % 360;

/** Spread labels only; actual longitudes remain unchanged and get visible anchors. */
export function layoutPlanetMarkers<T extends { id: string; lon: number }>(points: T[], minimumGap = 17): Array<T & { displayLon: number }> {
  if (!Number.isFinite(minimumGap) || minimumGap <= 0 || points.length * minimumGap >= 360 || points.some(p => !Number.isFinite(p.lon))) throw new Error('Invalid chart marker layout.');
  if (points.length < 2) return points.map(p => ({ ...p, displayLon: norm(p.lon) }));
  const ordered = [...points].sort((a, b) => norm(a.lon) - norm(b.lon) || a.id.localeCompare(b.id));
  let best: { cost: number; positions: Map<string, number> } | undefined;
  for (let start = 0; start < ordered.length; start++) {
    const list = [...ordered.slice(start), ...ordered.slice(0, start)];
    const raw = list.map((p, i) => norm(p.lon) + (start + i >= ordered.length ? 360 : 0));
    // Isotonic least squares on longitude minus the required marker spacing.
    const blocks: Array<{ sum: number; count: number; from: number }> = [];
    raw.forEach((lon, i) => {
      blocks.push({ sum: lon - i * minimumGap, count: 1, from: i });
      while (blocks.length > 1) {
        const a = blocks[blocks.length - 2], b = blocks[blocks.length - 1];
        if (a.sum / a.count <= b.sum / b.count) break;
        blocks.splice(-2, 2, { sum: a.sum + b.sum, count: a.count + b.count, from: a.from });
      }
    });
    const fitted = raw.slice();
    for (const block of blocks) for (let i = block.from; i < block.from + block.count; i++) fitted[i] = block.sum / block.count + i * minimumGap;
    if (fitted.at(-1)! - fitted[0] > 360 - minimumGap + 1e-9) continue;
    const cost = fitted.reduce((sum, lon, i) => sum + (lon - raw[i]) ** 2, 0);
    if (!best || cost < best.cost - 1e-9) best = { cost, positions: new Map(list.map((p, i) => [p.id, norm(fitted[i])])) };
  }
  if (!best) throw new Error('Unable to lay out chart markers.');
  return points.map(p => ({ ...p, displayLon: best!.positions.get(p.id)! }));
}

export function formatSignDegree(longitude: number): string {
  // Round to the nearest displayed minute, keeping the calculated sign at its
  // boundary. Tables retain the unrounded longitude for precision checks.
  const minutes = Math.min(1799, Math.round((norm(longitude) % 30) * 60));
  return `${Math.floor(minutes / 60)}°${String(minutes % 60).padStart(2, '0')}′`;
}

