export const MOOD_LOG_KEY = 'astrolove_mood_log_v1';
export const MOOD_LOG_EVENT = 'astrolove:mood-log-change';
export const MOOD_TAGS = ['calm', 'focused', 'scattered', 'irritable', 'anxious', 'social', 'tired', 'creative', 'talkative', 'foggy'] as const;
export type MoodTag = typeof MOOD_TAGS[number];
export const LOG_BODY_IDS = ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'uranus', 'neptune', 'pluto'] as const;
export interface MoodContext { phase: number; featuredPlanetId: string; motion: 'direct' | 'retrograde'; at: string; timeZone: string }
export interface MoodEntry { personId: string; date: string; mood: number; energy: number; tags: MoodTag[]; note: string; createdAt: string; updatedAt: string; context: MoodContext | null }
export type MoodInput = Pick<MoodEntry, 'personId' | 'date' | 'mood' | 'energy' | 'tags' | 'note'> & { context?: MoodContext | null };
export interface LogStorage { getItem(key: string): string | null; setItem(key: string, value: string): void }
export interface MoodPattern { kind: 'phase' | 'motion'; key: string; n: number; averageMood: number; averageEnergy: number; label: 'Your own log, not proof' }
const validDate = (value: unknown): value is string => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(`${value}T12:00:00Z`)) && new Date(`${value}T12:00:00Z`).toISOString().slice(0, 10) === value;
const validStamp = (value: unknown): value is string => typeof value === 'string' && Number.isFinite(Date.parse(value)) && new Date(value).toISOString() === value;
function store(storage?: LogStorage): LogStorage { if (storage) return storage; if (typeof localStorage === 'undefined') throw new Error('Local storage is unavailable.'); return localStorage; }
function contextValid(context: unknown): context is MoodContext {
  if (!context || typeof context !== 'object') return false;
  const c = context as MoodContext;
  if (!Number.isInteger(c.phase) || c.phase < 1 || c.phase > 8 || !LOG_BODY_IDS.includes(c.featuredPlanetId as typeof LOG_BODY_IDS[number]) || !['direct', 'retrograde'].includes(c.motion) || !validStamp(c.at) || typeof c.timeZone !== 'string') return false;
  try { new Intl.DateTimeFormat('en', { timeZone: c.timeZone }); return true; } catch { return false; }
}
function validateEntry(entry: unknown): asserts entry is MoodEntry {
  const e = entry as MoodEntry;
  if (!e || typeof e !== 'object' || typeof e.personId !== 'string' || !e.personId.trim() || e.personId.length > 200 || !validDate(e.date)
    || !Number.isInteger(e.mood) || e.mood < 1 || e.mood > 5 || !Number.isInteger(e.energy) || e.energy < 1 || e.energy > 5
    || !Array.isArray(e.tags) || e.tags.length > MOOD_TAGS.length || new Set(e.tags).size !== e.tags.length || !e.tags.every(t => MOOD_TAGS.includes(t))
    || typeof e.note !== 'string' || Array.from(e.note).length > 280 || !validStamp(e.createdAt) || !validStamp(e.updatedAt) || e.updatedAt < e.createdAt
    || !(e.context === null || contextValid(e.context))) throw new Error('Invalid entry: check the date, notes, 1–5 ratings and calculated context.');
  if (e.context) {
    const parts = new Intl.DateTimeFormat('en-CA', { timeZone: e.context.timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(e.context.at));
    const snapshotDate = ['year', 'month', 'day'].map(k => parts.find(p => p.type === k)?.value).join('-');
    if (snapshotDate !== e.date) throw new Error('The calculated context does not match the entry’s local date.');
  }
}
function sorted(entries: MoodEntry[]) { return [...entries].sort((a, b) => a.personId.localeCompare(b.personId) || a.date.localeCompare(b.date)); }
export function parseMoodLog(json: string): MoodEntry[] {
  let value: { schemaVersion?: unknown; entries?: unknown };
  try { value = JSON.parse(json); } catch { throw new Error('The file does not contain valid JSON.'); }
  if (!value || value.schemaVersion !== 1 || !Array.isArray(value.entries) || value.entries.length > 100000) throw new Error('Unrecognized journal format.');
  const seen = new Set<string>();
  for (const entry of value.entries) { validateEntry(entry); const id = JSON.stringify([entry.personId, entry.date]); if (seen.has(id)) throw new Error('Duplicate entries exist for the same person and date.'); seen.add(id); }
  return sorted(value.entries);
}
export function readMoodLog(storage?: LogStorage): MoodEntry[] { const raw = store(storage).getItem(MOOD_LOG_KEY); return raw ? parseMoodLog(raw) : []; }
function write(entries: MoodEntry[], storage?: LogStorage) { const json = JSON.stringify({ schemaVersion: 1, entries: sorted(entries) }, null, 2); store(storage).setItem(MOOD_LOG_KEY, json); if (typeof window !== 'undefined') window.dispatchEvent(new Event(MOOD_LOG_EVENT)); }
export function saveMoodEntry(input: MoodInput, storage?: LogStorage, now = new Date().toISOString()): MoodEntry {
  const entries = readMoodLog(storage), previous = entries.find(e => e.personId === input.personId && e.date === input.date);
  const entry: MoodEntry = { ...input, tags: [...input.tags], createdAt: previous?.createdAt || now, updatedAt: now, context: input.context === undefined ? previous?.context || null : input.context };
  validateEntry(entry);
  write([...entries.filter(e => e.personId !== input.personId || e.date !== input.date), entry], storage);
  return entry;
}
export function deleteMoodEntry(personId: string, date: string, storage?: LogStorage): void { write(readMoodLog(storage).filter(e => e.personId !== personId || e.date !== date), storage); }
export function exportMoodLog(storage?: LogStorage): string { return JSON.stringify({ schemaVersion: 1, entries: readMoodLog(storage) }, null, 2); }
/** Explicit replacement: validate every entry before touching existing storage. */
export function importMoodLog(json: string, storage?: LogStorage): MoodEntry[] { const entries = parseMoodLog(json); write(entries, storage); return entries; }
/** Descriptive means only. Missing context is excluded; selected-person logs never mix. */
export function computeMoodPatterns(entries: MoodEntry[], personId: string, featuredPlanetId: string): MoodPattern[] {
  const person = entries.filter(e => e.personId === personId && e.context), buckets: Array<{ kind: 'phase' | 'motion'; key: string; entries: MoodEntry[] }> = [];
  for (let phase = 1; phase <= 8; phase++) buckets.push({ kind: 'phase', key: String(phase), entries: person.filter(e => e.context?.phase === phase) });
  for (const motion of ['direct', 'retrograde']) buckets.push({ kind: 'motion', key: motion, entries: person.filter(e => e.context?.featuredPlanetId === featuredPlanetId && e.context?.motion === motion) });
  return buckets.filter(b => b.entries.length >= 10).map(b => ({ kind: b.kind, key: b.key, n: b.entries.length, averageMood: b.entries.reduce((sum, e) => sum + e.mood, 0) / b.entries.length, averageEnergy: b.entries.reduce((sum, e) => sum + e.energy, 0) / b.entries.length, label: 'Your own log, not proof' }));
}

