export const BODY_IDS = ['sun','moon','mercury','venus','mars','jupiter','saturn','uranus','neptune','pluto'] as const;
export type BodyId = typeof BODY_IDS[number];
export interface SelectionState {
  selectedPersonId: string;
  selectedDate: string;
  selectedBody: BodyId | null;
  selectedAspectId: string | null;
  selectedEventId: string | null;
  selectedPhase: number | null;
}
export type SelectionAction =
 | { type:'person'; id:string } | { type:'date'; date:string }
 | { type:'body'; id:BodyId|null } | { type:'aspect'; id:string|null }
 | { type:'event'; id:string|null; body?:BodyId; date?:string }
 | { type:'phase'; phase:number|null };
export function civilDate(at:Date,timeZone:string):string {
 const p=new Intl.DateTimeFormat('en',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(at);
 return ['year','month','day'].map(t=>p.find(v=>v.type===t)!.value).join('-');
}
export function initialSelection(personId:string,timeZone:string,now=new Date()):SelectionState {
 return {selectedPersonId:personId,selectedDate:civilDate(now,timeZone),selectedBody:null,selectedAspectId:null,selectedEventId:null,selectedPhase:null};
}
export function selectionReducer(state:SelectionState,action:SelectionAction):SelectionState {
 switch(action.type){
 case 'person': return action.id===state.selectedPersonId?state:{...state,selectedPersonId:action.id,selectedBody:null,selectedAspectId:null,selectedEventId:null,selectedPhase:null};
 case 'date': {const d=new Date(`${action.date}T12:00:00Z`);if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==action.date||action.date<'1200-01-01'||action.date>'2399-12-31')return state;return action.date===state.selectedDate?state:{...state,selectedDate:action.date,selectedPhase:null,selectedAspectId:null,selectedEventId:null};}
 case 'body': return {...state,selectedBody:action.id,selectedPhase:null,selectedAspectId:null,selectedEventId:null};
 case 'aspect':return {...state,selectedAspectId:action.id,selectedPhase:null,selectedEventId:null};
 case 'event':return {...state,selectedEventId:action.id,selectedPhase:null,selectedBody:action.body??state.selectedBody,selectedDate:action.date??state.selectedDate,selectedAspectId:null};
 case 'phase':return {...state,selectedPhase:action.phase,selectedBody:null,selectedEventId:null,selectedAspectId:null};
 }
}

