import { useEffect, useRef, useState } from 'react';
import { fetchDailySky, type DailySkyRequest, type DailySkyResponse } from './daily-sky';

export function useDailySky(request: DailySkyRequest) {
  const key = JSON.stringify(request);
  const cache = useRef(new Map<string, DailySkyResponse>());
  const [response, setResponse] = useState<{key: string; data: DailySkyResponse} | null>(null);
  const [failure, setFailure] = useState<{key: string; message: string} | null>(null);
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    if (cache.current.has(key)) return;
    const controller = new AbortController();
    let active = true;
    const timer = setTimeout(() => controller.abort(), 45000);
    setFailure(null);
    fetchDailySky(JSON.parse(key), controller.signal).then(data => {
      if (!active) return;
      if (cache.current.size >= 12) cache.current.delete(cache.current.keys().next().value!);
      cache.current.set(key, data);
      setResponse({key, data});
    }).catch(error => {
      if (active) setFailure({key, message: controller.signal.aborted ? 'The daily calculation timed out. Try again.' : error instanceof Error ? error.message : 'Could not calculate this day.'});
    }).finally(() => clearTimeout(timer));
    return () => { active = false; clearTimeout(timer); controller.abort(); };
  }, [key, attempt]);
  return {
    data: cache.current.get(key) ?? (response?.key === key ? response.data : null),
    error: failure?.key === key ? failure.message : null,
    retry: () => { cache.current.delete(key); setResponse(null); setFailure(null); setAttempt(n => n+1); },
  };
}

