import type { BirthDetails, Interpretation } from '../types';
import type { ChartSettings } from './chart-settings';

export interface ComputedChart {
  metadata?: { engine: string; zodiac: string; houseSystem: string; settings?: ChartSettings; timeKnown: boolean; utc: string; warnings: string[] };
  planets: Array<{ id: string; symbol: string; name: string; lon: number; sign: string; signSymbol: string; degree: number; house: number; retrograde: boolean }>;
  houses: Array<{ number: number; cuspLon: number; sign: string; signSymbol: string; degree: number }> | null;
  ascendant: number | null;
  midheaven: number | null;
  bigThree: { sol: string; lua: string; ascendente: string | null };
  aspects: Array<{ a: string; b: string; type: string; angle: number; orb: number; strength: string; vibe: string; weight: number }>;
}

export interface ComputedSynastry {
  user: ComputedChart;
  partner: ComputedChart;
  crossAspects: Array<{ a: string; b: string; type: string; angle: number; orb: number; strength: string; vibe: string; weight: number; from: string; to: string }>;
  compatibility: {
    overall: number;
    emocional: number;
    sexual: number;
    intelectual: number;
    karmica: number;
    attentionDimension: string;
    breakdown: Array<{ label: string; value: number; reason: string }>;
  };
  composite: {
    planets: ComputedChart['planets'];
    houses: ComputedChart['houses'];
    ascendant: number | null;
    midheaven: number | null;
  };
  houseOverlay: {
    partnerInUser: Array<{ planetId: string; planetSymbol: string; planetName: string; house: number; sign: string }>;
    userInPartner: Array<{ planetId: string; planetSymbol: string; planetName: string; house: number; sign: string }>;
  };
}

export interface TransitsToday {
  date: string;
  utc?: string;
  engine?: string;
  hits?: TransitsToday['topHits'];
  mood: 'harmônico' | 'intenso' | 'misto' | 'calmo';
  transitPlanets: Array<{ id: string; symbol: string; name: string; sign: string; signSymbol: string; degree: number }>;
  topHits: Array<{
    transitPlanet: string;
    transitSymbol: string;
    transitSign: string;
    natalPlanet: string;
    natalTarget: 'user' | 'partner';
    type: string;
    angle: number;
    orb: number;
    vibe: string;
    weight: number;
  }>;
}

export type ChartPayload = ComputedChart | ComputedSynastry;

export function natalTransitPoints(chart: ComputedChart): Array<{ id: string; lon: number }> {
  return [
    ...chart.planets.filter(p => chart.metadata?.timeKnown || p.id !== 'moon').map(p => ({ id: p.id, lon: p.lon })),
    ...(chart.metadata?.timeKnown && chart.ascendant != null ? [{ id: 'ascendant', lon: chart.ascendant }] : []),
    ...(chart.metadata?.timeKnown && chart.midheaven != null ? [{ id: 'midheaven', lon: chart.midheaven }] : []),
  ];
}

// Call the server-side real ephemeris computation.
export async function computeChart(mode: 'chart' | 'compatibility', user: BirthDetails, partner?: BirthDetails, settings?: ChartSettings, signal?: AbortSignal): Promise<ChartPayload> {
  const res = await fetch('/api/compute-chart', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ mode, user, partner, settings }),
    signal,
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `compute-chart HTTP ${res.status}`);
  }
  return res.json();
}

export async function loadTransits(userPlanets: Array<{ id: string; lon: number }>, partnerPlanets?: Array<{ id: string; lon: number }>, at?: string): Promise<TransitsToday> {
  const res = await fetch('/api/transits-today', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      user: { planets: userPlanets.map((p) => ({ id: p.id, lon: p.lon })) },
      partner: partnerPlanets ? { planets: partnerPlanets.map((p) => ({ id: p.id, lon: p.lon })) } : undefined,
      at,
    }),
  });
  if (!res.ok) { const error = await res.json().catch(() => ({})); throw new Error(error.message || `transits HTTP ${res.status}`); }
  return res.json();
}

export async function interpretChart(mode: 'chart' | 'compatibility', user: BirthDetails, chart: ChartPayload, partner?: BirthDetails): Promise<Interpretation> {
  const res = await fetch('/api/llm-chart', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ mode, user, partner, chart }),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `llm-chart HTTP ${res.status}`);
  }
  return res.json();
}

