import type { ComputedChart } from './astro';

export const bodyIds = ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'uranus', 'neptune', 'pluto'] as const;
export type BodyId = typeof bodyIds[number];
/** Traditional domiciles, Aries through Pisces; this is the Sun-sign ruler, not the chart ruler. */
export const traditionalRulers: readonly BodyId[] = ['mars', 'venus', 'mercury', 'moon', 'sun', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'saturn', 'jupiter'];
export function featuredPlanetForChart(chart: Pick<ComputedChart, 'planets' | 'metadata'>, override?: BodyId, confirmedSunSignIndex?: number): { bodyId: BodyId; sunSignIndex: number; uncertainSunSign: boolean } {
  const sun = chart.planets.find(planet => planet.id === 'sun');
  if (!sun || !Number.isFinite(sun.lon) || sun.lon < 0 || sun.lon >= 360) throw new Error('Natal Sun is unavailable.');
  if (override !== undefined && !bodyIds.includes(override)) throw new Error('Invalid featured planet.');
  if (confirmedSunSignIndex !== undefined && (!Number.isInteger(confirmedSunSignIndex) || confirmedSunSignIndex < 0 || confirmedSunSignIndex > 11)) throw new Error('Invalid confirmed Sun sign.');
  const degree = sun.lon % 30;
  const uncertainSunSign = !chart.metadata?.timeKnown && (degree <= 1 || degree >= 29) && confirmedSunSignIndex === undefined;
  const sunSignIndex = confirmedSunSignIndex ?? Math.floor(sun.lon / 30);
  return { bodyId: override ?? traditionalRulers[sunSignIndex], sunSignIndex, uncertainSunSign };
}

