import type { BirthDetails } from '../types';
import type { ChartSettings } from './chart-settings';
import type { ChartPayload } from './astro';

export interface SavedChart {
  id: string; mode: 'chart' | 'compatibility'; user: BirthDetails; partner?: BirthDetails;
  isPaid: boolean; createdAt?: number; settings?: ChartSettings;
  // Standalone input remains in user for backward-compatible recalculation.
  standaloneSlot?: 'user' | 'partner';
}
function birth(value: unknown): value is BirthDetails {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const p = value as Record<string, unknown>;
  if (!['name', 'date', 'time', 'location'].every(k => typeof p[k] === 'string')) return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(p.date as string)) return false;
  const day = new Date(`${p.date}T00:00:00Z`);
  if (!Number.isFinite(day.getTime()) || day.toISOString().slice(0, 10) !== p.date || (p.date as string) < '1200-01-01' || (p.date as string) > '2399-12-31') return false;
  if (p.time !== '' && p.time !== 'SUNRISE' && !/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(p.time as string)) return false;
  for (const [key, maximum] of [['lat', 90], ['lon', 180]] as const) if (p[key] !== undefined && (typeof p[key] !== 'number' || !Number.isFinite(p[key]) || Math.abs(p[key] as number) > maximum)) return false;
  return p.timezone === undefined || typeof p.timezone === 'string';
}
export function parseSavedChart(value: unknown): SavedChart | null {
  try {
    if (typeof value === 'string') { if (value.length > 100000) return null; value = JSON.parse(value); }
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    const c = value as Record<string, unknown>;
    if (typeof c.id !== 'string' || !c.id || c.id.length > 256 || !['chart', 'compatibility'].includes(c.mode as string) || !birth(c.user) || c.mode === 'compatibility' && !birth(c.partner)) return null;
    if (c.partner !== undefined && !birth(c.partner)) return null;
    if (c.standaloneSlot !== undefined && !['user', 'partner'].includes(c.standaloneSlot as string)) return null;
    return { ...c, isPaid: c.isPaid === true } as SavedChart;
  } catch { return null; }
}

/** Map the canonical standalone owner back to its UI slot without relabeling. */
export function restoreSavedProfiles(saved: SavedChart) {
  const blank: BirthDetails = { name: '', date: '', time: '', location: '' };
  const initialSlot = saved.mode === 'chart' && saved.standaloneSlot === 'partner' ? 'partner' : 'user';
  return { initialSlot, user: initialSlot === 'partner' ? blank : saved.user, partner: initialSlot === 'partner' ? saved.user : saved.partner || blank } as const;
}

export function createWorkspaceSavedChart(user: BirthDetails, partner: BirthDetails, chart: ChartPayload, standaloneSlot: 'user' | 'partner', isPaid: boolean): SavedChart {
  if ('user' in chart) return { id: 'last', mode: 'compatibility', user, partner, settings: chart.user.metadata?.settings, isPaid };
  return { id: 'last', mode: 'chart', user: standaloneSlot === 'partner' ? partner : user, standaloneSlot, settings: chart.metadata?.settings, isPaid };
}

