import type { BirthDetails } from '../types';
import type { ChartSettings } from './chart-settings';
import type { BodyId } from './featured-planet';
import type { LunationPhase, PhaseNumber } from './phase-cycle';

export interface DailySkyRequest {
  date: string;
  timeZone: string;
  birth?: BirthDetails;
  settings?: ChartSettings;
  featuredPlanet?: BodyId;
}
export interface DailyMoon extends LunationPhase {
  /** Separate physical result from Swiss pheno_ut; UI default uses the PDF elongation formula. */
  physicalIllumination: number;
  phaseStart: string | null;
  phaseEnd: string | null;
  dayOfPhase: number | null;
  nextPrincipalEvent: PlanetCycleEvent | null;
}
export interface DailyPlanet {
  id: string; name: string; lon: number; sign: string; degree: number; retrograde: boolean; speed: number;
}
export interface DailyContact {
  transitPlanet: string; natalPlanet: string; type: string; angle: number; orb: number;
  applying: boolean;
  motion: 'applying' | 'separating';
}
export interface PlanetCycleEvent {
  id: string;
  bodyId: BodyId;
  kind: 'station' | 'ingress' | 'conjunction' | 'lunation' | 'exact-aspect';
  at: string;
  longitude: number;
  direction?: 'direct' | 'retrograde';
  signIndex?: number;
  sign?: string;
  conjunctionType?: 'inferior' | 'superior';
  phaseNumber?: PhaseNumber;
  phaseName?: string;
  natalPlanet?: string;
  angle?: number;
  pass?: number;
  residualDegrees?: number;
  precisionSeconds: number;
}
export interface PlanetCycle {
  bodyId: BodyId;
  status: 'Direct' | 'Retrograde';
  nextEvent: PlanetCycleEvent | null;
}
export type DailyCalendarDay = DailyMoon & { date: string; events: PlanetCycleEvent[]; featuredRetrograde: boolean };
export interface DailySkyResponse {
  date: string;
  timeZone: string;
  /** Explicit overview sampling instant: noon in the selected civil timezone. */
  at: string;
  engine: 'swiss-ephemeris';
  moon: DailyMoon;
  planets: DailyPlanet[];
  contacts: DailyContact[];
  topContacts: DailyContact[];
  featuredPlanetId?: BodyId;
  planetEvents: PlanetCycleEvent[];
  planetCycles: PlanetCycle[];
  month: DailyCalendarDay[];
  fourteenDayStrip: DailyCalendarDay[];
  warnings: string[];
}

export async function fetchDailySky(body: DailySkyRequest, signal?: AbortSignal): Promise<DailySkyResponse> {
  const response = await fetch('/api/daily-sky', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), signal,
  });
  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(error.message || `daily-sky HTTP ${response.status}`);
  }
  const value: unknown = await response.json();
  if (!isDailySky(value, body)) throw new Error('The calculation returned incomplete data. Try again.');
  return value;
}

// Check the API boundary before its payload reaches date formatters, SVG geometry, or chart rows.
function isDailySky(value: unknown, request: DailySkyRequest): value is DailySkyResponse {
  if (!value || typeof value !== 'object') return false;
  const v = value as DailySkyResponse;
  const ids = ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'uranus', 'neptune', 'pluto'];
  const instant = (at: unknown) => typeof at === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(at) && Number.isFinite(Date.parse(at));
  const event = (e: PlanetCycleEvent) => Boolean(e && typeof e.id === 'string' && ids.includes(e.bodyId)
    && ['station', 'ingress', 'conjunction', 'lunation', 'exact-aspect'].includes(e.kind) && instant(e.at)
    && Number.isFinite(e.longitude) && e.longitude >= 0 && e.longitude < 360 && Number.isFinite(e.precisionSeconds) && e.precisionSeconds > 0 && e.precisionSeconds <= 120
    && (e.kind !== 'station' || ['direct', 'retrograde'].includes(e.direction || ''))
    && (e.kind !== 'ingress' || (Number.isInteger(e.signIndex) && e.signIndex! >= 0 && e.signIndex! < 12 && typeof e.sign === 'string'))
    && (e.kind !== 'conjunction' || (e.bodyId === 'mercury' && ['inferior', 'superior'].includes(e.conjunctionType || '')))
    && (e.kind !== 'lunation' || (e.bodyId === 'moon' && Number.isInteger(e.phaseNumber) && e.phaseNumber! >= 1 && e.phaseNumber! <= 8))
    && (e.kind !== 'exact-aspect' || (ids.includes(e.natalPlanet || '') && [0, 60, 90, 120, 180].includes(e.angle!) && Number.isInteger(e.pass) && e.pass! > 0)));
  const moon = (m: DailyMoon) => Boolean(m && typeof m.phaseName === 'string' && typeof m.phaseNameEn === 'string'
    && Number.isFinite(m.phaseAngle) && m.phaseAngle >= 0 && m.phaseAngle < 360 && m.phaseNumber === Math.floor(m.phaseAngle / 45) + 1
    && Number.isFinite(m.illumination) && m.illumination >= 0 && m.illumination <= 1
    && Number.isFinite(m.illuminationPercent) && Math.abs(m.illuminationPercent - m.illumination * 100) < 1e-8
    && Number.isFinite(m.physicalIllumination) && m.physicalIllumination >= 0 && m.physicalIllumination <= 1 && typeof m.waxing === 'boolean'
    && (m.phaseStart === null || instant(m.phaseStart)) && (m.phaseEnd === null || instant(m.phaseEnd))
    && (m.dayOfPhase === null || (Number.isInteger(m.dayOfPhase) && m.dayOfPhase >= 1 && m.dayOfPhase <= 8))
    && (m.nextPrincipalEvent === null || (event(m.nextPrincipalEvent) && m.nextPrincipalEvent.kind === 'lunation' && [1, 3, 5, 7].includes(m.nextPrincipalEvent.phaseNumber!))));
  const contact = (c: DailyContact) => Boolean(c && ids.includes(c.transitPlanet) && ids.includes(c.natalPlanet) && typeof c.type === 'string'
    && [0, 60, 90, 120, 180].includes(c.angle) && Number.isFinite(c.orb) && c.orb >= 0 && c.orb <= 12
    && typeof c.applying === 'boolean' && c.motion === (c.applying ? 'applying' : 'separating'));
  const day = (d: DailyCalendarDay) => {
    if (!d || typeof d.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(d.date)) return false;
    const at = new Date(`${d.date}T12:00:00Z`);
    return Number.isFinite(at.getTime()) && at.toISOString().slice(0, 10) === d.date && moon(d) && typeof d.featuredRetrograde === 'boolean' && Array.isArray(d.events) && d.events.every(event);
  };
  return v.engine === 'swiss-ephemeris' && v.date === request.date && v.timeZone === request.timeZone && instant(v.at) && moon(v.moon)
    && Array.isArray(v.planets) && v.planets.length === 10 && new Set(v.planets.map(p => p?.id)).size === 10
    && v.planets.every(p => p && ids.includes(p.id) && typeof p.name === 'string' && typeof p.sign === 'string' && Number.isFinite(p.lon) && p.lon >= 0 && p.lon < 360 && Number.isFinite(p.degree) && p.degree >= 0 && p.degree < 30 && Number.isFinite(p.speed) && p.retrograde === (p.speed < 0))
    && Array.isArray(v.month) && v.month.length > 0 && v.month.length <= 31 && new Set(v.month.map(d => d?.date)).size === v.month.length
    && v.month.some(d => d?.date === request.date) && v.month.every(d => day(d) && d.date.slice(0, 7) === request.date.slice(0, 7))
    && Array.isArray(v.fourteenDayStrip) && v.fourteenDayStrip.length > 0 && v.fourteenDayStrip.length <= 14 && v.fourteenDayStrip[0]?.date === request.date
    && new Set(v.fourteenDayStrip.map(d => d?.date)).size === v.fourteenDayStrip.length && v.fourteenDayStrip.every(day)
    && Array.isArray(v.contacts) && v.contacts.every(contact)
    && Array.isArray(v.topContacts) && v.topContacts.length <= 3 && v.topContacts.every(c => contact(c) && v.contacts.some(other => other.transitPlanet === c.transitPlanet && other.natalPlanet === c.natalPlanet && other.angle === c.angle && other.orb === c.orb))
    && (v.featuredPlanetId === undefined || ids.includes(v.featuredPlanetId)) && (request.featuredPlanet === undefined || v.featuredPlanetId === request.featuredPlanet)
    && Array.isArray(v.planetEvents) && v.planetEvents.every(event)
    && Array.isArray(v.planetCycles) && v.planetCycles.length === 10 && new Set(v.planetCycles.map(c => c?.bodyId)).size === 10
    && v.planetCycles.every(c => c && ids.includes(c.bodyId) && ['Direct', 'Retrograde'].includes(c.status) && (c.nextEvent === null || (event(c.nextEvent) && c.nextEvent.bodyId === c.bodyId && Date.parse(c.nextEvent.at) > Date.parse(v.at))))
    && Array.isArray(v.warnings) && v.warnings.every(w => typeof w === 'string');
}

src/lib/location.ts:
export interface GeoResult {
  id?: string;
  display: string;
  lat: number;
  lon: number;
  country: string;
  timezone?: string;
  source?: string;
  license?: string;
}

export async function searchCities(q: string, signal?: AbortSignal): Promise<GeoResult[]> {
  if (q.trim().length < 2) return [];
  const response = await fetch('/api/locations', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ query: q }), signal });
  const data = await response.json();
  if (!response.ok) throw new Error(data.message || 'City search is unavailable.');
  if (!Array.isArray(data.cities) || data.cities.some((city: GeoResult) => typeof city.display !== 'string' || typeof city.country !== 'string' || !Number.isFinite(city.lat) || Math.abs(city.lat) > 90 || !Number.isFinite(city.lon) || Math.abs(city.lon) > 180 || (city.timezone !== undefined && typeof city.timezone !== 'string'))) throw new Error('City search did not return valid coordinates. Enter them manually.');
  return data.cities;
}

