import { parseSavedChart, type SavedChart } from './saved-chart';
const LS_KEY = 'astrolove_last_chart';

export function saveChartLocal(chart: SavedChart) {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify({ ...chart, createdAt: Date.now() }));
    return true;
  } catch { return false; }
}

export function loadChartLocal(): SavedChart | null {
  try {
    const raw = localStorage.getItem(LS_KEY);
    return raw ? parseSavedChart(raw) : null;
  } catch {
    return null;
  }
}

export function clearChartLocal() {
  try {
    localStorage.removeItem(LS_KEY);
  } catch {}
}

