export interface InterpretationSection { title: string; text: string }
export interface PlanetInterpretationReading { status:'ready'|'uncertain'|'unavailable';title:string;subtitle?:string;sections:InterpretationSection[];notes:string[];aspectCount:number;placement?:PlacementFilter;discoveryLabel?:string }
export function describePlanet(chart:ComputedChart,pointId:string):PlanetInterpretationReading {
 const definition=points[pointId];
 const unavailable=(title:string,message:string):PlanetInterpretationReading=>({status:'unavailable',title,sections:[],notes:[message],aspectCount:0});
 if(!definition)return unavailable('Point unavailable','No interpretation is available for this point. Select a calculated chart point.');
 const known=chart.metadata?.timeKnown===true,angle=pointId==='ascendant'||pointId==='midheaven';
 if(angle&&!known)return unavailable(definition.name,'Confirmed time, place and timezone are required to calculate and interpret this angle.');
 const planet=chart.planets.find(p=>p.id===pointId),longitude=pointId==='ascendant'?chart.ascendant:pointId==='midheaven'?chart.midheaven:planet?.lon;
 if(longitude==null||!Number.isFinite(longitude)||longitude<0||longitude>=360)return unavailable(definition.name,'This point’s position is unavailable in the calculated chart.');
 if(pointId==='moon'&&!known)return {status:'uncertain',title:'Moon · birth time required',sections:[],aspectCount:0,notes:['The Moon shown on the wheel is an approximate noon reference in the birth timezone (UTC if no place was supplied). It moves quickly and may change sign on the birth date. Supply a confirmed time and timezone for a lunar reading and comparison.']};
 const signIndex=Math.floor(longitude/30),sign=signs[signIndex],signName=zodiacNames[signIndex];
 const relevantAspects=chart.aspects.filter(a=>(a.a===pointId||a.b===pointId)&&(known||(a.a!=='moon'&&a.b!=='moon'&&!['ascendant','midheaven'].includes(a.a)&&!['ascendant','midheaven'].includes(a.b)))).sort((a,b)=>a.orb-b.orb||a.a.localeCompare(b.a)||a.b.localeCompare(b.b));
 const sections:InterpretationSection[]=[
 {title:'Essence',text:`${definition.essence} In ${signName}, ${definition.domain} may be expressed ${sign.manner}.`},
 {title:definition.contextTitle,text:pointId==='moon'?sign.moon:pointId==='venus'?sign.venus:definition.context},
 {title:'Potential',text:`${definition.potential}, with ${sign.gift}. The complete chart and your choices give this potential context.`},
 {title:'Things to notice',text:`${definition.attention}. ${signName} also invites reflection on ${sign.risk}. These are prompts rather than inevitable traits.`},
 {title:'In practice',text:`${definition.practice} ${sign.practice}`}];
 const house=known&&chart.houses&&Number.isInteger(planet?.house)&&planet!.house>=1&&planet!.house<=12?planet!.house:undefined;
 if(house!==undefined)sections.push({title:`House ${house}`,text:`In this chart’s house system, ${definition.name} occupies House ${house}, associated with ${houseReadings[house-1]}. The reading connects ${definition.domain} with this field of experience; a house does not determine events.`});
 if(planet?.retrograde)sections.push({title:'Retrograde motion',text:`${definition.name} was in apparent retrograde motion according to the astronomical calculation. Some traditions associate this with reflection and internal processing of the planet’s themes. It does not mean failure, inevitable obstacles or a planet physically reversing its orbit.`});
 sections.push({title:'Aspects',text:relevantAspects.length?`${definition.name} participates in ${relevantAspects.length} calculated ${relevantAspects.length===1?'contact':'contacts'} within the selected orbs: ${relevantAspects.map(a=>`${a.type} with ${points[a.a===pointId?a.b:a.a]?.name||(a.a===pointId?a.b:a.a)} (orb ${a.orb.toFixed(2)}°)`).join('; ')}. Read these alongside the sign and house. A smaller orb describes geometric closeness rather than the importance of an event.`:'No contact with this point meets the selected orb criteria. This describes the calculation criteria rather than a lack of importance or connection.'});
 if(relevantAspects.length){const closest=relevantAspects[0],other=closest.a===pointId?closest.b:closest.a,pair=describeAspectPair(pointId,other,closest.angle,{a:definition.name,b:points[other]?.name||other});if(pair)sections.push({title:'A dialogue in this chart',text:`${definition.name} · ${closest.type} · ${points[other]?.name||other}: ${pair.context} ${pair.reflection}`});}
 const notes=known?[]:['Birth time unknown: this reading uses an approximate noon reference in the birth timezone (UTC if no place was supplied). Sign and degree may vary with the actual time, especially near a sign boundary. Houses and contacts involving the Moon or angles are excluded.'];
 if(definition.generational)notes.push('This body moves slowly: its sign is shared by many people in a generation. Houses and aspects help personalize the reading when the birth data supports them.');
 return {status:'ready',title:`${definition.name} in ${signName}`,subtitle:`${(longitude%30).toFixed(2)}°${house?` · House ${house}`:''}${planet?.retrograde?' · Retrograde':''}`,sections,notes,aspectCount:relevantAspects.length,placement:{point:pointId,sign:signIndex},discoveryLabel:`Who has ${definition.name} in ${signName}?`};
}

