import type { ComputedChart } from './astro';

export const MAKEUP_BODY_IDS = ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'uranus', 'neptune', 'pluto'] as const;
export type MakeupBodyId = typeof MAKEUP_BODY_IDS[number];
export type ChartElement = 'fire' | 'earth' | 'air' | 'water';
export type ChartModality = 'cardinal' | 'fixed' | 'mutable';
export const MODALITY_GUIDES: Record<ChartModality, { label: string; meaning: string }> = {
  cardinal: { label: 'Cardinal', meaning: 'In astrology, the cardinal modality is associated with initiating and putting ideas into motion.' },
  fixed: { label: 'Fixed', meaning: 'In astrology, the fixed modality is associated with sustaining and developing what has begun.' },
  mutable: { label: 'Mutable', meaning: 'In astrology, the mutable modality is associated with adapting, connecting and reconsidering paths.' },
};

export const ELEMENT_GUIDES: Record<ChartElement, { label: string; meaning: string; prompt: string; color: string }> = {
  fire: { label: 'Fire', meaning: 'In astrology, fire is associated with initiative, expression and a desire to explore.', prompt: 'What makes you want to begin?', color: '#e89b74' },
  earth: { label: 'Earth', meaning: 'In astrology, earth is associated with practical action, steadiness and tangible results.', prompt: 'What helps you feel grounded?', color: '#8dae92' },
  air: { label: 'Air', meaning: 'In astrology, air is associated with ideas, conversations and different perspectives.', prompt: 'What idea is on your mind?', color: '#a3b9de' },
  water: { label: 'Water', meaning: 'In astrology, water is associated with feelings, imagination and emotional connections.', prompt: 'What feeling needs some space now?', color: '#b5a0d5' },
};

const ELEMENT_ORDER: ChartElement[] = ['fire', 'earth', 'air', 'water'];
const SIGN_NAMES = ['Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo', 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces'];
const BODY_NAMES: Record<MakeupBodyId, string> = { sun: 'Sun', moon: 'Moon', mercury: 'Mercury', venus: 'Venus', mars: 'Mars', jupiter: 'Jupiter', saturn: 'Saturn', uranus: 'Uranus', neptune: 'Neptune', pluto: 'Pluto' };

export interface MakeupMember { id: MakeupBodyId; name: string; sign: string; longitude: number }
export interface MakeupGroup { element: ChartElement; count: number; percentage: number; members: MakeupMember[] }
export interface ModalityGroup { modality: ChartModality; count: number; percentage: number; members: MakeupMember[] }
export type ChartMakeupResult =
  | { status: 'ready'; total: 10; groups: MakeupGroup[]; modalities: ModalityGroup[]; dominantElements: ChartElement[]; lackingElements: ChartElement[]; dominantModalities: ChartModality[]; lackingModalities: ChartModality[]; provisional: boolean; referenceNote: string | null; ascendantExtra: { sign: string; longitude: number } | null }
  | { status: 'unavailable'; reason: 'incomplete-chart'; message: string };

/** A disclosed count of ten sign placements, never a personality or daily-energy score. */
export function computeChartMakeup(chart: ComputedChart): ChartMakeupResult {
  if (!chart || !Array.isArray(chart.planets)) return incomplete();
  const groups: MakeupGroup[] = ELEMENT_ORDER.map(element => ({ element, count: 0, percentage: 0, members: [] }));
  const modalities: ModalityGroup[] = (['cardinal', 'fixed', 'mutable'] as const).map(modality => ({ modality, count: 0, percentage: 0, members: [] }));
  for (const id of MAKEUP_BODY_IDS) {
    const matches = chart.planets.filter(planet => planet.id === id);
    if (matches.length !== 1) return incomplete();
    const planet = matches[0];
    if (typeof planet.lon !== 'number' || !Number.isFinite(planet.lon) || planet.lon < 0 || planet.lon >= 360) return incomplete();
    // Use the calculated longitude rather than trusting a translated or stale display label.
    const signIndex = Math.floor(planet.lon / 30);
    const group = groups[signIndex % 4];
    const member = { id, name: BODY_NAMES[id], sign: SIGN_NAMES[signIndex], longitude: planet.lon };
    group.members.push(member);
    group.count += 1;
    group.percentage = group.count * 10;
    modalities[signIndex % 3].members.push(member);
    modalities[signIndex % 3].count += 1;
    modalities[signIndex % 3].percentage = modalities[signIndex % 3].count * 10;
  }
  const maximumElement = Math.max(...groups.map(g => g.count)), maximumModality = Math.max(...modalities.map(g => g.count));
  const provisional = chart.metadata?.timeKnown !== true;
  const ascendantExtra = !provisional && typeof chart.ascendant === 'number' && Number.isFinite(chart.ascendant) && chart.ascendant >= 0 && chart.ascendant < 360 ? { sign: SIGN_NAMES[Math.floor(chart.ascendant / 30)], longitude: chart.ascendant } : null;
  return { status: 'ready', total: 10, groups, modalities, dominantElements: groups.filter(g => g.count === maximumElement).map(g => g.element), lackingElements: groups.filter(g => g.count === 0).map(g => g.element), dominantModalities: modalities.filter(g => g.count === maximumModality).map(g => g.modality), lackingModalities: modalities.filter(g => g.count === 0).map(g => g.modality), provisional,
    referenceNote: provisional ? 'Birth time unknown · provisional composition at 12:00 local time (UTC if no place was supplied). The exact Moon position and counts can change with the birth time.' : null, ascendantExtra };
}

function incomplete(): ChartMakeupResult {
  return { status: 'unavailable', reason: 'incomplete-chart', message: 'This composition requires a valid calculated position for each of the ten bodies, from the Sun to Pluto. The chart is incomplete or contains an invalid position, so percentages are unavailable.' };
}

