/** Rudhyar lunation convention required by the product specification, section 8.5. */
export const lunationPhaseNames = ['New Moon', 'Crescent', 'First Quarter', 'Gibbous', 'Full Moon', 'Disseminating', 'Last Quarter', 'Balsamic'] as const;
export const lunationPhaseNamesEn = ['New Moon', 'Crescent', 'First Quarter', 'Gibbous', 'Full Moon', 'Disseminating', 'Last Quarter', 'Balsamic'] as const;
export type PhaseNumber = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
export interface LunationPhase {
  phaseNumber: PhaseNumber;
  phaseName: string;
  phaseNameEn: string;
  phaseAngle: number;
  /** Product formula (1 - cos E)/2, a fraction. Physical illumination is a separate field. */
  illumination: number;
  illuminationPercent: number;
  waxing: boolean;
}
export function phaseFromElongation(elongation: number): LunationPhase {
  if (!Number.isFinite(elongation)) throw new Error('Invalid elongation.');
  const phaseAngle = ((elongation % 360) + 360) % 360;
  const phaseNumber = (Math.floor(phaseAngle / 45) + 1) as PhaseNumber;
  const illumination = (1 - Math.cos(phaseAngle * Math.PI / 180)) / 2;
  return { phaseNumber, phaseName: lunationPhaseNames[phaseNumber - 1], phaseNameEn: lunationPhaseNamesEn[phaseNumber - 1], phaseAngle, illumination, illuminationPercent: illumination * 100, waxing: phaseAngle < 180 };
}
export function lunationPhase(sunLongitude: number, moonLongitude: number): LunationPhase {
  if (!Number.isFinite(sunLongitude) || !Number.isFinite(moonLongitude)) throw new Error('Invalid longitudes.');
  return phaseFromElongation(moonLongitude - sunLongitude);
}

/** Count civil calendar dates, not 24-hour durations; DST days can have 23 or 25 hours. */
export function localPhaseDay(phaseStart: string, selectedDate: string, timeZone: string): number {
  const start = new Date(phaseStart);
  if (!Number.isFinite(start.getTime()) || !/^\d{4}-\d{2}-\d{2}$/.test(selectedDate)) throw new Error('Invalid phase dates.');
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(start).map(part => [part.type, part.value]));
  const firstDate = `${parts.year}-${parts.month}-${parts.day}`;
  const first = Date.parse(`${firstDate}T00:00:00Z`), selected = Date.parse(`${selectedDate}T00:00:00Z`);
  if (!Number.isFinite(selected) || new Date(selected).toISOString().slice(0, 10) !== selectedDate || selected < first) throw new Error('Date is before the phase begins.');
  return Math.round((selected - first) / 86400000) + 1;
}

src/lib/civil-day.ts:
/** Browser-safe resolution of a selected local civil day to its real noon instant. */
export function localNoon(date: string, timeZone: string): Date {
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Invalid date; use YYYY-MM-DD.');
  const target = Date.parse(`${date}T12:00:00Z`);
  if (!Number.isFinite(target) || new Date(target).toISOString().slice(0, 10) !== date || date < '1200-01-01' || date > '2399-12-31') throw new Error('Date does not exist or is outside the 1200–2399 coverage.');
  if (typeof timeZone !== 'string' || !timeZone.trim() || timeZone.length > 100) throw new Error('Select a valid IANA timezone.');
  let format: Intl.DateTimeFormat;
  try {
    format = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
  } catch { throw new Error('Select a valid IANA timezone.'); }
  const localMillis = (instant: number): number => {
    const parts = Object.fromEntries(format.formatToParts(new Date(instant)).map(part => [part.type, part.value]));
    return Date.parse(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}Z`);
  };
  // Offset samples span both sides of DST transitions and date-line changes.
  const offsets = new Set([-36, 0, 36].map(hours => {
    const instant = target + hours * 3600000;
    return localMillis(instant) - instant;
  }));
  const candidates = [...offsets].map(offset => target - offset).filter(instant => localMillis(instant) === target);
  if (candidates.length !== 1) throw new Error('Local noon is ambiguous or does not exist because of a timezone change.');
  const result = new Date(candidates[0]);
  if (result.getUTCFullYear() < 1200 || result.getUTCFullYear() > 2399) throw new Error('Local noon is outside the 1200–2399 coverage.');
  return result;
}

src/lib/similarity.ts:
export interface PositionChart {
  planets: Array<{ id: string; lon: number }>;
  metadata?: { timeKnown: boolean };
}

// Personal planets dominate; slow planets must not make an entire generation twins.
const WEIGHTS: Record<string, number> = {
  sun: 3, moon: 3, mercury: 2, venus: 2, mars: 2,
  jupiter: 1, saturn: 1, uranus: 0.5, neptune: 0.5, pluto: 0.5,
};
export function angularDistance(a: number, b: number): number {
  const d = ((a - b) % 360 + 360) % 360;
  return Math.min(d, 360 - d);
}

/** A versioned geometric index, never a probability or scientific personality score. */
export function comparePositions(a: PositionChart, b: PositionChart) {
  const timeKnown = a.metadata?.timeKnown === true && b.metadata?.timeKnown === true;
  const seen = new Set<string>();
  const positions = a.planets.flatMap(p => {
    const other = b.planets.find(q => q.id === p.id);
    if (!other || !WEIGHTS[p.id] || seen.has(p.id) || (!timeKnown && p.id === 'moon')) return [];
    if (!Number.isFinite(p.lon) || !Number.isFinite(other.lon)) throw new Error('Invalid longitude');
    seen.add(p.id);
    const difference = angularDistance(p.lon, other.lon);
    return [{ planet: p.id, difference, weight: WEIGHTS[p.id], similarity: 100 * Math.exp(-0.5 * (difference / 30) ** 2) }];
  });
  if (!positions.length) throw new Error('No comparable planets');
  const weight = positions.reduce((n, p) => n + p.weight, 0);
  const score = positions.reduce((n, p) => n + p.similarity * p.weight, 0) / weight;
  return {
    method: 'personal-weighted-gaussian-30deg-v1',
    score: Math.round(score * 10) / 10,
    partial: positions.length !== 10,
    excluded: [...(timeKnown ? [] : ['moon']), 'ascendant', 'houses'],
    positions: positions.sort((a, b) => a.difference - b.difference),
  };
}

