import type { ComputedChart } from './astro';

export const journalStorageKey = 'astrolove_private_journal_v1';
export interface JournalEntry {
  id: string; profile: string; createdAt: string; text: string; context: string;
}
// Stable across house/orb changes; distinct locations/known times retain distinct angles.
export function journalProfile(chart: ComputedChart): string {
  return JSON.stringify([chart.metadata?.utc, chart.metadata?.timeKnown, chart.planets.map(p => [p.id, p.lon]), chart.ascendant, chart.midheaven]);
}
export function parseJournal(raw: string | null): JournalEntry[] {
  if (raw === null) return [];
  const value: unknown = JSON.parse(raw);
  if (!Array.isArray(value) || value.length > 500 || value.some(e => !e || typeof e.id !== 'string' || typeof e.profile !== 'string' || typeof e.createdAt !== 'string' || !Number.isFinite(Date.parse(e.createdAt)) || typeof e.text !== 'string' || !e.text.trim() || e.text.length > 10000 || typeof e.context !== 'string') || new Set(value.map(e => e.id)).size !== value.length) throw new Error('Saved journal is invalid. Existing data has been preserved.');
  return value;
}
export function addJournalEntry(entries: JournalEntry[], entry: JournalEntry): JournalEntry[] {
  const result = [entry, ...entries];
  parseJournal(JSON.stringify(result));
  return result;
}

