import type { ComputedChart } from './astro';
import { zodiacNames } from './catalog';
import { houseTopics } from './chart-learning';
import { houseSystemNames } from './chart-settings';
import type { ChartElementSelection } from '../components/ChartElementExplanation';
export type LearningTerm={id:string;title:string;category:'Start'|'Planets'|'Signs'|'Houses'|'Aspects'|'Method';definition:string;pointId?:string;signIndex?:number;houseNumber?:number;aspectAngle?:number};
const planets=[
 ['sun','Sun','The Sun symbolizes identity, vitality and the direction you choose for your expression. Your Sun sign is one part of the full chart.'],
 ['moon','Moon','The Moon symbolizes emotional needs, care and ways of seeking security. It moves quickly: an unknown birth time prevents a confirmed lunar interpretation.'],
 ['mercury','Mercury','Mercury symbolizes communication, curiosity and ways of organizing and exchanging information. Its sign and contacts provide context.'],
 ['venus','Venus','Venus symbolizes affection, values, pleasure and reciprocity. Its position invites reflection on preferences and agreements without deciding whom you should love.'],
 ['mars','Mars','Mars symbolizes initiative, desire and ways of acting or sustaining boundaries. Its reading considers how to turn an impulse into a chosen action.'],
 ['jupiter','Jupiter','Jupiter symbolizes expansion, broad learning and meaning. The full chart offers context for opportunities and the risk of excess.'],
 ['saturn','Saturn','Saturn symbolizes time, responsibility and consistency. Boundaries and commitments can be explored without reducing the planet to fear or punishment.'],
 ['uranus','Uranus','Uranus symbolizes autonomy, experimentation and revisiting patterns. Its slow movement makes its sign a theme shared by many people in a generation.'],
 ['neptune','Neptune','Neptune symbolizes imagination, receptivity, ideals and boundaries. Its sign is generational and does not establish powers, diagnoses or intuitive certainty.'],
 ['pluto','Pluto','Pluto symbolizes depth, power and transformation. As a slow-moving body, its sign position is shared by many people.'],
];
const signThemes=['initiative and directness','continuity and resources','curiosity and exchange','care and belonging','expression and creativity','observation and improvement','dialogue and reciprocity','depth and trust','exploration and meaning','responsibility and building','autonomy and collective participation','imagination and receptivity'];
export const learningTerms:LearningTerm[]=[
 {id:'planet',title:'Planet: what is being expressed?',category:'Start',definition:'Planets and luminaries represent symbolic functions in astrology. The Sun and Moon are included by convention, although they are a star and a natural satellite. Read planet, sign, house and aspects together.'},
 {id:'sign',title:'Sign: how is this function expressed?',category:'Start',definition:'The twelve signs divide the tropical zodiac into thirty-degree sectors. They are an astrological reference connected to the seasonal cycle, distinct from astronomical constellations. A sign describes a symbolic tone of a position.'},
 {id:'house',title:'House: which field of experience?',category:'Start',definition:'Houses divide a chart for a time and place. Symbolically, they describe fields of experience. Changing the house system can change cusps and planetary houses; an empty house remains part of the chart.'},
 {id:'aspect',title:'Aspect: a dialogue between two points',category:'Start',definition:'An aspect compares the angular separation of two points with a reference angle. Its reading relates symbolic functions; geometry does not determine personality or relationship quality.'},
 ...planets.map(([id,title,definition])=>({id,title,definition,category:'Planets' as const,pointId:id})),
 ...zodiacNames.map((title,signIndex)=>({id:`sign-${signIndex}`,title,signIndex,category:'Signs' as const,definition:`${title} occupies the sector from ${signIndex*30}° to ${(signIndex+1)*30}° of the tropical zodiac. Its traditional reading explores ${signThemes[signIndex]}. This tone does not define someone’s entire personality.`})),
 ...houseTopics.map((topic,i)=>({id:`house-${i+1}`,title:`House ${i+1}`,houseNumber:i+1,category:'Houses' as const,definition:`In symbolic readings, House ${i+1} explores ${topic.toLocaleLowerCase('en')}. Its cusp marks the start of the division in the selected system. Having no planets there does not mean that theme is absent from life.`})),
 ...[[0,'Conjunction','closeness and joint expression'],[60,'Sextile','opportunities for cooperation'],[90,'Square','contrasts that invite adjustments'],[120,'Trine','ease of expression'],[180,'Opposition','polarities and balance']].map(([aspectAngle,title,theme])=>({id:`aspect-${aspectAngle}`,title:String(title),aspectAngle:Number(aspectAngle),category:'Aspects' as const,definition:`Reference aspect angle: ${aspectAngle}°. In astrology its reading explores ${theme}. It appears in a chart’s list only when the measured separation falls within the selected orb.`})),
 {id:'orb',title:'Orb: distance from the exact aspect',category:'Aspects',definition:'An orb is the difference between the measured separation and the aspect’s reference angle. A smaller orb means greater geometric closeness. You can adjust calculation limits without treating closeness as certainty about events.'},
 {id:'ascendant',title:'Ascendant',category:'Method',pointId:'ascendant',definition:'The zodiac point rising on the eastern horizon at the chart’s time and place. Its symbolic reading considers presentation and first encounters. Time, location and timezone are required to calculate it.'},
 {id:'midheaven',title:'Midheaven (MC)',category:'Method',pointId:'midheaven',definition:'An angle associated with the local meridian. Symbolically, it explores public direction and contribution. It is not always the cusp of the tenth house; that depends on the house system.'},
 {id:'retrograde',title:'Retrograde motion',category:'Method',definition:'An apparent motion as viewed from Earth: the body’s longitude is decreasing at the calculated instant. The planet does not reverse its physical orbit. Some traditions associate this condition with revision and inner processing.'},
 {id:'unknown-time',title:'Unknown birth time',category:'Method',definition:'Without a confirmed time, this app uses noon in the birth timezone (UTC if no place was supplied). Houses, Ascendant and MC are unavailable; confirmed lunar readings and contacts are omitted. Other planets can also change sign near a boundary during the day.'},
 {id:'systems',title:'House systems',category:'Method',definition:'Equal houses divide the zodiac into equal sectors from the Ascendant; whole-sign houses use one sign per house; Placidus uses a time-based division. The system changes the reading convention without changing planetary positions. Placidus may be unavailable near the poles.'},
 {id:'cusp',title:'Cusp and degree',category:'Method',definition:'A cusp begins a house. Degree in sign measures position within a thirty-degree sector; longitude measures position around the whole zodiac. Consult calculated values rather than estimating a house from the sign alone.'},
 {id:'synastry',title:'Synastry and similarity',category:'Method',definition:'Similarity compares each planet with the same planet in another chart. Synastry calculates contacts between points in both charts. Geometric closeness is not a probability of a relationship or identical personalities.'},
];
export function findLearningTerms(query:string,category=''){
 const normalize=(text:string)=>text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('en');
 const tokens=normalize(query).trim().split(/\s+/).filter(Boolean);
 return learningTerms.filter(term=>(!category||term.category===category)&&tokens.every(token=>normalize(`${term.title} ${term.definition}`).includes(token)));
}
export function learningContext(term:LearningTerm,chart?:ComputedChart|null):{text:string;pointId?:string;selection?:ChartElementSelection}{
 if(!chart)return {text:'Calculate or choose a profile to see examples from your chart. Definitions remain available without birth data.'};
 const known=chart.metadata?.timeKnown===true;
 const planets=chart.planets.filter(p=>known||p.id!=='moon');
 const aspects=chart.aspects.filter(a=>known||![a.a,a.b].some(id=>['moon','ascendant','midheaven'].includes(id))).slice().sort((a,b)=>a.orb-b.orb);
 const point=term.pointId||(term.id==='planet'?'sun':undefined);
 if(point){
  if(!known&&['moon','ascendant','midheaven'].includes(point))return {text:'This point needs a confirmed birth time for a reading. No confirmed sign, house or contact is assigned here.'};
  const p=planets.find(p=>p.id===point),lon=p?.lon??(point==='ascendant'?chart.ascendant:point==='midheaven'?chart.midheaven:null);
  if(lon==null)return {text:'This method did not calculate this point. Check the chart limitations; the definition does not replace an available position.'};
  return {text:`${p?.name||term.title} in ${zodiacNames[Math.floor(lon/30)]}, ${(lon%30).toFixed(2)}°${known&&p?.house?` · House ${p.house}`:''}.${known?'':' Approximate local-noon reference; the position may vary with the actual birth time.'}`,pointId:point};
 }
 if(term.signIndex!==undefined||term.id==='sign'){
  const index=term.signIndex??Math.floor(planets.find(p=>p.id==='sun')!.lon/30),members=planets.filter(p=>Math.floor(p.lon/30)===index).map(p=>p.name);
  return {text:`${zodiacNames[index]} in this chart: ${members.length?members.join(', '):'none of the available bodies in this sector'}.${known?'':' Approximate local-noon reference; Moon omitted.'}`,selection:{kind:'sign',index}};
 }
 if(term.houseNumber||['house','cusp'].includes(term.id)){
  const h=known?chart.houses?.find(h=>h.number===(term.houseNumber||1)):undefined;
  return h?{text:`House ${h.number}: cusp in ${h.sign}, ${h.degree.toFixed(2)}° · longitude ${h.cuspLon.toFixed(2)}°.`,selection:{kind:'house',number:h.number}}:{text:'Houses are unavailable in this chart. A confirmed time, location and a calculable house convention are required; no cusp example has been invented.'};
 }
 if(term.aspectAngle!==undefined||['aspect','orb'].includes(term.id)){
  const a=term.aspectAngle===undefined?aspects[0]:aspects.find(a=>a.angle===term.aspectAngle);
  return a?{text:`${chart.planets.find(p=>p.id===a.a)?.name||({ascendant:'Ascendant',midheaven:'Midheaven'}[a.a]||a.a)} · ${a.type} · ${chart.planets.find(p=>p.id===a.b)?.name||({ascendant:'Ascendant',midheaven:'Midheaven'}[a.b]||a.b)}: reference ${a.angle}°, orb ${a.orb.toFixed(2)}°.`,selection:{kind:'aspect',a:a.a,b:a.b}}:{text:'No available contact of this type meets the selected orb criteria. This does not imply the theme is absent from your life.'};
 }
 if(term.id==='retrograde'){const bodies=planets.filter(p=>p.retrograde);return {text:bodies.length?`Calculated retrograde motion: ${bodies.map(p=>p.name).join(', ')}.`:'None of the available bodies is retrograde at this calculated instant.',pointId:bodies[0]?.id};}
 if(term.id==='systems')return {text:`This chart’s house system: ${houseSystemNames[chart.metadata?.houseSystem||'equal']}.${chart.houses?' Calculated cusps are in the Houses section.':' No houses were calculated for this method or profile.'}`};
 if(term.id==='unknown-time')return {text:known?`This chart has a known instant: ${chart.metadata!.utc}. Accuracy still depends on the birth data and documented time standard.`:`Chart reference: ${chart.metadata?.utc||'not supplied'}. Moon, houses and angles do not provide confirmed examples.`};
