import * as astronomy from 'astronomy-engine';
import { buildSky, searchObjects } from './sky.js';

type Row = [number, number|null, string, string[], number, number, number, number|null, number|null, number|null];
type Catalog = { stars: Row[] };
let catalog: Promise<Catalog> | undefined;
function loadCatalog() {
  return catalog ??= fetch('/fomalhaut/data/stars.json', { signal: AbortSignal.timeout(15000) })
    .then(async response => {
      if (!response.ok) throw Error('Star catalogue unavailable');
      const data = await response.json();
      if (data.version !== 1 || data.stars?.length !== 8920 || !data.stars.every((r: Row) =>
        Array.isArray(r) && r.length === 10 && typeof r[2] === 'string' && Array.isArray(r[3]) &&
        r[3].every(v => typeof v === 'string') && [r[4], r[5], r[6]].every(Number.isFinite))) throw Error('Invalid star catalogue');
      return data as Catalog;
    }).catch(error => { catalog = undefined; throw error; });
}
export interface SkyObject {
  id: string; name: string; magnitude: number; altitude: number; azimuth: number; kind: string; hip?: number;
}
let lastSky: { key: string; objects: SkyObject[] } | undefined;
export async function observerSky(instant: string, latitude: number, longitude: number): Promise<SkyObject[]> {
  const data = await loadCatalog();
  const key = JSON.stringify([instant, latitude, longitude]);
  if (lastSky?.key === key) return lastSky.objects;
  const engine = typeof astronomy.Observer === 'function' ? astronomy : Reflect.get(astronomy, 'default');
  const objects = buildSky(engine, data, new Date(instant), {latitude, longitude}).objects;
  lastSky = { key, objects };
  return objects;
}
export function searchSky(objects: SkyObject[], text: string): SkyObject[] {
  return searchObjects(objects, text, 8);
}

