import type { DailyContact } from './daily-sky';
import type { BodyId } from './featured-planet';
import type { ChartSettings } from './chart-settings';

const names: Record<string, string> = { '0': 'Conjunction', '60': 'Sextile', '90': 'Square', '120': 'Trine', '180': 'Opposition' };
export const aspectSeparation = (a: number, b: number) => {
  const difference = Math.abs(a - b) % 360;
  return Math.min(difference, 360 - difference);
};
/** One-hour-later positions must come from the same ephemeris, not a linear motion estimate. */
export function transitContacts(moving: { id: string; lon: number }[], oneHourLater: { id: string; lon: number }[], natal: { id: string; lon: number }[], settings: ChartSettings): DailyContact[] {
  const next = new Map(oneHourLater.map(body => [body.id, body.lon]));
  const contacts: DailyContact[] = [];
  for (const transit of moving) for (const fixed of natal) {
    const later = next.get(transit.id);
    if (later === undefined) throw new Error('The position one hour later is unavailable.');
    for (const [angleText, limit] of Object.entries(settings.orbs)) {
      const angle = Number(angleText), orb = Math.abs(aspectSeparation(transit.lon, fixed.lon) - angle);
      if (orb > limit + 1e-9) continue;
      const applying = Math.abs(aspectSeparation(later, fixed.lon) - angle) < orb;
      contacts.push({ transitPlanet: transit.id, natalPlanet: fixed.id, type: names[angleText], angle, orb, applying, motion: applying ? 'applying' : 'separating' });
    }
  }
  return contacts;
}

/** Featured planet takes the first slot; the rest rank by orb then slower absolute speed. */
export function topTransitContacts(contacts: DailyContact[], speeds: Readonly<Record<string, number>>, featuredPlanet?: BodyId): DailyContact[] {
  const sorted = [...contacts].sort((a, b) => a.orb - b.orb || Math.abs(speeds[a.transitPlanet] ?? Infinity) - Math.abs(speeds[b.transitPlanet] ?? Infinity) || a.transitPlanet.localeCompare(b.transitPlanet) || a.natalPlanet.localeCompare(b.natalPlanet));
  const featured = featuredPlanet ? sorted.find(contact => contact.transitPlanet === featuredPlanet) : undefined;
  return featured ? [featured, ...sorted.filter(contact => contact !== featured)].slice(0, 3) : sorted.slice(0, 3);
}

