import type { ComputedChart } from './astro';
import type { BirthDetails } from '../types';
import { zodiacNames } from './catalog';
import { describePlanet } from './planet-interpretation';
import { describeAspectPair } from './aspect-interpretation';
import { houseSystemNames } from './chart-settings';
import { houseTopics } from './chart-learning';

const ids = ['sun', 'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'uranus', 'neptune', 'pluto'];
const angles = { ascendant: 'Ascendant', midheaven: 'Midheaven' };
const aspectAngles: Record<string, number> = { Conjunction: 0, Sextile: 60, Square: 90, Trine: 120, Opposition: 180 };
const norm = (n: number) => (n % 360 + 360) % 360;
const distance = (a: number, b: number) => Math.min(norm(a - b), norm(b - a));
const finiteLongitude = (n: unknown): n is number => typeof n === 'number' && Number.isFinite(n) && n >= 0 && n < 360;

/** A report must fail visibly if its positions or relationships contradict the chart. */
export function buildChartReport(chart: ComputedChart, name: string) {
  const invalid = () => { throw new Error('The chart contains inconsistent data. Recalculate before opening the report.'); };
  const metadata = chart?.metadata;
  if (!metadata || !['swiss-ephemeris', 'astronomy-engine'].includes(metadata.engine) || metadata.zodiac !== 'tropical-geocentric' || !Object.hasOwn(houseSystemNames, metadata.houseSystem) || typeof metadata.timeKnown !== 'boolean' || !Array.isArray(metadata.warnings) || metadata.warnings.some(w => typeof w !== 'string')) invalid();
  if (!Number.isFinite(Date.parse(metadata.utc)) || new Date(metadata.utc).toISOString() !== metadata.utc) invalid();
  if (!Array.isArray(chart.planets) || chart.planets.length !== 10 || new Set(chart.planets.map(p => p.id)).size !== 10) invalid();
  for (const p of chart.planets) {
    if (!ids.includes(p.id) || !finiteLongitude(p.lon) || p.sign !== zodiacNames[Math.floor(p.lon / 30)] || !Number.isFinite(p.degree) || Math.abs(p.degree - p.lon % 30) > 1e-7 || !Number.isInteger(p.house) || p.house < 0 || p.house > 12 || typeof p.retrograde !== 'boolean') invalid();
  }
  for (const lon of [chart.ascendant, chart.midheaven]) if (lon !== null && !finiteLongitude(lon)) invalid();
  if (!metadata.timeKnown && (chart.houses !== null || chart.ascendant !== null || chart.midheaven !== null || chart.planets.some(p => p.house !== 0))) invalid();
  if (chart.houses !== null) {
    if (!metadata.timeKnown || chart.ascendant === null || chart.midheaven === null || chart.houses.length !== 12) invalid();
    const widths = chart.houses.map((h, i) => norm(chart.houses![(i + 1) % 12].cuspLon - h.cuspLon));
    if (widths.some(w => w <= 0) || Math.abs(widths.reduce((a, b) => a + b, 0) - 360) > 1e-6) invalid();
    for (const [i, h] of chart.houses.entries()) if (h.number !== i + 1 || !finiteLongitude(h.cuspLon) || !Number.isFinite(h.degree) || h.sign !== zodiacNames[Math.floor(h.cuspLon / 30)] || Math.abs(h.degree - h.cuspLon % 30) > 1e-7) invalid();
    for (const p of chart.planets) if (chart.houses.find((h, i) => norm(p.lon - h.cuspLon) < widths[i])?.number !== p.house) invalid();
  } else if (chart.planets.some(p => p.house !== 0) || chart.ascendant !== null || chart.midheaven !== null) invalid();
  const longitudes = new Map(chart.planets.map(p => [p.id, p.lon]));
  for (const id of Object.keys(angles)) if (chart[id] !== null) longitudes.set(id, chart[id]);
  const pairs = new Set<string>();
  if (!Array.isArray(chart.aspects)) invalid();
  for (const a of chart.aspects) {
    const key = [a.a, a.b].sort().join(':');
    if (a.a === a.b || pairs.has(key) || !longitudes.has(a.a) || !longitudes.has(a.b) || aspectAngles[a.type] !== a.angle || !Number.isFinite(a.orb) || a.orb < 0 || a.orb > 12 || Math.abs(Math.abs(distance(longitudes.get(a.a)!, longitudes.get(a.b)!) - a.angle) - a.orb) > 1e-6) invalid();
    pairs.add(key);
  }
  const names = new Map(chart.planets.map(p => [p.id, p.name]));
  Object.entries(angles).forEach(([id, label]) => names.set(id, label));
  const positions = chart.planets.filter(p => metadata.timeKnown || p.id !== 'moon');
  const angularPositions = Object.entries(angles).filter(([id]) => metadata.timeKnown && chart[id] !== null).map(([id, label]) => ({ id, name: label, lon: chart[id] as number, sign: zodiacNames[Math.floor(chart[id] / 30)], degree: chart[id] % 30 }));
  const retainedAspects = chart.aspects.filter(a => metadata.timeKnown || (a.a !== 'moon' && a.b !== 'moon')).sort((a, b) => a.orb - b.orb || a.a.localeCompare(b.a) || a.b.localeCompare(b.b));
  const readings = [...positions, ...angularPositions].map(p => ({ id: p.id, ...describePlanet(chart, p.id) }));
  const rawInput = (chart as ComputedChart & { input?: BirthDetails }).input;
  const input = rawInput ? { date: rawInput.date, time: metadata.timeKnown ? rawInput.time : '', location: rawInput.location, timezone: rawInput.timezone, lat: rawInput.lat, lon: rawInput.lon } : undefined;
  const sourceInput = rawInput as BirthDetails & { source?: string; attribution?: string; license?: string; licenseUrl?: string; sourceNotes?: string; timeEvidence?: { source?: string; note?: string } };
  const sourceUrl = (value: unknown) => { try { const u = new URL(String(value)); return ['http:', 'https:'].includes(u.protocol) && !u.username && !u.password ? u.href : undefined; } catch { return undefined; } };
  const provenance = sourceInput ? { source: sourceUrl(sourceInput.source), attribution: typeof sourceInput.attribution === 'string' ? sourceInput.attribution : undefined, license: typeof sourceInput.license === 'string' ? sourceInput.license : undefined, licenseUrl: sourceUrl(sourceInput.licenseUrl), coordinateSource: sourceUrl(sourceInput.coordinateSource), note: [sourceInput.sourceNotes, sourceInput.timeEvidence?.note].filter(value => typeof value === 'string').join(' ') } : undefined;
  return {
    name: name.trim() || 'My chart', metadata, input, provenance, positions, angularPositions, houses: chart.houses,
    readings, summary: ['sun', 'moon', 'ascendant'].map(id => readings.find(r => r.id === id)).filter(Boolean),
    aspects: retainedAspects.map(a => ({ ...a, firstName: names.get(a.a)!, secondName: names.get(a.b)!, separation: distance(longitudes.get(a.a)!, longitudes.get(a.b)!), interpretation: describeAspectPair(a.a, a.b, a.angle, { a: names.get(a.a)!, b: names.get(a.b)! }) })),
    limitations: [...metadata.warnings, ...(rawInput?.locationPrecision === 'city' ? ['City reference coordinates do not represent a confirmed birth address. Check the recorded coordinates for more precise houses and angles.'] : []), ...(!metadata.timeKnown ? ['Birth time unknown: the Moon, Ascendant, Midheaven, houses and lunar contacts are omitted from this report. Other planets use a noon reference in the birth timezone (UTC if no place was supplied) and may change sign near a boundary.'] : []), ...(metadata.timeKnown && !chart.houses ? ['This method did not calculate houses or angles; a known time does not replace the convention needed to calculate them.'] : [])],
  };
}

export type ChartReportData = ReturnType<typeof buildChartReport>;
export function escapeReportHtml(value: unknown) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
}

export function chartReportHtml(chart: ComputedChart, name: string, wheelSvg = ''): string {
  const r = buildChartReport(chart, name), e = escapeReportHtml;
  // Only the app's own serialized chart SVG belongs here. Reject active content.
  if (wheelSvg && (!/^<svg\b[\s\S]*<\/svg>$/.test(wheelSvg) || /<!|<\?|\son\w+\s*=|\bhref\s*=|url\(\s*['"]?(?!#)|<(?!\/?(?:svg|g|defs|path|circle|line|rect|text|title|radialGradient|linearGradient|stop|mask)\b)/i.test(wheelSvg))) throw new Error('The chart image contains unsupported content.');
  const p = (text: string) => `<p>${e(text)}</p>`;
  const heading = (title: string) => `<h2>${e(title)}</h2>`;
  const rows = (items: string[][]) => items.map(cells => `<tr>${cells.map(cell => `<td>${e(cell)}</td>`).join('')}</tr>`).join('');
  const table = (headers: string[], items: string[][]) => `<div class="table-wrap"><table><thead><tr>${headers.map(h => `<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows(items)}</tbody></table></div>`;
  const birth = r.input ? p([r.input.date, r.input.time || 'Birth time unknown', r.input.location, r.input.timezone].filter(Boolean).join(' · ')) + (Number.isFinite(r.input.lat) && Number.isFinite(r.input.lon) ? p(`Coordinates used: latitude ${r.input.lat.toFixed(6)} · longitude ${r.input.lon.toFixed(6)}`) : '') : '';
  const sources = r.provenance ? [r.provenance.coordinateSource ? `<p>City coordinates: <a href="${e(r.provenance.coordinateSource)}" rel="noreferrer">GeoNames · CC BY 4.0</a></p>` : '',r.provenance.source ? `<p>Supplied birth source: <a href="${e(r.provenance.source)}" rel="noreferrer">${e(r.provenance.source)}</a></p>` : '', r.provenance.attribution ? p(r.provenance.attribution) : '', r.provenance.license ? `<p>Data license: ${r.provenance.licenseUrl ? `<a href="${e(r.provenance.licenseUrl)}" rel="noreferrer">${e(r.provenance.license)}</a>` : e(r.provenance.license)}</p>` : '', r.provenance.note ? p(r.provenance.note) : ''].join('') : '';
  const settings = r.metadata.settings ? p(`Maximum orbs: ${Object.entries(r.metadata.settings.orbs).map(([angle, orb]) => `${angle}°: ${orb}°`).join(' · ')}`) : '';
  const intro = p('Planets represent symbolic functions; signs describe modes of expression; houses describe fields of experience; aspects relate two points. Begin with the Sun, Moon and Ascendant, then read the positions and their contacts together.');
  const overview = r.summary.map(reading => `<section><h3>${e(reading.title)}</h3>${p(reading.subtitle || '')}${p(reading.sections[0].text)}${p(reading.sections[1].text)}</section>`).join('');
  const figure = wheelSvg ? `<figure style="max-width:560px;margin:24px auto"><div style="background:#101116;border-radius:16px">${wheelSvg}</div><figcaption>Wheel of the same calculated chart. The tables below retain all numerical values.</figcaption></figure>` : '';
  const positions = table(['Point', 'Sign', 'Degree in sign', 'Longitude', 'House', 'Motion'], r.positions.map(point => [point.name, point.sign, `${point.degree.toFixed(4)}°`, `${point.lon.toFixed(6)}°`, point.house ? String(point.house) : 'Not calculated', point.retrograde ? 'Apparent retrograde' : 'Direct']));
  const angular = r.angularPositions.length ? table(['Angle', 'Sign', 'Degree in sign', 'Longitude'], r.angularPositions.map(point => [point.name, point.sign, `${point.degree.toFixed(4)}°`, `${point.lon.toFixed(6)}°`])) : '';
  const houses = r.houses ? table(['House', 'Sign', 'Cusp degree', 'Longitude', 'Symbolic theme'], r.houses.map(h => [String(h.number), h.sign, `${h.degree.toFixed(4)}°`, `${h.cuspLon.toFixed(6)}°`, houseTopics[h.number - 1]])) : p('Houses are unavailable in this chart.');
  const readings = r.readings.map(reading => `<article class="reading"><h3>${e(reading.title)}</h3>${p(reading.subtitle || '')}${reading.notes.map(p).join('')}${reading.sections.map(s => `<section><h4>${e(s.title)}</h4>${p(s.text)}</section>`).join('')}</article>`).join('');
  const aspects = table(['First point', 'Aspect', 'Second point', 'Separation', 'Exact angle', 'Orb'], r.aspects.map(a => [a.firstName, a.type, a.secondName, `${a.separation.toFixed(4)}°`, `${a.angle}°`, `${a.orb.toFixed(4)}°`]));
  const aspectReadings = r.aspects.map(a => `<article><h3>${e(`${a.firstName} · ${a.type} · ${a.secondName}`)}</h3>${a.interpretation ? p(a.interpretation.context) + p(a.interpretation.reflection) : ''}</article>`).join('');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><title>${e(r.name)} · Report Hermit</title><style>body{font:16px/1.65 system-ui,sans-serif;color:#17202a;background:#fff;margin:0;overflow-wrap:anywhere}main{max-width:900px;margin:0 auto;padding:40px 24px}h1{font-size:32px;line-height:1.2}h2{font-size:24px;margin-top:48px;border-bottom:1px solid #ccd3dc;padding-bottom:12px}h3{font-size:20px;margin-top:28px}h4{font-size:16px;margin-bottom:4px}p{margin:8px 0 16px}header{border-bottom:3px solid #806027;padding-bottom:24px}.note{background:#f5f0e5;border-left:4px solid #806027;padding:12px 16px}figure svg{display:block;width:100%;height:auto}.table-wrap{overflow:auto}table{min-width:620px;width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #dce1e8}th{background:#f4f6f8}.reading{border-bottom:1px solid #ccd3dc;padding-bottom:20px}footer{margin-top:40px;font-size:13px;color:#526172}@media print{main{max-width:none;padding:0}h2,h3,h4{break-after:avoid}tr,section{break-inside:avoid}thead{display:table-header-group}.table-wrap{overflow:visible}body{font-size:11pt}.note{background:transparent}}@page{size:A4;margin:18mm}</style></head><body><main><header><p>Hermit · Complete chart report</p><h1>${e(r.name)}</h1>${birth}${p(`UTC reference: ${r.metadata.utc}`)}${p(`Engine: ${r.metadata.engine} · Tropical geocentric zodiac · Houses: ${houseSystemNames[r.metadata.houseSystem]}`)}${settings}${sources}</header>${r.limitations.length ? `<aside class="note" aria-label="Accuracy and limitations">${r.limitations.map(p).join('')}</aside>` : ''}${heading('How to read this report')}${intro}${figure}${heading('Sun, Moon and Ascendant')}${overview}${heading('Calculated positions')}${positions}${angular}${heading('Houses and cusps')}${houses}${heading('Placement readings')}${readings}${heading('Calculated aspects')}${aspects}${aspectReadings}<footer>${p('The numbers reproduce the calculated chart. Readings are original text based on astrological traditions; they do not determine personality, events or relationship quality. This file contains profile data: share it only by your own choice.')}${p('To save as PDF, open this file in a browser and choose Print → Save as PDF. The report is self-contained and loads no external fonts, scripts or services.')}</footer></main></body></html>`;
}

