import { useEffect, useState } from 'react';
import { ChartWorkspace } from './components/ChartWorkspace';
import { computeChart, type ChartPayload } from './lib/astro';
import { createWorkspaceSavedChart, restoreSavedProfiles } from './lib/saved-chart';
import { loadChartLocal, saveChartLocal } from './lib/local-charts';
import './workspace.css';
import './daily-sky.css';
import './you-panel.css';

export default function OfflineApp() {
  const [saved] = useState(loadChartLocal);
  const [attempt, setAttempt] = useState(0);
  const [chart, setChart] = useState<ChartPayload | null>(null);
  const [error, setError] = useState('');
  const [continueEditing, setContinueEditing] = useState(false);
  useEffect(() => {
    if (!saved || continueEditing) return;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 45000);
    let active = true;
    computeChart(saved.mode, saved.user, saved.partner, saved.settings, controller.signal)
      .then(value => { if (active) setChart(value); })
      .catch(() => { if (active) setError('Could not reopen the saved chart. Your birth details are still on this device.'); })
      .finally(() => clearTimeout(timer));
    return () => { active = false; clearTimeout(timer); controller.abort(); };
  }, [saved, attempt, continueEditing]);

  if (saved && !chart && !continueEditing) return <main className="workspace-panel">
    {error ? <><p role="alert">{error}</p><button onClick={() => { setError(''); setAttempt(n => n + 1); }}>Retry chart</button>
      <button onClick={() => setContinueEditing(true)}>Open workspace</button></> : <p role="status">Opening your saved chart…</p>}
  </main>;
  const restored = saved && restoreSavedProfiles(saved);
  return <ChartWorkspace offline premium initialUser={restored?.user} initialPartner={restored?.partner}
    initialSlot={restored?.initialSlot} initialChart={chart}
    onComputed={(user, partner, result, slot = 'user') => {
      if (!saveChartLocal(createWorkspaceSavedChart(user, partner, result, slot, saved?.isPaid ?? false))) throw new Error('Local storage unavailable');
    }} />;
}

